    # Assume the record stores field names in a list `self._field_names`
    # and values in a list `self._values` in the same order.
    field_names = getattr(self, "_field_names", None)
    values = getattr(self, "_values", None)

    if field_names is None or values is None:
        # If the expected attributes are missing, treat as empty record.
        return {}

    if not keys:
        # Return all fields
        return {name: values[i] for i, name in enumerate(field_names)}

    result = {}
    for key in keys:
        if isinstance(key, int):
            idx = key
            if idx < 0 or idx >= len(field_names):
                raise IndexError(f"Index {idx} out of bounds for record with "
                                 f"{len(field_names)} fields")
            name = field_names[idx]
            result[name] = values[idx]
        else:
            # Treat as field name
            name = str(key)
            if name in field_names:
                idx = field_names.index(name)
                result[name] = values[idx]
            else:
                # Name not present in record; insert with None
                result[name] = None
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the instance stores a list of field names and a list of values
    if not hasattr(self, "_keys") or not hasattr(self, "_items"):
        raise AttributeError("Record must have '_keys' and '_items' attributes")
    result = {}
    # If no keys specified, return all
    if not keys:
        for name, value in zip(self._keys, self._items):
            result[name] = value
        return result
    for key in keys:
        # Handle numeric indexes (including negative indices)
        if isinstance(key, int) and not isinstance(key, bool):
            idx = key
            size = len(self._items)
            if idx < -size or idx >= size:
                raise IndexError(f"index {idx} is out of bounds")
            if idx < 0:
                idx = size + idx
            name = self._keys[idx]
            result[name] = self._items[idx]
        # Handle string field names
        elif isinstance(key, str):
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._items[idx]
            else:
                # Field name not present; insert None
                result[key] = None
        else:
            raise TypeError(f"keys must be integers or strings, got {type(key).__name__}")
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys provided, return the full dictionary.
    if not keys:
        return dict(zip(self._names, self._items))

    result = {}
    total = len(self._items)

    for key in keys:
        if isinstance(key, int):
            # Resolve negative indices like normal Python sequences.
            if key < 0:
                key = total + key
            if key < 0 or key >= total:
                raise IndexError(f"Index {key} is out of bounds for record of length {total}")
            result[self._names[key]] = self._items[key]
        elif isinstance(key, str):
            if key in self._names:
                idx = self._names.index(key)
                result[key] = self._items[idx]
            else:
                result[key] = None
        else:
            raise TypeError(f"Key must be an integer index or a string name, got {type(key).__name__}")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Basic type validation
    try:
        n = int(n)
    except Exception:
        raise ValueError("Parameter 'n' must be an integer")
    try:
        qid = int(qid)
    except Exception:
        raise ValueError("Parameter 'qid' must be an integer")

    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    if not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dict mapping types to callables")
    if not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dict mapping types to callables")

    # Build the message dictionary
    message = {
        "command": "DISCARD",
        "n": n,
        "qid": qid,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
    }

    # Attach any additional handlers provided
    if handlers:
        message["handlers"] = handlers

    # Append the message to the internal output queue
    try:
        self._output_queue.append(message)
    except AttributeError:
        raise RuntimeError("Output queue not initialized on this object")

    # Return a Response object that will later invoke handlers when a response arrives
    try:
        return Response(*handlers.values())
    except Exception:
        # If Response construction fails, still return a basic placeholder
        return Response()

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate input types
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(qid, int):
        raise TypeError("qid must be an integer")
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    # Prepare message dictionary
    msg = {
        'type': 'DISCARD',
        'n': n,
        'qid': qid
    }

    # Apply dehydration hooks if any
    for key, value in msg.items():
        hook = dehydration_hooks.get(type(value))
        if hook is not None:
            try:
                msg[key] = hook(value)
            except Exception:
                # ignore hook failures, keep original value
                pass

    # Append the message to the outgoing queue
    # Assume self.output_queue is available and supports append
    if hasattr(self, 'output_queue') and hasattr(self.output_queue, 'append'):
        self.output_queue.append(msg)
    else:
        # Fallback: store in a list if output_queue not defined
        if not hasattr(self, '_tmp_output_queue'):
            self._tmp_output_queue = []
        self._tmp_output_queue.append(msg)

    # Create and return a Response object if available
    try:
        result = Response(msg, **handlers)
    except NameError:
        result = None

    return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is None:
        mode = "WRITE"
    else:
        mode = mode.upper()
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")

    # Validate bookmarks
    if bookmarks is None:
        bookmarks = []
    else:
        try:
            bookmarks = list(bookmarks)
        except TypeError:
            raise ValueError("bookmarks must be an iterable of bookmark values")

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("metadata must be a dictionary")

    # Validate hooks
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dict")
    for key, hook in dehydration_hooks.items():
        if not callable(hook):
            raise ValueError(f"dehydration hook for {key!r} is not callable")

    if hydration_hooks is None:
        hydration_hooks = {}
    if not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dict")
    for key, hook in hydration_hooks.items():
        if not callable(hook):
            raise ValueError(f"hydration hook for {key!r} is not callable")

    # Build the BEGIN message payload
    begin_msg = {
        "mode": mode,
        "bookmarks": bookmarks,
        "metadata": metadata or {},
        "timeout": timeout,
        "db": db,
        "imp_user": imp_user,
    }

    # Apply dehydration hooks to the payload before sending
    for key, hook in dehydration_hooks.items():
        if key in begin_msg:
            begin_msg[key] = hook(begin_msg[key])

    # Apply hydration hooks to the payload after sending (if needed)
    # Heuristic: only on metadata portion
    if hydration_hooks and "metadata" in begin_msg:
        for key, hook in hydration_hooks.items():
            if isinstance(begin_msg["metadata"], dict):
                for k, v in list(begin_msg["metadata"].items()):
                    if isinstance(v, key):
                        begin_msg["metadata"][k] = hook(v)

    # Append to the outgoing message queue; assume self._outgoing exists
    try:
        self._outgoing.append(begin_msg)  # pragma: no cover
    except AttributeError:
        # Fallback: if _outgoing not defined, just ignore queueing for demo
        pass

    # Return a Response object; assume a Response class is available in context
    # Pass the message and handlers to the Response constructor
    if 'Response' in globals():
        return Response(begin_msg, **handlers)
    # If Response is not defined, raise a descriptive error
    raise RuntimeError("Response class is not defined in the current context")

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """Append a BEGIN message to the output queue.

    Args:
        mode: access mode for routing - ``"READ"`` or ``"WRITE"`` (default).
        bookmarks: iterable of bookmark values after which this transaction
            should begin.
        metadata: custom metadata dictionary to attach to the transaction.
        timeout: timeout for transaction execution (seconds).
        db: name of the database against which to begin the transaction
            (requires Bolt 4.0+).
        imp_user: the user to impersonate (requires Bolt 4.4+).
        dehydration_hooks: mapping from type (class) to dehydration function.
        hydration_hooks: mapping from type (class) to hydration function.
        **handlers: handler functions passed into the returned Response object.

    Returns:
        Response: A Response object representing the transaction begin.

    Raises:
        ValueError: if any argument is invalid.
    """
    # Validate mode
    if mode is not None and mode not in {"READ", "WRITE"}:
        raise ValueError("mode must be 'READ' or 'WRITE'")

    # Validate bookmarks
    if bookmarks is not None:
        try:
            iter(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable")

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict")

    # Ensure hooks are dicts
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    # Update session-level hooks (assumes these attributes exist)
    try:
        self._dehydration_hooks.update(dehydration_hooks)
        self._hydration_hooks.update(hydration_hooks)
    except AttributeError:
        # If the attributes are missing, create them
        self._dehydration_hooks = dehydration_hooks
        self._hydration_hooks = hydration_hooks

    # Build the arguments dictionary for the BEGIN record
    args = {}
    if mode is not None:
        args["mode"] = mode
    if bookmarks:
        args["bookmarks"] = list(bookmarks)
    if metadata:
        args["metadata"] = metadata
    if timeout is not None:
        args["timeout"] = timeout
    if db is not None:
        args["db"] = db
    if imp_user is not None:
        args["imp_user"] = imp_user

    # Create the message for the output queue
    try:
        message = self._message_factory.create_begin_message(args)
    except AttributeError:
        # Fallback if a message factory isn't available
        message = {"code": "BEGIN", "args": args}

    # Append the message to the output queue
    if hasattr(self, "_output_queue"):
        self._output_queue.append(message)
    else:
        # If a queue attribute does not exist, create it and push
        self._output_queue = [message]

    # Construct and return the Response object
    return self._response_factory.create_response(message, handlers=handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not isinstance(name, str) or not name.isidentifier():
        raise ValueError(f"Invalid class name: {name!r}")

    if not isinstance(fields, (list, tuple, set)):
        raise TypeError("fields must be an iterable of field names")
    field_names = []
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise ValueError(f"Invalid field name: {f!r}")
        if f in field_names:
            raise ValueError(f"Duplicate field name: {f!r}")
        field_names.append(f)

    try:
        from shapely.geometry import Point as BasePoint
    except Exception:
        BasePoint = object

    def _init(self, *args, srid=None, **kwargs):
        if len(args) > len(field_names):
            raise TypeError(
                f"Expected at most {len(field_names)} positional args, got {len(args)}"
            )
        for name, value in zip(field_names, args):
            setattr(self, name, value)
        for name, value in kwargs.items():
            if name == "srid":
                continue
            if name not in field_names:
                raise TypeError(f"Unexpected keyword argument: {name!r}")
            setattr(self, name, value)
        for name in field_names:
            if not hasattr(self, name):
                setattr(self, name, None)
        if srid is None and "srid" in kwargs:
            srid = kwargs["srid"]
        if srid is not None:
            try:
                self.srid = srid_map[srid]
            except Exception:
                self.srid = srid
        else:
            self.srid = None

    def _repr(self):
        parts = [f"{name}={getattr(self, name, None)!r}" for name in field_names]
        if hasattr(self, "srid") and self.srid is not None:
            parts.append(f"srid={self.srid!r}")
        return f"{name}({', '.join(parts)})"

    class_dict = {f: None for f in field_names}
    class_dict["_srid_map"] = srid_map
    class_dict["__init__"] = _init
    class_dict["__repr__"] = _repr
    return type(name, (BasePoint,), class_dict)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Basic validation of arguments
    if not isinstance(name, str):
        raise TypeError(f"name must be a str, got {type(name).__name__}")
    if not isinstance(fields, (list, tuple)):
        raise TypeError(f"fields must be a list or tuple, got {type(fields).__name__}")
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise ValueError(f"Field names must be valid identifiers, got {f!r}")

    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")

    # Prepare class attributes
    attrs = {}
    attrs['__slots__'] = tuple(fields)
    attrs['_srid_map'] = srid_map
    attrs['_field_names'] = tuple(fields)

    # Define the constructor
    def __init__(self, x, y, srid=None, **kwargs):
        # Call the base Point constructor
        super(klass, self).__init__(x, y)
        # Handle SRID
        if srid is None:
            self.srid = None
        elif srid in self._srid_map:
            self.srid = self._srid_map[srid]
        else:
            raise ValueError(f"SRID {srid!r} not found in srid_map")
        # Assign additional fields
        for field in self._field_names:
            setattr(self, field, kwargs.get(field))

    attrs['__init__'] = __init__

    # Define a simple representation that includes coordinates, SRID, and fields
    def __repr__(self):
        coord_repr = f"({self.x} {self.y})"
        srid_repr = f" srid={self.srid}" if getattr(self, "srid", None) is not None else ""
        fields_repr = " ".join(f"{f}={getattr(self, f)!r}" for f in self._field_names)
        return f"<{klass.__name__}{coord_repr}{srid_repr} {fields_repr}>"

    attrs['__repr__'] = __repr__

    # Attempt to use the real Point base class if available
    try:
        from shapely.geometry import Point as _BasePoint  # noqa: F401
    except Exception:
        # Fallback to a simple base that stores x and y
        class _BasePoint:
            __slots__ = ("x", "y")

            def __init__(self, x, y):
                self.x = x
                self.y = y

    # Define the new class
    klass = type(name, (_BasePoint,), attrs)

    return klass

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    def __init__(self, *coords, **kwargs):
        if len(coords) < len(fields):
            raise TypeError(f"Expected {len(fields)} coordinates, got {len(coords)}")
        self._coords = tuple(coords)
        self._srid = kwargs.get('srid', srid_map.get(fields[0]) if srid_map else None)

    def __repr__(self):
        parts = [f"{name}("]
        for f, c in zip(fields, self._coords):
            parts.append(f"{f}={c!r}")
        parts.append(")")
        return "".join(parts)

    # Prepare the dictionary of attributes for the new class.
    cls_attrs = {
        "__init__": __init__,
        "__repr__": __repr__,
        "_coords": None,   # initialized in __init__
        "_srid": None,
    }

    # Dynamically create a property for each field that retrieves the
    # corresponding coordinate from the internal tuple.
    for idx, f in enumerate(fields):
        cls_attrs[f] = property(lambda self, i=idx: self._coords[i])

    # Create and return the new class.
    return type(name, (object,), cls_attrs)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        if func.__doc__:
            wrapper.__doc__ = f"{func.__doc__}\n\nDeprecated: {message}"
        else:
            wrapper.__doc__ = f"Deprecated: {message}"
        return wrapper
    return decorator

