        def foo(x):
            pass

    """

    # Ensure we receive a callable to decorate
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Emit the deprecation warning when the function is called
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)

        return wrapper

    return decorator

