def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    import os

    if not isinstance(code, str):
        raise TypeError(f"_inline_r_setup expects a str, got {type(code).__name__}")

    try:
        prefix = "R_OPTION_"
        r_options = []

        for env_key, env_val in os.environ.items():
            if env_key.upper().startswith(prefix):
                option_name = env_key[len(prefix):].lower()
                # Try to interpret the value as a native R literal.
                # Booleans
                lowered = env_val.lower()
                if lowered == "true":
                    r_val = "TRUE"
                elif lowered == "false":
                    r_val = "FALSE"
                else:
                    # Numeric or string
                    try:
                        # If conversion to float succeeds, keep numeric representation
                        float(env_val)
                        r_val = env_val
                    except ValueError:
                        # Escape any double quotes in the string value
                        escaped = env_val.replace('"', r'\"')
                        r_val = f'"{escaped}"'
                r_options.append(f"options({option_name} = {r_val})")

        if r_options:
            header = "\n".join(r_options) + "\n"
            return header + code
        else:
            return code
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Failed to inline R setup: {exc}") from exc

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence of strings."""
    try:
        items = list(seq)
    except Exception as exc:
        raise TypeError("seq must be a sequence-like object") from exc
    if not all(isinstance(item, str) for item in items):
        raise TypeError("seq must contain only strings")
    from random import Random
    rng = Random(0)  # fixed seed for deterministic behavior
    rng.shuffle(items)
    return items

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    parts = []
    for part in s.split("."):
        if part == "":
            continue
        try:
            parts.append(int(part))
        except ValueError:
            m = re.match(r"^(\d+)", part)
            if m:
                parts.append(int(m.group(1)))
            else:
                raise ValueError(f"Invalid numeric component in version: {part!r}")
    if not parts:
        raise ValueError(f"Empty or invalid version string: {s!r}")
    return tuple(parts)

