def _reset_logging(cls):
    """
    Reset logging configuration to defaults.
    """
    try:
        root = logging.getLogger()
        # Remove and close all handlers
        handlers = root.handlers[:]
        for h in handlers:
            try:
                h.flush()
            except Exception:
                pass
            try:
                h.close()
            except Exception:
                pass
            root.removeHandler(h)
        # Reset root level to WARNING
        root.setLevel(logging.WARNING)
    except Exception as e:
        # Attempt to log the failure, fallback to print if logger not ready
        try:
            logging.getLogger().error("Failed to reset logging: %s", e)
        except Exception:
            print(f"Failed to reset logging: {e}")

def _reset_logging(cls):
        """
        Reset logging configuration to a clean default state.
        Removes all handlers from the root logger, restores the default
        logging level, and reattaches a simple StreamHandler.
        """
        try:
            import logging
            root = logging.getLogger()
            # Remove existing handlers
            for handler in root.handlers[:]:
                try:
                    root.removeHandler(handler)
                    if hasattr(handler, "close"):
                        handler.close()
                except Exception as e:
                    # If a handler cannot be closed, log a warning and continue
                    logging.getLogger(cls.__name__).warning(
                        "Failed to close handler %s: %s", handler, e
                    )
            # Reset level to WARNING (default)
            root.setLevel(logging.WARNING)
            # Reattach default StreamHandler if no handlers remain
            if not root.handlers:
                stream_handler = logging.StreamHandler()
                stream_handler.setLevel(logging.WARNING)
                stream_formatter = logging.Formatter(
                    "%(asctime)s - %(levelname)s - %(message)s"
                )
                stream_handler.setFormatter(stream_formatter)
                root.addHandler(stream_handler)
        except Exception as general_err:
            # Use a fallback logger if logging itself fails
            try:
                logging.getLogger(cls.__name__).error(
                    "Unexpected error during logging reset: %s", general_err
                )
            except Exception:
                # If logging is completely broken, silently pass
                pass

