    try:
        log_mod = __import__("logging")
    except Exception:
        return  # logging module not available, nothing to reset
    try:
        root = log_mod.getLogger()
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        log_mod.basicConfig()
    except Exception as exc:
        # Fallback: silently ignore or print error for visibility
        print(f"Failed to reset logging: {exc}")

