            if other is cls:
                continue
            # If cls is a subclass of another, it's redundant
            try:
                if issubclass(cls, other):
                    redundant = True
                    break
            except TypeError:
                # Should not happen because we verified class types
                continue
        if not redundant:
            result.append(cls)
            seen.add(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of types")
    minimal = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"expected type, got {type(cls).__name__}")
        # Skip duplicates already included
        if any(cls is existing for existing in minimal):
            continue
        # Skip if this class is a subclass of one already in the list
        if any(issubclass(cls, existing) for existing in minimal):
            continue
        minimal.append(cls)
    return minimal

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.

    The returned list contains only those classes that are not superclasses
    of any other class in the original list.  The order of the first
    occurrence of each such class is preserved.

    :param classes: iterable of classes (must be type objects)
    :returns: list of minimal base classes
    """
    if classes is None:
        raise TypeError("classes must not be None")
    try:
        iterable = list(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of types") from None

    minimal = []
    seen = set()
    for cls in iterable:
        if not isinstance(cls, type):
            raise TypeError(f"all items must be types, got {type(cls).__name__}")
        if cls in seen:
            continue
        # determine if cls is a superclass of any other class in iterable
        is_super = False
        for other in iterable:
            if other is cls:
                continue
            if isinstance(other, type) and issubclass(other, cls):
                is_super = True
                break
        if not is_super:
            minimal.append(cls)
        seen.add(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of class objects")

    # Preserve order and remove duplicates
    unique = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"{cls!r} is not a class")
        if cls not in seen:
            seen.add(cls)
            unique.append(cls)

    # Keep only classes that are not ancestors of any other in the list
    minimal = []
    for cls in unique:
        # Skip if some other class is a subclass of this one
        if any(issubclass(other, cls) and other is not cls for other in unique):
            continue
        minimal.append(cls)

    return minimal

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    The function removes any class that is a subclass of another
    in the list while preserving the original order of the remaining
    classes. Each element must be a class type; otherwise a TypeError
    is raised.
    """
    if classes is None:
        return list()
    try:
        iter(classes)
    except TypeError as e:
        raise TypeError("minimalBases expects an iterable of classes") from e

    minimal = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Element {cls!r} is not a class")
        # Skip if already covered by an existing class in `minimal`
        redundant = False
        for existing in minimal:
            try:
                if issubclass(cls, existing):
                    redundant = True
                    break
            except TypeError:
                # In case issubclass itself fails, treat as not redundant
                continue
        if redundant:
            continue

        # Remove any classes in `minimal` that are subclasses of the new `cls`
        new_minimal = []
        for existing in minimal:
            try:
                if not issubclass(existing, cls):
                    new_minimal.append(existing)
            except TypeError:
                # Keep the existing class if issubclass fails
                new_minimal.append(existing)
        new_minimal.append(cls)
        minimal = new_minimal

    return minimal

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    try:
        attrs = dir(self)
    except Exception:
        # In the unlikely event that dir fails, return an empty mapping
        return result

    for name in attrs:
        if not all and name.startswith('_'):
            # Skip private/internal attributes when `all` is False
            continue
        try:
            attr = getattr(self, name)
            if callable(attr):
                desc = attr.__doc__
            else:
                # Try to get the docstring from the attribute's type
                desc = getattr(type(attr), '__doc__', None)
        except Exception:
            # If attribute access raises any exception, record None as description
            desc = None
        result[name] = desc
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attribute names defined on the instance
    attrs = set()
    try:
        instance_attrs = getattr(self, "__dict__", {})
        for key in instance_attrs:
            if not key.startswith("_"):
                attrs.add(key)
    except Exception:
        # If accessing instance __dict__ fails, ignore and continue
        pass

    # Collect attribute names defined on the class that are not callables
    try:
        class_attrs = getattr(self.__class__, "__dict__", {})
        for key, val in class_attrs.items():
            if not key.startswith("_") and not callable(val):
                attrs.add(key)
    except Exception:
        # If accessing class __dict__ fails, ignore and continue
        pass

    # Return the attributes in a deterministic order
    if all:
        return sorted(attrs)
    # If ``all`` is False, filter out callables (methods/functions)
    return sorted([name for name in attrs if not callable(getattr(self, name, None))])

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a Boolean value")

    # Use the method resolution order (MRO) if all=True to include inherited
    classes = self.__class__.mro() if all else [self.__class__]

    names = []
    for cls in classes:
        for key, value in cls.__dict__.items():
            # Skip private and special attributes
            if key.startswith('_'):
                continue
            # Skip callables (methods, functions, etc.)
            if callable(value):
                continue
            if key not in names:
                names.append(key)

    return sorted(names)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect names defined in this interface's own namespace
    def _collect(cls):
        return {
            name
            for name, value in vars(cls).items()
            if not name.startswith("_") and not callable(value)
        }

    collected = _collect(self.__class__)

    if all:
        # Include attributes from all direct base classes that are also interface types
        for base in reversed(self.__class__.__mro__):
            if base is self.__class__ or base is object:
                continue
            collected.update(_collect(base))

    return sorted(collected)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, "__bases__", ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

