def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If sequence is a class with a base named 'Broken', return it directly
    try:
        bases = getattr(sequence, "__bases__", ())
        if any(base.__name__ == "Broken" for base in bases):
            return [sequence]
    except Exception:
        pass

    # Check if the sequence itself is an interface declaration
    # (look for 'InterfaceClass' or 'Implements' in its MRO)
    try:
        mro = getattr(sequence, "__mro__", ())
        for base in mro:
            name = getattr(base, "__name__", None)
            if name in ("InterfaceClass", "Implements"):
                output.append(sequence)
                return output
    except Exception:
        pass

    # If sequence is iterable but not a string, iterate over its items
    # otherwise treat it as a single interface declaration
    if isinstance(sequence, (list, tuple, set)):
        for item in sequence:
            _normalizeargs(item, output)
    elif hasattr(sequence, "__iter__") and not isinstance(sequence, (str, bytes)):
        for item in sequence:
            _normalizeargs(item, output)
    else:
        # Treat as a single declaration
        output.append(sequence)

    return output

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import importlib
        return importlib.import_module("c_optimizations")
    except ImportError:
        return False

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    try:
        # If the required method exists, invert its result
        return not self._c_optimizations_required()
    except AttributeError:
        # The required method is not defined on this instance
        raise AttributeError(
            "Method `_c_optimizations_required` not found on this object."
        )
    except Exception as exc:
        # Any other error is propagated as a runtime error for clarity
        raise RuntimeError(
            f"Error evaluating `_c_optimizations_required`: {exc}"
        )

