def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context to an empty dictionary.  Handle missing attribute gracefully.
    try:
        self.context = {}
    except AttributeError:
        self.context = {}

    # Reinitialize bins based on the initialization strategy.
    # Priority: use `initial_value` if it is defined and not None,
    # otherwise fall back to calling `make_bins` (if available).
    try:
        # If bins already exist, preserve their length when resetting.
        if hasattr(self, "bins"):
            bin_len = len(self.bins)
        else:
            bin_len = None

        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Use the predefined initial value for every bin.
            if bin_len is not None:
                self.bins = [self.initial_value] * bin_len
            else:
                self.bins = [self.initial_value]
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            # Delegate bin creation to the user-provided method.
            self.bins = self.make_bins()
    except Exception:
        # If any unexpected issue occurs, silently ignore to keep method robust.
        pass

def reset(self):
        """
        Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context dictionary
        try:
            self.context = {}
        except AttributeError:
            # if the histogram has no context attribute, ignore
            pass

        # Reinitialize the bins
        try:
            initial_value = getattr(self, "initial_value", None)
        except Exception:
            initial_value = None

        # If an initial value is defined, set all existing bins to that value
        if initial_value is not None:
            try:
                # Preserve the current bin structure if possible
                if hasattr(self, "bins") and isinstance(self.bins, list):
                    self.bins = [initial_value for _ in self.bins]
                elif hasattr(self, "nbins") and hasattr(self, "make_bins"):
                    self.bins = [initial_value for _ in range(self.nbins)]
                else:
                    # No bin structure; create a minimal list
                    self.bins = [initial_value]
            except Exception:
                self.bins = [initial_value]
        else:
            # No initial value; use the make_bins() method if available
            try:
                if hasattr(self, "make_bins"):
                    self.bins = self.make_bins()
                else:
                    # Fallback: create an empty list
                    self.bins = []
            except Exception:
                self.bins = []

def reset(self):
