    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context
    self.context = {}
    # Reinitialize bins
    try:
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # If we already have bins stored, fill them with the initial value
            if hasattr(self, "bins"):
                self.bins = [self.initial_value] * len(self.bins)
            elif hasattr(self, "counts"):
                self.counts = [self.initial_value] * len(self.counts)
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            # Use the make_bins method to regenerate bins
            self.bins = self.make_bins()
        else:
            # Fallback: simply set bins to an empty list
            self.bins = []
    except Exception:
        # Ensure the histogram is still usable even if an error occurs
        self.bins = []

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    output_lines = []
    if header is not None:
        output_lines.append(str(header))

    for point in self:
        try:
            coord, value = point
        except Exception:
            # If the point does not provide exactly two elements,
            # skip it to avoid crashes during export.
            continue

        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord)

        if isinstance(value, (list, tuple)):
            value_str = separator.join(map(str, value))
        else:
            value_str = str(value)

        output_lines.append(f"{coord_str}{separator}{value_str}")

    return "\n".join(output_lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        # Attempt to get from a coordinate object's error_indices attribute.
        if hasattr(self, "coords") and isinstance(self.coords, dict):
            coord_obj = self.coords.get(coord_name)
            if coord_obj is not None and hasattr(coord_obj, "error_indices"):
                return list(coord_obj.error_indices)

        # Fallback to a dictionary of error indices stored on the object.
        if hasattr(self, "err_indices") and isinstance(self.err_indices, dict):
            indices = self.err_indices.get(coord_name)
            if indices is not None:
                return list(indices)

        # If no explicit storage for this coordinate, return empty list.
        return []
    except Exception:
        # In case of any unexpected errors, return an empty list to avoid breaking caller logic.
        return []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Attempt to retrieve error data stored in typical attributes.
    err_dict = getattr(self, "_err_dict", None) or getattr(self, "_err_data", None)
    if err_dict is None or not isinstance(err_dict, dict):
        # No container for error data; assume no indices.
        return []
    err_obj = err_dict.get(coord_name)
    if err_obj is None:
        return []
    try:
        import numpy as _np
        err_arr = _np.asarray(err_obj)
    except Exception:
        # Non-array-like error object; cannot determine indices.
        return []
    if err_arr.ndim == 0:
        # Scalar error: return [0] if it is a valid number.
        return [0] if not _np.isnan(err_arr) else []
    # Flatten in case of multi-dimensional error arrays.
    flattened = err_arr.ravel()
    # Find indices where error is not NaN.
    mask = ~_np.isnan(flattened)
    return _np.where(mask)[0].tolist()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure coordinate error mapping exists
    if not hasattr(self, "err_coords"):
        raise AttributeError("The object has no attribute 'err_coords'.")
    if coord_name not in self.err_coords:
        raise KeyError(f"Coordinate {coord_name!r} has no associated error data.")
    err = self.err_coords[coord_name]
    if err is None:
        return []
    # Convert to NumPy array for reliable indexing
    try:
        err_arr = np.asarray(err)
    except Exception as exc:
        raise TypeError(f"Error data for {coord_name!r} could not be converted to an array: {exc}") from exc
    # Only 1‑D arrays are supported for error tracks
    if err_arr.ndim != 1:
        raise ValueError(f"Error data for {coord_name!r} must be 1‑D, got shape {err_arr.shape}.")
    # Return indices where an error value exists (i.e. is not NaN)
    return list(np.where(~np.isnan(err_arr))[0])

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate inputs
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Ensure that the object has the expected attribute
    if not hasattr(self, "errors"):
        raise AttributeError("The object has no attribute 'errors' to query error indices")

    errors = getattr(self, "errors")

    if not isinstance(errors, dict):
        raise TypeError("self.errors must be a dictionary mapping coord names to indices")

    # Retrieve the indices for the requested coordinate
    indices = errors.get(coord_name, [])

    # Convert to a plain Python list for consistency
    if indices is None:
        return []
    try:
        return list(indices)
    except Exception:
        # If the indices are a scalar value, wrap it in a list
        return [indices]

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Attempt to retrieve error indices dictionary
    err_dict = getattr(self, "err_indices", None)
    if err_dict is None:
        return []
    # Return a list of indices; handle missing key gracefully
    try:
        val = err_dict[coord_name]
    except KeyError:
        return []
    # Ensure the result is a list (or iterable)
    if isinstance(val, (list, tuple, set)):
        return list(val)
    else:
        return [val]

def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert bins to ndarray to allow vectorized operations
    bins = np.asarray(bins)

    # Prepare widths from edges
    if isinstance(edges, (list, tuple)):
        try:
            widths = [np.diff(np.asarray(e)) for e in edges]
        except Exception as exc:
            raise ValueError(f"Each element in edges must be 1‑D numeric-like. Got {edges}") from exc
    else:
        try:
            widths = [np.diff(np.asarray(edges))]
        except Exception as exc:
            raise ValueError(f"Edges must be 1‑D numeric-like array. Got {edges}") from exc

    # Calculate the product of bin widths for each bin (product over all dimensions)
    if len(widths) == 1:
        # 1‑D histogram
        bin_widths = widths[0]
    else:
        # ND histogram – compute outer product of widths
        try:
            grid = np.meshgrid(*widths, indexing='ij')
            bin_widths = np.multiply.reduce(grid)
        except Exception as exc:
            raise ValueError("Failed to compute widths product from edges.") from exc

    # Check that the resulting width array can be broadcasted with bins
    try:
        product = bins * bin_widths
    except ValueError as exc:
        raise ValueError(f"Shape mismatch between bins {bins.shape} and edge widths {bin_widths.shape}") from exc

    # Return the integral as a scalar
    return np.sum(product)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # convert inputs to numpy arrays
    try:
        b = np.asarray(bins, dtype=float)
        e = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise TypeError("bins and edges must be array-like numeric") from exc

    # basic sanity checks
    if b.size == 0:
        return 0.0

    if e.shape != tuple([b.size + 1]) and not (e.ndim == 1 and e.size == b.size + 1):
        raise ValueError(f"edges must have length len(bins)+1, got {e.shape} and {b.shape}")

    # compute bin widths
    widths = np.diff(e)

    # compute integral as sum of bin values times their widths
    try:
        result = np.sum(b * widths)
    except Exception as exc:
        raise ValueError("Failed to compute integral due to incompatible shapes or types") from exc

    return float(result)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Import numpy lazily
    try:
        import numpy as np
    except ImportError as exc:
        raise ImportError("NumPy is required for integral calculation.") from exc

    # Ensure bins and edges are numpy arrays
    bins_arr = np.asarray(bins)
    # If edges is a single array-like, wrap it in list
    if isinstance(edges, (np.ndarray, list, tuple)):
        if isinstance(edges, np.ndarray):
            # If 1D, treat as single edge array
            if edges.ndim == 1:
                edge_list = [edges]
            else:
                # For multi-dimensional maybe passed as list of arrays
                edge_list = list(edges)
        else:
            edge_list = list(edges)
    else:
        raise TypeError("edges must be an array-like object or sequence of arrays")

    # Compute widths (bin volumes) for each dimension
    widths = []
    for e in edge_list:
        e_arr = np.asarray(e)
        if e_arr.ndim != 1:
            raise ValueError("Each edge array must be one-dimensional.")
        if e_arr.size < 2:
            raise ValueError("Edge arrays must contain at least two points.")
        w = np.diff(e_arr)
        widths.append(w)

    # Compute bin volume grid matching bins shape
    # Start with first dimension widths
    vol = widths[0]
    for w in widths[1:]:
        # Compute outer product and reshape to match increasing dimensions
        vol = np.multiply.outer(vol, w)
    # Ensure vol shape equals bins_arr.shape
    if vol.shape != bins_arr.shape:
        raise ValueError(
            f"Shape mismatch: bin array shape {bins_arr.shape} "
            f"does not match computed volume shape {vol.shape}"
        )

    # Compute integral as sum of bin values times volume
    return np.sum(bins_arr * vol)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Handle single element
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, Source):
        return False

    # Avoid treating strings as iterables of characters
    if isinstance(seq, str):
        return False

    # Check common iterable types
    if isinstance(seq, (list, tuple, set, frozenset)):
        has_fill = False
        for item in seq:
            if isinstance(item, Source):
                return False
            if isinstance(item, FillRequest):
                has_fill = True
        return has_fill

    # Generic iterable fallback
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    has_fill = False
    for item in iterator:
        if isinstance(item, Source):
            return False
        if isinstance(item, FillRequest):
            has_fill = True
    return has_fill

