def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Helper function that carries a depth counter.
    def _difference(a, b, cur_level):
        # no recursion allowed (cur_level == 0) or infinite recursion mode (cur_level == -1)
        result = {}
        for key, val in a.items():
            if key not in b:
                # key missing in b => include verbatim
                result[key] = val
            else:
                val_b = b[key]
                # Both sides are dicts and we are allowed to recurse
                if isinstance(val, dict) and isinstance(val_b, dict) and (cur_level > 0 or cur_level == -1):
                    # Determine next depth level
                    next_level = cur_level - 1 if cur_level > 0 else -1
                    subdiff = _difference(val, val_b, next_level)
                    if subdiff:
                        result[key] = subdiff
                else:
                    # At this depth we do not recurse into dicts,
                    # so simply compare values for inequality.
                    if val != val_b:
                        result[key] = val
        return result

    # Call the recursive helper with the requested depth
    return _difference(d1, d2, level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    def _diff(d1_local, d2_local, depth):
        if depth == 0:
            return {}
        res = {}
        for key, val1 in d1_local.items():
            if key not in d2_local:
                # Entire value is new
                if isinstance(val1, dict) and (depth != 1):
                    # Deep copy recursively according to remaining depth
                    res[key] = _diff(val1, {}, depth - 1 if depth > 0 else -1)
                else:
                    res[key] = val1
            else:
                val2 = d2_local[key]
                # Both are dictionaries: recurse
                if isinstance(val1, dict) and isinstance(val2, dict):
                    sub = _diff(val1, val2, depth - 1 if depth > 0 else -1)
                    if sub:
                        res[key] = sub
                else:
                    # Non-dict values
                    if depth == 1:
                        res[key] = val1
                    else:
                        if val1 != val2:
                            res[key] = val1
        return res

    return _diff(d1, d2, level if level != -1 else float('inf'))

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Helper that performs recursion.
    def _diff(d1_sub, d2_sub, cur_level):
        # cur_level may be -1 for infinite recursion
        out = {}
        for key, val1 in d1_sub.items():
            # If recursion depth exhausted, treat as leaf
            if cur_level == 0:
                if key not in d2_sub or val1 != d2_sub.get(key):
                    out[key] = val1
                continue

            if key not in d2_sub:
                out[key] = val1
                continue

            val2 = d2_sub[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                # Recursive case
                sub = _diff(val1, val2, cur_level - 1 if cur_level >= 0 else -1)
                if sub:      # Only include if differences found
                    out[key] = sub
            else:
                if val1 != val2:
                    out[key] = val1
        return out

    # Call helper with full depth
    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        # If either is not a dict, the entire d1 is returned
        return d1

    def _diff(a, b, lev):
        res = {}
        for k, v in a.items():
            if k not in b:
                # key absent in b: include whole value
                res[k] = v
            else:
                v2 = b[k]
                if isinstance(v, dict) and isinstance(v2, dict):
                    if lev == 1:
                        # At level 1, include the entire subdictionary
                        res[k] = v
                    elif lev == -1:
                        # Infinite recursion: recurse without decrement
                        sub = _diff(v, v2, lev)
                        if sub:
                            res[k] = sub
                    else:
                        # lev > 1: recurse with one level less
                        sub = _diff(v, v2, lev - 1)
                        if sub:
                            res[k] = sub
                else:
                    # Either non-dict or mismatched types
                    if v != v2:
                        res[k] = v
        return res

    # Start recursion with the specified level
    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        # Convert coordinate to numpy array and ensure iterable
        coord_arr = np.atleast_1d(coord)
        if coord_arr.ndim > 1:
            # flatten if higher dims but treat each row as a coordinate
            coord_arr = coord_arr.reshape(-1, coord_arr.shape[-1])
        # Determine histogram dimensionality
        if hasattr(self, 'edges'):
            # 1D histogram
            edges = np.asarray(self.edges)
            nbins = len(edges) - 1
            indices = np.searchsorted(edges, coord_arr, side='right') - 1
            # Validate indices
            if indices < 0 or indices >= nbins:
                return
            # Update bin
            if np.isscalar(weight):
                self.bins[indices] += weight
            else:
                self.bins[indices] += np.asarray(weight)
        elif hasattr(self, 'bin_edges'):
            # Multi‑dimensional histogram
            bin_edges = self.bin_edges  # list or array of edges per axis
            if isinstance(bin_edges, list):
                ndim = len(bin_edges)
            else:
                # Assume extended edges shape (ndim, nbins+1)
                ndim, _ = bin_edges.shape
            # Ensure coordinate has correct shape
            if coord_arr.ndim == 1:
                coord_arr = coord_arr.reshape(1, -1)
            ncoord = coord_arr.shape[0]
            indices = []
            for d in range(ndim):
                edges = np.asarray(bin_edges[d]) if isinstance(bin_edges, list) else bin_edges[d]
                nbins = len(edges) - 1
                idx = np.searchsorted(edges, coord_arr[:, d], side='right') - 1
                if np.any(idx < 0) or np.any(idx >= nbins):
                    return  # coordinate outside histogram bounds
                indices.append(idx)
            # Convert to tuples for indexing
            indices_tuples = np.array(indices).T
            for idx_tuple in indices_tuples:
                if np.isscalar(weight):
                    self.bins[tuple(idx_tuple)] += weight
                else:
                    self.bins[tuple(idx_tuple)] += np.asarray(weight)
        else:
            raise AttributeError("Histogram object does not contain 'edges' attribute.")
    except Exception as exc:
        # Log error and re‑raise for debugging
        logger = getattr(self, 'logger', None)
        if logger:
            logger.error(f"Error filling histogram at {coord} with weight {weight}: {exc}")
        raise ValueError(f"Failed to fill histogram: {exc}")

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.
    Coordinates outside the histogram edges are ignored.
    """
    # Convert coordinate to float and validate
    try:
        value = float(coord)
    except Exception as exc:
        raise TypeError(f"coord must be a scalar numeric value, got {type(coord)}") from exc

    if not np.isfinite(value):
        # ignore NaNs or infinities
        return

    # Ensure the histogram edges are sorted ascending
    if not np.all(np.diff(self.edges) > 0):
        raise RuntimeError("Histogram edges must be strictly increasing")

    # Exclude points exactly equal to the rightmost edge
    if value == self.edges[-1]:
        return

    # Find the index of the bin that contains the value
    bin_idx = np.searchsorted(self.edges, value, side="right") - 1

    # If the value lies outside the range, ignore it
    if bin_idx < 0 or bin_idx >= self.values.size:
        return

    # Convert weight to float and validate
    try:
        w = float(weight)
    except Exception as exc:
        raise TypeError(f"weight must be a scalar numeric value, got {type(weight)}") from exc

    # Add the weight to the bin count
    try:
        self.values[bin_idx] += w
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram bin: {exc}") from exc
    return None

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    messages = []

    # Example regex for label keys: start with letter/underscore, follow by word chars
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for key, val in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
        else:
            # For bytes, decode using utf-8 if possible; otherwise skip regex check
            try:
                key_str = key.decode('utf-8') if isinstance(key, bytes) else key
                if not key_pattern.match(key_str):
                    messages.append(
                        {
                            repr(key_str): f"Label key '{key_str}' does not match the regex {key_pattern.pattern}"
                        }
                    )
            except Exception:
                # If decoding fails, consider it invalid
                messages.append({repr(key): 'expected string or bytes-like object'})

        # Validate value(s)
        if isinstance(val, list):
            for item in val:
                if not isinstance(item, (str, bytes)):
                    messages.append({repr(item): 'expected string or bytes-like object'})
                else:
                    # Optional: validate string items against a pattern
                    pass
        else:
            if not isinstance(val, (str, bytes)):
                messages.append({repr(val): 'expected string or bytes-like object'})

    if messages:
        raise ValidationError(messages)

