    # Ensure there is a dictionary to hold observer schemas
    if not hasattr(app.spec, "observer_schemas"):
        app.spec.observer_schemas = {}

    for resource in app.spec.manifest:
        try:
            kind = resource.get("kind")
            metadata = resource.get("metadata", {})
            name = metadata.get("name")
            namespace = metadata.get("namespace", "default")
            key = f"{kind}/{namespace}/{name}"
        except Exception:
            # Skip malformed entries; be tolerant and continue
            continue

        # Skip if a custom schema has already been provided
        if key in app.spec.observer_schemas:
            continue

        # Construct a very simple default schema that echoes the resource
        # This can be extended with more sophisticated defaults if needed
        default_schema = {
            "api_version": resource.get("apiVersion", ""),
            "kind": kind,
            "metadata": {
                "name": name,
                "namespace": namespace,
            },
            "spec": {},
        }

        app.spec.observer_schemas[key] = default_schema

