def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Collect any digests that are referenced in the manifest but not present
        # or not marked as used.
        missing = []
        unused = []

        # Normalise digests_used to a set for fast lookup
        try:
            used_set = set(digests_used)
        except Exception:
            used_set = set()

        # Determine the structure of `manifest_files`.  It could be:
        #   - a list of dicts with a 'digest' key
        #   - a list of objects that expose a .digest attribute
        #   - a dict mapping filepaths to digests
        for item in manifest_files:
            try:
                if isinstance(item, dict):
                    digest = item.get("digest") or item.get("sha256")
                else:
                    digest = getattr(item, "digest", None)
            except Exception:
                continue

            if not digest:
                continue

            # Check that the digest is present in the analyzed files mapping
            # (assuming the object has an `analyzed_files` attribute that stores digests
            #  of files already processed).  If the attribute does not exist, default
            #  to empty mapping.
            if not hasattr(self, "analyzed_files"):
                available = set()
            else:
                available = set(self.analyzed_files.get(digest, []))

            if not available:
                missing.append(digest)

            # Check that the digest is used somewhere in the analysis
            if digest not in used_set:
                unused.append(digest)

        if missing:
            raise ValueError(
                f"{len(missing)} digests referenced in the manifest were not found "
                f"in the analyzed files: {missing}"
            )
        if unused:
            raise ValueError(
                f"{len(unused)} digests are present in the analysis but not marked "
                f"as used: {unused}"
            )

        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None or digest_used is None:
        raise ValueError("Both manifest_files and digests_used must be provided")
    # Determine the set of digests recorded in the manifest.
    if isinstance(manifest_files, dict):
        manifest_digests = set(manifest_files.keys())
    else:
        manifest_digests = set()
        for entry in manifest_files:
            try:
                if isinstance(entry, dict):
                    manifest_digests.add(entry["digest"])
                else:
                    manifest_digests.add(entry.digest)
            except Exception as exc:
                raise ValueError(f"Manifest entry does not provide a digest: {entry}") from exc
    # Ensure digests_used is iterable
    try:
        used_digests = set(digests_used)
    except Exception as exc:
        raise ValueError("digests_used must be an iterable type") from exc
    # Digests that exist in the manifest but are not used
    missing_in_use = manifest_digests - used_digests
    # Digests that are used but not present in the manifest
    missing_in_manifest = used_digests - manifest_digests
    if missing_in_use:
        missing_string = ", ".join(sorted(missing_in_use))
        raise ValueError(f"The following manifest digests are not used: {missing_string}")
    if missing_in_manifest:
        missing_string = ", ".join(sorted(missing_in_manifest))
        raise ValueError(f"The following used digests are missing from the manifest: {missing_string}")
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Determine the set of digests present in the manifest
    if isinstance(manifest_files, dict):
        manifest_digests = set(manifest_files.keys())
    else:
        try:
