    # Digests that are required but missing from the manifest
    missing = digests_used - manifest_digests
    if missing:
        raise ValueError(f"Missing required digests in manifest: {', '.join(sorted(missing))}")

    # Digests that are present in the manifest but not needed
    unused = manifest_digests - digests_used
