    for attr in ("inventory", "version"):
        if not hasattr(prior, attr):
            raise TypeError(f"prior must have a '{attr}' attribute, got {type(prior).__name__}")

    # Compare inventories: they should have the same structure and values
    try:
        if isinstance(self.inventory, dict) and isinstance(prior.inventory, dict):
            # Check that all keys are identical
            if set(self.inventory.keys()) != set(prior.inventory.keys()):
                raise ValueError("Prior inventory keys differ from current inventory")
            # For each matching key, the stored objects should be equal
            for key in self.inventory:
                if self.inventory[key] != prior.inventory[key]:
                    raise ValueError(f"Prior inventory value for key '{key}' differs from current inventory")
        else:
            # Fallback: compare the __dict__ of the inventory objects
            if self.inventory.__dict__ != prior.inventory.__dict__:
                raise ValueError("Prior inventory does not match current inventory")
    except Exception as exc:
        # Emit a clearer message on failure
        raise ValueError(f"Inventory mismatch between current and prior: {exc}") from None

    # Version comparison: prior's version must be strictly older or equal
    if hasattr(self, "version"):
        if prior.version > self.version:
            raise ValueError(f"Prior version ({prior.version}) cannot be newer than current version ({self.version})")
    else:
        # If current object doesn't have a version attribute, we cannot enforce this rule,
        # but we still issue a warning for consistency.
        import warnings
        warnings.warn("Current object has no 'version' attribute; cannot validate version ordering.", RuntimeWarning)

    # All checks passed
    return True

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is an instance of the same class
        if not isinstance(prior, type(self)):
            raise TypeError(f"prior must be an InventoryValidator instance, got {type(prior)!r}")

        # Attributes that are not relevant for a strict comparison
        ignore_attrs = {
            "_internal_state",
            "validation_cache",
            "timestamp",
            "history",
            "_validation_errors",
            "_validation_history",
        }

        # Compare all attributes of `prior` with the current inventory
        for key, val in prior.__dict__.items():
            if key in ignore_attrs or key.startswith("_"):
                continue
            if not hasattr(self, key):
                raise ValueError(
                    f"Current inventory is missing attribute {key!r} expected from prior"
                )
            curr_val = getattr(self, key)

            # For iterables we want an equality check that works with list/tuple/set
            if isinstance(val, (list, tuple, set)):
                if curr_val != val:
                    raise ValueError(
                        f"Attribute {key!r} differs between current inventory and prior"
                    )
            else:
                if curr_val != val:
                    raise ValueError(
                        f"Attribute {key!r} differs between current inventory and prior"
                    )

        # If a version or timestamp attribute exists, ensure that the current
        # inventory is newer than the prior one.
        if hasattr(self, "version") and hasattr(prior, "version"):
            if self.version <= prior.version:
                raise ValueError(
                    "Current inventory must be a newer version than prior"
                )
        if hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
            try:
                current_ts = float(self.timestamp)
                prior_ts = float(prior.timestamp)
                if current_ts <= prior_ts:
                    raise ValueError(
                        "Current inventory must have a later timestamp than prior"
                    )
            except (TypeError, ValueError):
                # Ignore if timestamp cannot be compared
                pass

        # If all checks pass, the method completes silently
        return None

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, type(self)):
            raise TypeError(
                f"prior must be an instance of {type(self).__name__}, "
                f"got {type(prior).__name__}"
            )

        errors = []

        # Helper to extract a unique identifier for each item
        def _names(items):
            return {
                getattr(item, "name", str(item)).lower()
                for item in items
                if item is not None
            }

        # Compare species
        self_species = getattr(self, "species", [])
        prior_species = getattr(prior, "species", [])
        if prior_species:
            missing = _names(prior_species) - _names(self_species)
            if missing:
                errors.append(
                    f"Prior inventory contains species {missing} "
                    "that are not present in the current inventory"
                )

        # Compare parameters
        self_params = getattr(self, "parameters", [])
        prior_params = getattr(prior, "parameters", [])
        if prior_params:
            missing = _names(prior_params) - _names(self_params)
            if missing:
                errors.append(
                    f"Prior inventory contains parameters {missing} "
                    "that are not present in the current inventory"
                )

        # Compare constants
        self_constants = getattr(self, "constants", [])
        prior_constants = getattr(prior, "constants", [])
        if prior_constants:
            missing = _names(prior_constants) - _names(self_constants)
            if missing:
                errors.append(
                    f"Prior inventory contains constants {missing} "
                    "that are not present in the current inventory"
                )

        # Compare shape consistency for numpy arrays and other sequences
        def _check_shape_consistency(attr):
            self_items = getattr(self, attr, [])
            prior_items = getattr(prior, attr, [])
            for prior_item in prior_items:
                name = getattr(prior_item, "name", str(prior_item))
                self_item = next(
                    (x for x in self_items if getattr(x, "name", str(x)) == name), None
                )
                if self_item is None:
                    continue
                if hasattr(self_item, "shape") and hasattr(prior_item, "shape"):
                    if self_item.shape != prior_item.shape:
                        errors.append(
                            f"Inconsistent shape for {name} in {attr}: "
                            f"{self_item.shape} (current) vs {prior_item.shape} (prior)"
                        )
            return

        for attribute in ("species", "parameters", "constants"):
            _check_shape_consistency(attribute)

        if errors:
            raise ValueError("Prior inventory validation errors:\n" + "\n".join(errors))

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    import re

    def _parse_version(v):
        """Parse a version string into comparable parts."""
        parts = []
        # Split on any sequence of non-digit characters
        for part in re.split(r'\D+', v):
            if part.isdigit():
                parts.append(int(part))
        return parts

    def _compare_versions(v1, v2):
        """Return -1 if v1 < v2, 0 if equal, 1 if v1 > v2."""
        p1 = _parse_version(v1)
        p2 = _parse_version(v2)
        # Compare element-wise
        for a, b in zip(p1, p2):
            if a < b:
                return -1
            if a > b:
                return 1
        # If all matched so far, longer version is greater
        if len(p1) < len(p2):
            return -1
        if len(p1) > len(p2):
            return 1
        return 0

    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a mapping of logical paths")
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    result = {}
    for logical_path, version_map in inventory.items():
        if not isinstance(version_map, dict):
            continue  # skip malformed entries
        files_set = set()
        for ver, content_files in version_map.items():
            try:
                comp = _compare_versions(ver, version)
            except Exception:
                # Skip versions that cannot be parsed
                continue
            if comp >= 0:  # ver is same or later than requested
                # Expect content_files to be an iterable of file paths
                if isinstance(content_files, (set, list, tuple)):
                    files_set.update(content_files)
                else:
                    files_set.add(content_files)
        if files_set:
            result[logical_path] = files_set

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in later
    versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary-like mapping of logical paths")
    if version is None:
        raise ValueError("version must be specified")

    ver_key = str(version)
    result = {}

    for logical_path, data in inventory.items():
        # Handle the most common case: mapping of version -> iterable of files
        if isinstance(data, dict):
            files = data.get(ver_key, data.get(ver_key.lower()))
            if files:
                try:
                    result[logical_path] = set(files)
                except TypeError:
                    # In case files is not an iterable, wrap it in a set
                    result[logical_path] = {files}

        # Handle legacy/alternate format: list of {version: files} tuples
        elif isinstance(data, (list, tuple)):
            for entry in data:
                if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                    entry_version, entry_files = entry[:2]
                    if str(entry_version) == ver_key:
                        files = entry_files
                        try:
                            if isinstance(files, (list, set, tuple)):
                                result.setdefault(logical_path, set()).update(files)
                            else:
                                result.setdefault(logical_path, set()).add(files)
                        except Exception:
                            # skip malformed entries but keep scanning
                            continue

        # Unsupported data structure: skip silently, but could log
        else:
            continue

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic input validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary of versions to state mappings")
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if version not in inventory:
        raise KeyError(f"Version '{version}' not found in inventory")

    # Retrieve the state mapping for the requested version
    state_map = inventory[version]
    if not isinstance(state_map, dict):
        raise TypeError(f"inventory['{version}'] must be a dictionary mapping logical paths to files")

    # Build result mapping, converting any iterable of files to a set
    result = {}
    for logical_path, files in state_map.items():
        try:
            file_set = set(files)
        except Exception as e:  # pragma: no cover
            raise ValueError(
                f"Files for logical path '{logical_path}' must be an iterable of file paths"
            ) from e
        result[logical_path] = file_set

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        return {}
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a mapping of logical paths to file information")
    path_map = {}
    for logical_path, files in inventory.items():
        files_set = set()
        # Files entry may be a dict (whose keys are file paths), a list/tuple/set, or a single path.
        if isinstance(files, dict):
            # Assume the keys are file paths or each value is a mapping containing a 'file' key
            for key, value in files.items():
                if isinstance(value, dict) and 'file' in value:
                    files_set.add(value['file'])
                else:
                    files_set.add(key)
        elif isinstance(files, (list, tuple, set)):
            for f in files:
                if isinstance(f, dict) and 'file' in f:
                    files_set.add(f['file'])
                else:
                    files_set.add(f)
        else:
            # single value
            if isinstance(files, dict) and 'file' in files:
                files_set.add(files['file'])
            else:
                files_set.add(files)
        if files_set:
            path_map[logical_path] = files_set
    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    # Resolve the target version
    if version not in inventory:
        raise ValueError(f"Version {version!r} not found in inventory")
    # Order versions; assume they are comparable (strings or numbers)
    try:
        sorted_versions = sorted(inventory.keys())
    except TypeError as exc:
        raise TypeError("Inventory keys must be comparable for sorting") from exc
    # Helper to get index
    try:
        start_index = sorted_versions.index(version)
    except ValueError as exc:
        raise ValueError(f"Version {version!r} not present in sorted inventory") from exc
    # Accumulate mapping
    result = {}
    for v in sorted_versions[start_index:]:
        mapping = inventory.get(v, {})
        if not isinstance(mapping, dict):
            raise TypeError(f"Inventory entry for version {v!r} must be a dict")
        for logical_path, files in mapping.items():
            if not isinstance(files, (set, list, tuple)):
                raise TypeError(f"Files for logical path {logical_path!r} must be a set/list/tuple")
            files_set = set(files)
            if logical_path in result:
                result[logical_path].update(files_set)
            else:
                result[logical_path] = files_set
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError('Fixity must be a dict')
    if 'files' not in fixity:
        raise ValueError('Missing "files" key in fixity block')
    files_block = fixity['files']
    if not isinstance(files_block, dict):
        raise ValueError('"files" entry must be a dict')
    allowed_algos = {'md5', 'sha1', 'sha256', 'sha512'}
    for fname, algo_dict in files_block.items():
        if not isinstance(fname, str):
            raise ValueError('File names in fixity must be strings')
        if fname not in manifest_files:
            raise ValueError(f'File "{fname}" referenced in fixity is not present in the manifest')
        if not isinstance(algo_dict, dict):
            raise ValueError(f'Checksum for file "{fname}" must be a dict')
        if not algo_dict:
            raise ValueError(f'No checksum algorithm provided for file "{fname}"')
        for algo, hash_val in algo_dict.items():
            if algo not in allowed_algos:
                raise ValueError(f'Unsupported checksum algorithm "{algo}" for file "{fname}"')
            if not isinstance(hash_val, str) or not hash_val:
                raise ValueError(f'Invalid checksum value for file "{fname}", algorithm "{algo}"')
    return True  # Success indication if needed.

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    required_keys = {"algorithm", "hashes"}
    missing = required_keys - fixity.keys()
    if missing:
        raise ValueError(f"Fixity block missing required keys: {', '.join(sorted(missing))}")

    algorithm = fixity.get("algorithm")
    if not isinstance(algorithm, str) or not algorithm.strip():
        raise ValueError("Fixity 'algorithm' must be a non-empty string")

    hashes = fixity.get("hashes")
    if not isinstance(hashes, dict):
        raise ValueError("Fixity 'hashes' must be a dictionary")

    for file_path, hash_value in hashes.items():
        if file_path not in manifest_files:
            raise ValueError(f"File '{file_path}' referenced in fixity is not present in the manifest")
        if not isinstance(hash_value, str) or not hash_value.strip():
            raise ValueError(f"Hash for file '{file_path}' must be a non-empty string")

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic structural validation
        if not isinstance(fixity, dict):
            raise ValueError("Fixity must be a dictionary, got %r" % (type(fixity).__name__,))
        required_keys = {'type', 'files'}
        missing = required_keys - set(fixity.keys())
        if missing:
            raise ValueError("Missing keys in fixity block: %s" % ', '.join(sorted(missing)))
        # Type field should be a non-empty string
        if not isinstance(fixity['type'], str) or not fixity['type']:
            raise ValueError("Fixity 'type' must be a non-empty string")
        files_section = fixity['files']
        if not isinstance(files_section, dict):
            raise ValueError("Fixity 'files' must be a dictionary")
        if not files_section:
            raise ValueError("Fixity 'files' dictionary cannot be empty")

        for fname, file_entry in files_section.items():
            # Ensure reference is in the manifest
            if fname not in manifest_files:
                raise ValueError("Fixity references file '%s' not found in manifest" % fname)
            # Each entry must be a dict with checksum info
            if not isinstance(file_entry, dict):
                raise ValueError("Fixity entry for '%s' must be a dictionary" % fname)
            if 'algorithm' not in file_entry or 'checksum' not in file_entry:
                raise ValueError("Fixity entry for '%s' must include 'algorithm' and 'checksum'" % fname)
            alg = file_entry['algorithm']
            chk = file_entry['checksum']
            if not isinstance(alg, str) or not alg:
                raise ValueError("Algorithm for file '%s' must be a non-empty string" % fname)
            if not isinstance(chk, str) or not chk:
                raise ValueError("Checksum for file '%s' must be a non-empty string" % fname)

        # If all checks pass, the fixity block is considered valid
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

