def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.
        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic type check
        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__!r}")

        # Required keys
        required = {"algorithm"}
        optional_digest = {"value", "checksum"}
        # Accept either 'value' or 'checksum' as the digest
        if optional_digest & set(fixity):
            required.add(next(iter(optional_digest & set(fixity))))  # add the present key
        missing = required - set(fixity)
        if missing:
            raise ValueError(f"Fixity block missing required keys: {', '.join(sorted(missing))}")

        # Validate algorithm
        algorithm = fixity["algorithm"]
        if not isinstance(algorithm, str) or not algorithm:
            raise ValueError("Fixity 'algorithm' must be a non-empty string")
        # Basic support check (extendable)
        SUPPORTED_ALGOS = {"md5", "sha1", "sha256", "sha512"}
        if algorithm.lower() not in SUPPORTED_ALGOS:
            raise ValueError(f"Unsupported algorithm: {algorithm!r}")

        # Validate digest value
        digest_key = "value" if "value" in fixity else "checksum"
        digest = fixity[digest_key]
        if not isinstance(digest, str) or not digest:
            raise ValueError(f"Fixity '{digest_key}' must be a non-empty string")

        # Optional file references
        referenced = fixity.get("files") or fixity.get("references")
        if referenced is not None:
            if not isinstance(referenced, (list, set, tuple)):
                raise ValueError("Fixity 'files' / 'references' must be a list, set, or tuple")
            for path in referenced:
                if not isinstance(path, str):
                    raise ValueError(f"Referenced file path must be a string, got {type(path).__name__!r}")
                if path not in manifest_files:
                    raise ValueError(f"File '{path}' referenced in fixity not found in manifest")

        # If all checks pass, return True
        return True

def files_list(path):
    """
    Return the files in `path`.

    If `path` is a file, returns a list containing its absolute path.
    If `path` is a directory, returns a sorted list of absolute file paths
    within that directory and all its subdirectories.

    Raises FileNotFoundError if the path does not exist.
    """
    if not path:
        raise ValueError("path must be a non-empty string")
    if not os.path.exists(path):
        raise FileNotFoundError(f"No such file or directory: '{path}'")
    result = []
    if os.path.isfile(path):
        result.append(os.path.abspath(path))
    else:
        for root, dirs, files in os.walk(path):
            for f in files:
                result.append(os.path.join(root, f))
        result.sort()
    return result

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"The path {path!r} does not exist")
        if os.path.isfile(path):
            return [os.path.abspath(path)]
        if os.path.isdir(path):
            abs_path = os.path.abspath(path)
            files = []
            for entry in os.listdir(abs_path):
                full_entry = os.path.join(abs_path, entry)
                if os.path.isfile(full_entry):
                    files.append(full_entry)
            return files
        # For other file system objects (like symlinks that are not files or dirs)
        return []
    except Exception:
        return []

