def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    if not issue:
        return None, None
    # Remove possible <issue> tags
    content = re.sub(r'<\/?issue\b[^>]*>', '', issue, flags=re.I).strip()
    # Normalize punctuation
    cleaned = re.sub(r'[\(\)\.,]', ' ', content)
    tokens = [t for t in cleaned.split() if t]

    # Helper to determine if token is numeric or range
    def is_num(token):
        return bool(re.fullmatch(r'\d+(?:-\d+)?', token))

    suppl_variants = { 'suppl', 'spe', 'supp', 's', 'sup', 'supl', 'spe', 's2', 'spepr', 'supp' }

    number = None
    suppl = None

    # Find index of first sup-related token
    idx = None
    for i, token in enumerate(tokens):
        lw = token.lower()
        # Check if token starts with a sup variant and may have trailing punctuation removed
        for var in suppl_variants:
            if lw.startswith(var):
                idx = i
                break
        if idx is not None:
            break

    if idx is not None:
        # Try to get number preceding the sup term
        if idx > 0 and is_num(tokens[idx - 1]):
            number = tokens[idx - 1]
        # Try to get number following the sup term
        if idx + 1 < len(tokens) and is_num(tokens[idx + 1]):
            suppl = tokens[idx + 1]
        else:
            # Sometimes the number follows after a punctuation or is part of same token
            # e.g., "supp5 1" where "supp5" contains digits
            if re.match(r'supp\d+$', tokens[idx], re.I):
                match = re.search(r'\d+(?:-\d+)?', tokens[idx])
                if match:
                    number = match.group()
            if not suppl:
                # look ahead for any numeric token after idx
                for j in range(idx + 1, len(tokens)):
                    if is_num(tokens[j]):
                        suppl = tokens[j]
                        break
    else:
        # No supplement keyword found, maybe only a number
        if tokens and is_num(tokens[0]):
            number = tokens[0]

    # Convert numeric strings to int or keep as string for ranges
    def parse_num(tok):
        if not tok:
            return None
        if '-' in tok:
            try:
                start, end = map(int, tok.split('-'))
                return list(range(start, end + 1))
            except ValueError:
                return tok
        try:
            return int(tok)
        except ValueError:
            return tok

    number = parse_num(number)
    suppl = parse_num(suppl)

    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        import json
        # Determine a sensible indent level
        actual_indent = indent if indent and indent > 0 else 4
        if hasattr(self, "__dict__"):
            data = self.__dict__
            rep = json.dumps(data, indent=actual_indent, sort_keys=True, default=lambda o: str(o))
        else:
            rep = json.dumps(self, indent=actual_indent, default=lambda o: str(o))
    except Exception:
        rep = repr(self)
    if debug:
        header = f"{self.__class__.__name__} (id={id(self)})\n"
        return header + rep
    return rep

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def _simple(expr):
        # Return False if no change; otherwise return modified expression
        if isinstance(expr, tuple) and expr:
            typ = expr[0]
            if typ == 'and':
                left = _simple(expr[1])
                right = _simple(expr[2])
                e = ('and', left, right)
                # A & (A | B)  or  (A | B) & A
                if isinstance(right, tuple) and right[0] == 'or':
                    if right[1] == left or right[2] == left:
                        return left
                if isinstance(left, tuple) and left[0] == 'or':
                    if left[1] == right or left[2] == right:
                        return right
                # A & (~A | B)  or  (~A | B) & A
                def match_not_or(target):
                    if isinstance(target, tuple) and target[0] == 'or':
                        children = target[1:]
                        not_parts = [c for c in children if isinstance(c, tuple) and c[0] == 'not' and c[1] == left]
                        if not_parts:
                            other = [c for c in children if c not in not_parts]
                            if other:
                                return ('and', left, other[0])
                    return None
                if isinstance(right, tuple) and right[0] == 'or':
                    for c in right[1:]:
                        if isinstance(c, tuple) and c[0] == 'not' and c[1] == left:
                            other = [x for x in right[1:] if x is not c]
                            if other:
                                return ('and', left, other[0])
                if isinstance(left, tuple) and left[0] == 'or':
                    for c in left[1:]:
                        if isinstance(c, tuple) and c[0] == 'not' and c[1] == right:
                            other = [x for x in left[1:] if x is not c]
                            if other:
                                return ('and', right, other[0])
                return e
            if typ == 'or':
                left = _simple(expr[1])
                right = _simple(expr[2])
                e = ('or', left, right)
                # A | (A & B)  or  (A & B) | A
                if isinstance(right, tuple) and right[0] == 'and':
                    if right[1] == left or right[2] == left:
                        return left
                if isinstance(left, tuple) and left[0] == 'and':
                    if left[1] == right or left[2] == right:
                        return right
                # A | (~A & B)  or  (~A & B) | A
                if isinstance(right, tuple) and right[0] == 'and':
                    for c in right[1:]:
                        if isinstance(c, tuple) and c[0] == 'not' and c[1] == left:
                            other = [x for x in right[1:] if x is not c]
                            if other:
                                return ('or', left, other[0])
                if isinstance(left, tuple) and left[0] == 'and':
                    for c in left[1:]:
                        if isinstance(c, tuple) and c[0] == 'not' and c[1] == right:
                            other = [x for x in left[1:] if x is not c]
                            if other:
                                return ('or', right, other[0])
                return e
        return expr

    def _normalize(expr):
        # Repeatedly apply simplification until stable
        prev = None
        curr = expr
        while prev != curr:
            prev = curr
            curr = _simple(curr)
        return curr

    result = []
    for item in args:
        try:
            simplified = _normalize(item)
            result.append(simplified)
        except Exception:
            # If any error occurs, keep original item
            result.append(item)
    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    def decorator(func):
        # Try to use a preferred registration method if it exists
        try:
            if hasattr(self, "register_listener"):
                self.register_listener(hook, func)
            elif hasattr(self, "_registry"):
                # Expect _registry to be a dict mapping hooks to lists of callables
                listeners = getattr(self, "_registry").setdefault(hook, [])
                listeners.append(func)
            else:
                raise AttributeError(
                    "No suitable registration method or _registry found on the instance."
                )
        except Exception as exc:
            raise RuntimeError(
                f"Failed to register listener for hook {hook!r}: {exc}"
            ) from exc
        return func
    return decorator

