    candidate_files = ['VERSION', 'version.py', 'setup.cfg', 'pyproject.toml', 'setup.py']
    for fname in candidate_files:
        try:
            file_path = os.path.join(os.path.dirname(__file__), fname)
            if not os.path.isfile(file_path):
                continue
            if fname.endswith('.py'):
                ns = {}
                with open(file_path, 'r', encoding='utf-8') as f:
                    exec(f.read(), ns)
                if 'VERSION' in ns:
                    return str(ns['VERSION']).strip()
                if '__version__' in ns:
                    return str(ns['__version__']).strip()
            else:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                # Simple regex to find a version assignment
                import re
                match = re.search(r'version\s*=\s*[\'"]([^\'"]+)[\'"]', content, re.IGNORECASE)
                if match:
                    return match.group(1).strip()
        except Exception:
            continue

    # Attempt to use importlib.metadata (Python 3.8+)
    try:
        import importlib.metadata
        pkg_name = __package__ if __package__ else None
        if pkg_name:
            return importlib.metadata.version(pkg_name)
