        base = f"{major}.{minor}.{patch}"
        if prerelease:
            base += f"-{prerelease}"
        if metadata:
            base += f"+{metadata}"
        return base
    elif style == 'short':
        return f"{major}.{minor}"
    elif style == 'raw':
        # Concatenate all parts without separators
        return ''.join(part for part in (major, minor, patch, prerelease, metadata) if part)
    else:
        raise ValueError(f"Unsupported style '{style}'. Supported styles: 'full', 'short', 'raw'.")

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    def _serialize_value(val):
        return '' if val is None else str(val)

    try:
        if not isinstance(pieces, (list, tuple, dict)):
            raise TypeError("pieces must be a list, tuple, or dict")

        if callable(style):
            # If style is a callable, delegate rendering
            return style(pieces)

        if not isinstance(style, str):
            raise TypeError("style must be a string or callable")

        # Convert pieces into ordered string list
        if isinstance(pieces, dict):
            # Order of components: major, minor, patch, pre_release, build
            order = ["major", "minor", "patch", "pre_release", "build"]
            values = [_serialize_value(pieces.get(k)) for k in order]
        else:
            values = [str(p) for p in pieces]

        # Common predefined styles
        if style.lower() == "plain":
            return ".".join(values)

        if style.lower() == "full":
            # Core version: major.minor.patch
            core = ".".join(v for v in values[:3] if v)
            # Append pre-release and build if present
            suffix = []
            if values[3]:
                suffix.append(values[3])
            if values[4]:
                suffix.append(values[4])
            return core + ("-" + "-".join(suffix) if suffix else "")

        # If style string contains format placeholders, use it as custom format
        if "{" in style and "}" in style:
            if isinstance(pieces, dict):
                mapping = {k: _serialize_value(v) for k, v in pieces.items()}
                return style.format(**mapping)
            else:
                # Map positions to values 0,1,2...
                mapping = {str(i): v for i, v in enumerate(values)}
                return style.format(**mapping)

        # Unsupported style
        raise ValueError(f"Unsupported style: {style}")

    except Exception as exc:
        raise RuntimeError("Error rendering version") from exc

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Helper escaping for HTML/XML
    def escape(text):
        return (
            text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace("\"", "&quot;")
            .replace("'", "&#39;")
        )

    # Validate and normalize pieces
    if pieces is None:
        pieces = []
    try:
        pieces_list = list(pieces)
    except TypeError:
        raise ValueError("`pieces` must be an iterable")
    for i, item in enumerate(pieces_list):
        if isinstance(item, (bytes, bytearray)):
            try:
                pieces_list[i] = item.decode("utf-8")
            except AttributeError:
                raise ValueError("bytes-like objects must be decoded to str")
        else:
            pieces_list[i] = str(item)

    # Validate style
    if not isinstance(style, str):
        raise ValueError("`style` must be a string")
    style_key = style.strip().lower()

    if style_key in ("plain", "text", ""):
        return "\n".join(pieces_list)

    if style_key == "json":
        import json
        return json.dumps(pieces_list, ensure_ascii=False, indent=2)

    if style_key == "html":
        escaped = [f"<p>{escape(p)}</p>" for p in pieces_list]
        return "<div>\n" + "\n".join(escaped) + "\n</div>"

    if style_key == "xml":
        escaped = "".join(f"<piece>{escape(p)}</piece>" for p in pieces_list)
        return f"<root>{escaped}</root>"

    raise ValueError(f"Unsupported style: {style}")

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : iterable
        The individual components of the version (e.g., major, minor,
        patch, prerelease).  Items may be integers, strings, or any
        object that can be coerced to a string with ``str()``.
    style : {'dot', 'dash', 'space', 'tuple'} or callable
        The desired style for rendering. ``'dot'`` renders with '.' as the
        separator, ``'dash'`` with '-', ``'space'`` with a single space,
        ``'tuple'`` renders the components inside parentheses.  If ``style``
        is a callable, it must accept the list of stringified pieces
        and return a string.

    Returns
    -------
    str
        The formatted version string.

    Raises
    ------
    ValueError
        If an unsupported style is supplied or if *pieces* is not an
        iterable or contains unconvertible items.
    """
    # Validate pieces
    try:
        # Convert to list to allow multiple passes
        component_strings = []
        for idx, item in enumerate(pieces):
            try:
                component_strings.append(str(item))
            except Exception as exc:
                raise ValueError(f"Piece at index {idx!r} cannot be converted to string: {exc}") from exc
    except TypeError as exc:
        raise ValueError("`pieces` must be an iterable of components") from exc

    # Resolve rendering style
    if isinstance(style, str):
        style = style.lower()
        if style == 'dot':
            return '.'.join(component_strings)
        elif style == 'dash':
            return '-'.join(component_strings)
        elif style == 'space':
            return ' '.join(component_strings)
        elif style == 'tuple':
            return f"({', '.join(component_strings)})"
        else:
            raise ValueError(f"Unsupported style string: {style!r}")
    elif callable(style):
        try:
            return style(component_strings)
        except Exception as exc:
            raise ValueError(f"Custom style callable raised an error: {exc}") from exc
    else:
        raise ValueError(f"style must be a supported string or a callable, got {type(style).__name__}")

