        elif hasattr(self, 'hierarchy_root'):
            root_obj = self.hierarchy_root
        else:
            raise AttributeError("Hierarchy root not found on this instance.")

        num_objects = 0
        good_objects = 0

        # Local helper to compute a simple digest - placeholder for actual logic
        def _compute_digest(item):
            import hashlib
            # Convert the item to a string representation for hashing
            return hashlib.sha256(repr(item).encode()).hexdigest()

        def _validate(node):
            nonlocal num_objects, good_objects
            num_objects += 1
            valid = True

            # Basic verification that node is a mapping if we are validating objects
            if validate_objects:
                if not isinstance(node, dict):
                    valid = False
                    if show_warnings:
