                            print(f"Warning: Failed to compute digest for node {node.get('id', '<unknown>')}: {exc}")

            if valid:
                good_objects += 1

            # Recurse into children if present
            for child in node.get('children', []):
                _validate(child)

        try:
            _validate(root_obj)
