def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        import os
        import hashlib

        # Resolve the root path; it must be set on the instance
        root_path = getattr(self, 'root', None)
        if root_path is None:
            raise ValueError("Root path is not defined on this instance.")
        if not os.path.isdir(root_path):
            raise FileNotFoundError(f"Root directory does not exist: {root_path}")

        num_objects = 0
        good_objects = 0

        # Traverse the directory tree
        for dirpath, dirnames, filenames in os.walk(root_path, topdown=True):
            # Count directories
            for dirname in dirnames:
                num_objects += 1
                # Assume directories are always considered valid
                good_objects += 1

            # Process files
            for filename in filenames:
                num_objects += 1
                full_path = os.path.join(dirpath, filename)
                is_good = True

                if validate_objects:
                    try:
                        stat = os.stat(full_path)
                        if stat.st_size == 0:
                            is_good = False
                            if show_warnings:
                                print(f"Warning: {full_path} is empty.")
                    except Exception as exc:
                        is_good = False
                        if show_warnings:
                            print(f"Warning: cannot stat {full_path}: {exc}")

                if check_digests and is_good:
                    try:
                        with open(full_path, 'rb') as f:
                            data = f.read()
                        digest = hashlib.md5(data).hexdigest()
                        if not digest:
                            is_good = False
                            if show_warnings:
                                print(f"Warning: could not compute digest for {full_path}.")
                    except Exception as exc:
                        is_good = False
                        if show_warnings:
                            print(f"Warning: error computing digest for {full_path}: {exc}")

                if is_good:
                    good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Determine the starting point of the hierarchy.
    root = getattr(self, "root", None)
    if root is None:
        root = getattr(self, "storage_root", None)
    if root is None:
        # nothing to validate
        return num_objects, good_objects

    # Use a stack for iterative depth‑first traversal to avoid recursion limits.
    stack = [root]
    while stack:
        obj = stack.pop()
        num_objects += 1
        is_valid = True

        # Basic object validation via a validate() method if present.
        if validate_objects:
            try:
                validate_method = getattr(obj, "validate", None)
                if callable(validate_method):
                    validate_method()
                else:
                    # Fallback sanity checks: objects should be mappings in this context.
                    if not isinstance(obj, dict):
                        raise TypeError("Expected dict-like object for validation")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    obj_id = getattr(obj, "id", "<unknown>")
                    print(f"[VALIDATION] Object {obj_id!s} failed validation: {exc}")

        # Digest integrity check if requested and if prior validation passed.
        if is_valid and check_digests:
            try:
                content = getattr(obj, "content", None)
                if content is not None:
                    # Compute digest using SHA‑256 for demonstration.
                    import hashlib
                    if isinstance(content, str):
                        content_bytes = content.encode("utf-8")
                    else:
                        content_bytes = content
                    expected_digest = hashlib.sha256(content_bytes).hexdigest()
                    actual_digest = getattr(obj, "digest", None)
                    if expected_digest != actual_digest:
                        raise ValueError(f"Digest mismatch (expected {expected_digest}, got {actual_digest})")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    obj_id = getattr(obj, "id", "<unknown>")
                    print(f"[DIGEST] Object {obj_id!s} digest check failed: {exc}")

        if is_valid:
            good_objects += 1

        # Queue child objects for further validation.
        children = getattr(obj, "children", None)
        if isinstance(children, (list, tuple)):
            stack.extend(children)
        elif isinstance(children, dict):
            stack.extend(children.values())

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    if not hasattr(self, "root_path"):
        raise AttributeError("The instance must have a 'root_path' attribute to initialize an OCFL storage root.")

    root = self.root_path
    try:
        # Create the root directory; expect it not to exist already.
        os.makedirs(root, exist_ok=False)
    except FileExistsError:
        raise FileExistsError(f"OCFL root directory '{root}' already exists.")
    except PermissionError as exc:
        raise PermissionError(f"Permission denied while creating OCFL root directory '{root}': {exc}") from exc
    except Exception as exc:
        raise OSError(f"Failed to create OCFL root directory '{root}': {exc}") from exc

    # Create the internal .ocfl directory required by the OCFL specification.
    ocfl_dir = os.path.join(root, ".ocfl")
    try:
        os.makedirs(ocfl_dir, exist_ok=False)
    except FileExistsError:
        raise FileExistsError(f"The OCFL internal directory '{ocfl_dir}' already exists.")
    except PermissionError as exc:
        raise PermissionError(f"Permission denied while creating OCFL internal directory '{ocfl_dir}': {exc}") from exc
    except Exception as exc:
        raise OSError(f"Failed to create OCFL internal directory '{ocfl_dir}': {exc}") from exc

    # Create the objects directory where actual OCFL objects will live.
    objects_dir = os.path.join(ocfl_dir, "objects")
    try:
        os.makedirs(objects_dir, exist_ok=False)
    except FileExistsError:
        raise FileExistsError(f"The objects directory '{objects_dir}' already exists.")
    except PermissionError as exc:
        raise PermissionError(f"Permission denied while creating objects directory '{objects_dir}': {exc}") from exc
    except Exception as exc:
        raise OSError(f"Failed to create objects directory '{objects_dir}': {exc}") from exc

    # Write a minimal configuration file for the OCFL store.
    try:
        cfg_path = os.path.join(ocfl_dir, "ocfl.cfg")
        with open(cfg_path, "w", encoding="utf-8") as f:
            f.write("[ocfl]\n")
            f.write("version = 1.2\n")
    except Exception as exc:
        raise OSError(f"Failed to write OCFL configuration file '{cfg_path}': {exc}") from exc

    # Mark the instance as initialized so other methods can rely on it.
    self._initialized = True
    return root

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # Ensure input is a non-empty string consisting of digits
    if not isinstance(version, str) or not version:
        return ""
    if not version.isdigit():
        return ""

    try:
        # Convert to integer and increment
        new_value = int(version) + 1
    except (ValueError, TypeError):
        return ""

    # Convert back to string with appropriate zero padding
    new_str = str(new_value)
    if len(new_str) < len(version):
        new_str = new_str.zfill(len(version))
    return new_str

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not isinstance(version, str):
            return ""
        version = version.strip()
        if not version:
            return ""
        # Ensure the version string consists only of digits
        if not version.isdigit():
            return ""
        width = len(version)
        next_number = int(version) + 1
        # Preserve leading zeros by zero-filling to the original width
        return str(next_number).zfill(width)
    except Exception:
        return ""

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""
    v = version.strip()
    if not v:
        return v
    parts = v.split('.')
    widths = [len(p.lstrip('-').lstrip('0') or '0') for p in parts]  # width of each part ignoring leading zeros
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        # If any part is not an integer, return original string
        return v
    # Increment the last part
    nums[-1] += 1
    # Reconstruct with original padding
    new_parts = []
    for num, width, original in zip(nums, widths, parts):
        # Determine if original had a leading zero string
        # Preserve zero padding to the maximum of original width and result length
        if width > 0:
            new_str = str(num).zfill(max(width, len(str(num))))
        else:
            new_str = str(num)
        new_parts.append(new_str)
    return '.'.join(new_parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not version or not isinstance(version, str):
            return ""
        version = version.strip()
        if not version:
            return ""

        parts = version.split(".")
        if not parts:
            return version

        # Try to convert all parts to ints to ensure numeric version
        int_parts = []
        for part in parts:
            if part == '':
                return version
            try:
                int_parts.append(int(part))
            except ValueError:
                # Non-numeric part, return original
                return version

        # Increment the last part
        int_parts[-1] += 1

        # Reconstruct string with original padding for all but the last part
        new_parts = []
        for idx, (orig, new) in enumerate(zip(parts, int_parts)):
            if idx == len(parts) - 1:
                # Handle padding for the last part
                new_str = str(new)
                width = len(orig)
                if len(new_str) <= width:
                    new_str = new_str.zfill(width)
            else:
                new_str = orig  # keep as-is
            new_parts.append(new_str)

        return ".".join(new_parts)
    except Exception:
        return version

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.
    """
    import os
    import json
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    # The root inventory is expected to be a mapping of file paths to digests.
    root_inventory = getattr(self, 'root_inventory', {})
    cumulative_inventory = {}
    differences = {}
    for idx, vdir in enumerate(version_dirs):
        inv_path = os.path.join(self.base_dir, vdir, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file for version directory: '{vdir}'")
        try:
            with open(inv_path, 'r') as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Unable to load inventory from '{inv_path}': {exc}") from exc
        if not isinstance(inv, dict):
            raise ValueError(f"Inventory at '{inv_path}' must be a dictionary")
        # Ensure each cumulative inventory includes all items from earlier inventories.
        for path in cumulative_inventory:
            if path not in inv:
                raise ValueError(f"Inventory in '{vdir}' missing entry '{path}' which was present in an earlier version")
        # Record any discrepancy between this inventory and the root inventory.
        for path, digest in inv.items():
            root_digest = root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                differences.setdefault(path, []).append((root_digest, digest))
        # Merge current inventory into cumulative inventory.
        cumulative_inventory.update(inv)
    # Store the discrepancies for later validation checks.
    self.different_digests = differences
    return self.different_digests

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the
    root inventory so that we can also check them when validating the
    content.

    version_dirs is an array of version directory names and is assumed to
    be in version sequence (1, 2, 3...).
    """
    # Store cumulative inventory so far
    cumulative = {}
    # Root inventory is assumed to be stored on the instance (if present)
    root_inventory = getattr(self, 'root_inventory', {})
    # Map of path -> set of differing digests seen in the root inventory
    diffs = {}

    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(vdir, 'inventory.json')
        if not os.path.exists(inv_path):
            raise FileNotFoundError(
                f"Inventory file missing for version directory: {vdir}"
            )
        try:
            with open(inv_path, 'rt', encoding='utf-8') as fh:
                inventory = json.load(fh)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Failed to decode JSON inventory at {inv_path}: {exc}"
            ) from exc
        except OSError as exc:
            raise RuntimeError(
                f"Unable to open inventory at {inv_path}: {exc}"
            ) from exc

        if inventory is None:
            raise ValueError(f"Empty inventory at {inv_path}")

        # Verify that the inventory contains only known keys
        # and that all previously added items are present.
        missing = set(cumulative.keys()) - set(inventory.keys())
        if missing:
            raise ValueError(
                f"Inventory for version {vdir} misses previous items: {missing}"
            )

        # Update cumulative inventory and record any discrepancies with root
        for path, digest in inventory.items():
            prev_digest = cumulative.get(path)
            # Detect items that appeared first time with a different digest
            if prev_digest is None:
                # First time we see this path – compare with root if present
                root_digest = root_inventory.get(path)
                if root_digest is not None and root_digest != digest:
                    diffs.setdefault(path, set()).add(digest)
            else:
                # Subsequent appearance; ensure digest consistency within
                # the version sequence
                if prev_digest != digest:
                    raise ValueError(
                        f"Inconsistent digest for {path} "
                        f"between earlier ( {prev_digest} ) "
                        f"and current ( {digest} ) in version {vdir}"
                    )

            cumulative[path] = digest

    # Store the differences for later use
    self.version_inventory_differences = diffs
    return diffs

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    def _read_inventory(path):
        """Return a dict mapping filename to digest from a simple inventory file."""
        if not hasattr(self, 'open') and not hasattr(__builtins__, 'open'):
            raise RuntimeError('open function not available')
        inv = {}
        try:
            with open(path, 'r', encoding='utf-8') as f:
                for line in f:
                    parts = line.strip().split(None, 1)
                    if len(parts) != 2:
                        continue  # skip malformed lines
                    fname, digest = parts
                    inv[fname] = digest
        except FileNotFoundError:
            return None
        return inv

    # Validate required attributes
    base = getattr(self, 'base_dir', None)
    root_path = getattr(self, 'root_inventory_path', None)
    if base is None or root_path is None:
        raise AttributeError('self must have base_dir and root_inventory_path attributes')

    # Load root inventory once
    root_inv = _read_inventory(root_path)
    if root_inv is None:
        raise FileNotFoundError(f'Root inventory file not found at {root_path}')

    # Container for digests that differ from the root inventory
    differing = {}

    # Iterate through the expected version directories in order
    for idx, vdir in enumerate(version_dirs, start=1):
        dir_path = os.path.join(base, vdir)
        inv_path = os.path.join(dir_path, 'inventory')
        inv = _read_inventory(inv_path)
        if inv is None:
            raise FileNotFoundError(f'Inventory missing for version directory {vdir!r}')

        # Record any digest that differs from the root inventory
        for fname, digest in inv.items():
            root_digest = root_inv.get(fname)
            if root_digest is None or root_digest != digest:
                differing.setdefault(fname, []).append(vdir)

    # Store the result for later validation steps
    self.differing_digests = differing
    return self

