            ]
            if mismatches:
                self._digests_different[dir_name] = mismatches
            previous_files = current_files
        # If no mismatches were found, keep an empty dict for consistency
        if not self._digests_different:
            self._digests_different = {}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        # Check existence and file/dir status.
        if not os.path.exists(path):
            return f'not found: {path!r} does not exist'

        if os.path.isfile(path):
            return 'file'

        if os.path.isdir(path):
            # List the directory and look for any entry that starts with "0="
            try:
                entries = os.listdir(path)
            except Exception as exc:
                return f'cannot read directory: {exc}'
            for entry in entries:
                if entry.startswith('0='):
                    return 'object'
            # No "0=" entries -> likely OCFL storage root.
            return 'root'
    except Exception as exc:  # pragma: no cover
        # Catch any unexpected errors and return a descriptive string.
        return f'error: {exc}'

