        return "invalid input: path must be a string"

    try:
        if not os.path.exists(path):
            return f"path '{path}' does not exist"
    except Exception as e:
        return f"cannot access path: {e}"

    try:
        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            try:
                entries = os.listdir(path)
            except Exception as e:
                return f"cannot read directory '{path}': {e}"

            # look for Namaste files starting with "0="
            namaste_files = [e for e in entries if e.startswith("0=")]
            if not namaste_files:
                return "not an OCFL directory (no Namaste files)"

            # Heuristic: if there are subdirectories in this directory, assume root
            subdirs = [e for e in entries if os.path.isdir(os.path.join(path, e))]
            if subdirs:
                return "root"

            return "object"
    except Exception as e:
        return f"error processing path: {e}"

    return "unknown type"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'  - looks like an OCFL Storage Root
        'object'- looks like an OCFL Object
        'file'  - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    if not path:
        return "Error: empty path provided."

    # Normalize path to avoid trailing separators and handle relative paths
    path = os.path.normpath(path)

    if not os.path.exists(path):
        return f"Error: path '{path}' does not exist."

    try:
        if os.path.isfile(path):
            return 'file'

        if os.path.isdir(path):
            # Check for OCFL root indicator
            root_file = os.path.join(path, '.ocfl_root.json')
            if os.path.isfile(root_file):
                return 'root'

            # Check for OCFL object indicator
            object_file = os.path.join(path, '.ocfl_fmd.json')
            if os.path.isfile(object_file):
                return 'object'

            # Look for a Namaste "0=*" file inside the directory
            try:
                for entry in os.listdir(path):
                    if re.match(r'^0=\d+$', entry):
                        return 'object'
            except OSError:
                # If we cannot read the directory contents, report error
                return f"Error: cannot read directory contents at '{path}'."

            return f"Unknown directory type for path '{path}'."
    except Exception as exc:
        return f"Error: exception {type(exc).__name__} occurred while inspecting '{path}'."
    return f"Error: unhandled case for path '{path}'."

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Make a shallow copy to avoid modifying the caller's dict directly
    amended = dict(params)
    if bug_ids:
        if not hasattr(bug_ids, "__iter__"):
            raise TypeError("bug_ids must be iterable")
        # Convert each id to string, filtering out None or empty values
        cleaned_ids = [str(bid) for bid in bug_ids if bid is not None]
        if cleaned_ids:
            # Bugzilla expects comma-separated list for 'id' or 'ids' parameter
            # Use 'ids' as the standard key for multiple IDs
            amended["ids"] = ",".join(cleaned_ids)
    return amended

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # validate inputs
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    # If bug_ids is None or empty, do nothing
    if bug_ids is None or (isinstance(bug_ids, (list, tuple)) and not bug_ids):
        return params
    # Handle single id
    if isinstance(bug_ids, (int, str)):
        params['id'] = str(bug_ids)
    # Handle list/tuple of ids
    elif isinstance(bug_ids, (list, tuple)):
        params['ids'] = ','.join(str(bid) for bid in bug_ids)
    else:
        # Unsupported type
        raise TypeError("bug_ids must be an int, str, list or tuple")
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (ruamel.yaml.nodes.ScalarNode as a key,
         ruamel.yaml.nodes.MappingNode or other Node as a value),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping(node):
        """Return True if node behaves like a MappingNode (has .value as list)."""
        return hasattr(node, 'value') and isinstance(node.value, list)

    def merge_mapping_nodes(a, b):
        """Recursively merge two MappingNode-like objects, returning a new MappingNode."""
        # Make a copy of the first node's value list
        merged = list(a.value)
        for key_node, val_node in b.value:
            # Search for matching key in merged
            found = False
            for i, (k, v) in enumerate(merged):
                if k.value == key_node.value:
                    # Merge values if both are mapping-like
                    if is_mapping(v) and is_mapping(val_node):
                        merged[i] = (k, merge_mapping_nodes(v, val_node))
                    else:
                        # Non-mapping values: last wins
                        merged[i] = (k, val_node)
                    found = True
                    break
            if not found:
                # Append new pair
                merged.append((key_node, val_node))
        # Construct a new node of the same type as a
        return type(a)(tag=a.tag, value=merged)

    # Mapping from scalar key value to (original key_node, merged value_node)
    result_dict = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in result_dict:
            existing_key_node, existing_val_node = result_dict[key]
            if is_mapping(existing_val_node) and is_mapping(val_node):
                # Deep merge mapping nodes
                merged_node = merge_mapping_nodes(existing_val_node, val_node)
                result_dict[key] = (existing_key_node, merged_node)
            else:
                # For non-mapping or differing types, last value wins
                result_dict[key] = (existing_key_node, val_node)
        else:
            result_dict[key] = (key_node, val_node)

    # Reconstruct list preserving order of first appearance
    return [(k, v) for k, v in result_dict.values()]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a mapping node
    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    # Recursively merge two values
    def merge_value_pair(old, new):
        if is_mapping(old) and is_mapping(new):
            return merge_maps([old, new])
        else:
            return new

    # Merge a list of mapping nodes into one mapping node
    def merge_maps(nodes_list):
        merged_items = []
        seen = {}
        for node in nodes_list:
            for k, v in node.value:  # node.value is a list of (key, value) tuples
                key_id = k.value  # assuming ScalarNode with .value
                if key_id in seen:
                    idx = seen[key_id]
                    old_key, old_val = merged_items[idx]
                    merged_items[idx] = (old_key, merge_value_pair(old_val, v))
                else:
                    seen[key_id] = len(merged_items)
                    merged_items.append((k, v))
        # Construct a new MappingNode preserving the original tag
        if nodes_list:
            tag = nodes_list[0].tag
            return type(nodes_list[0])(tag=tag, value=merged_items)
        return None

    # Collect values by key while preserving order
    key_to_vals = {}
    key_order = []
    for key_node, val_node in nodes:
        key_id = key_node.value
        if key_id not in key_to_vals:
            key_to_vals[key_id] = []
            key_order.append(key_id)
        key_to_vals[key_id].append(val_node)

    # Build merged result
    merged = []
    for key_id in key_order:
        vals = key_to_vals[key_id]
        # Pick the original key node (first occurrence)
        key_node = None
        for kn, _ in nodes:
            if kn.value == key_id:
                key_node = kn
                break
        # Merge vals
        if len(vals) == 1:
            merged_val = vals[0]
        else:
            if all(is_mapping(v) for v in vals):
                merged_val = merge_maps(vals)
            else:
                merged_val = vals[-1]
        merged.append((key_node, merged_val))
    return merged

def deep_merge_nodes(nodes):
    """Deep merge nodes with duplicate keys.

    Parameters
    ----------
    nodes : list[tuple[ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node]]
        List of (key, value) tuples comprising a mapping node.

    Returns
    -------
    list[tuple[ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node]]
        The merged list of tuples.
    """
    # Helper to test for MappingNode
    MappingNode = type(nodes[0][1]) if nodes else None

    def is_mapping(n):
        try:
            return isinstance(n, MappingNode)
        except Exception:
            return False

    def _merge_values(a, b):
        """Merge two node values."""
        if is_mapping(a) and is_mapping(b):
            # Deep merge mapping node values
            merged_value = deep_merge_nodes(a.value + b.value)
            return type(a)(tag=a.tag, value=merged_value)
        # For non-mapping nodes: last one wins
        return b

    first_occurrence = {}
    merged = {}
    order = []

    for key_node, val_node in nodes:
        key = key_node.value
        if key not in merged:
            first_occurrence[key] = key_node
            merged[key] = val_node
            order.append(key)
        else:
            merged[key] = _merge_values(merged[key], val_node)

    result = [(first_occurrence[k], merged[k]) for k in order]
    return result

