def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser()
    # Add subparsers container; specific subparsers can be added later by the caller if needed
    try:
        subparsers_action = parser.add_subparsers(dest='subcommand')
    except Exception:
        subparsers_action = None

    try:
        global_namespace, remaining_args = parser.parse_known_args(list(unparsed_arguments))
    except Exception as exc:
        raise RuntimeError(f"Failed to parse global arguments: {exc}") from exc

    result: dict[str, argparse.Namespace] = {'global': global_namespace}

    # If the first remaining token is a subparser name, try to parse its arguments
    if remaining_args and not remaining_args[0].startswith('-'):
        subcmd_name = remaining_args[0]
        if subparsers_action and hasattr(subparsers_action, "_name_parser_map"):
            subparsers_map = subparsers_action._name_parser_map
            if subcmd_name in subparsers_map:
                subparser = subparsers_map[subcmd_name]
                try:
                    sub_namespace, _ = subparser.parse_known_args(remaining_args[1:])
                except Exception as exc:
                    raise RuntimeError(f"Failed to parse subparser '{subcmd_name}': {exc}") from exc
                result[subcmd_name] = sub_namespace

    return result

