        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''

    def is_mapping(node):
        """Return True if the node is a MappingNode (its value is a list)."""
        try:
            return isinstance(node.value, list)
        except AttributeError:
            return False

    def merge_node_values(v1, v2):
        """Deep merge two node values, returning the merged node."""
        if is_mapping(v1) and is_mapping(v2):
            # Recursively merge the mapping lists
            merged_value = deep_merge_nodes(v1.value)
            # Reconstruct a new MappingNode using the same type and tag as v1
            try:
                return type(v1)(v1.tag, merged_value)
            except Exception:
                # Fallback: just return v2 if constructor fails
                return v2
        # For non-mapping conflicts, last value wins
        return v2

    seen = {}
    order = []

    for key_node, val_node in nodes:
        try:
            key = key_node.value
        except AttributeError:
            # Invalid key node; skip or raise
            raise TypeError(f'Expected a node with a value attribute, got {key_node!r}')
        if key not in seen:
            seen[key] = (val_node, key_node)
            order.append(key)
        else:
            existing_val, existing_key = seen[key]
            merged_val = merge_node_values(existing_val, val_node)
            seen[key] = (merged_val, existing_key)

    result = []
    for key in order:
        val_node, key_node = seen[key]
        result.append((key_node, val_node))

    return result

