def bash_completion():
    """
    Return a bash completion script for the borgmatic command by introspecting
    Borgmatic's click command-line argument parsers.
    """
    try:
        import click
        # Import Borgmatic's root click command.  It is normally defined in
        # borgmatic.cli.main as `cli`, but some forks may expose it under
        # a different name.  We attempt a few common locations.
        try:
            from borgmatic.cli.main import cli
        except Exception:
            try:
                from borgmatic import cli
            except Exception:
                cli = None
        if not cli:
            raise RuntimeError("Could not locate Borgmatic CLI definition.")
    except Exception as exc:
        # Fallback: return a minimal script that simply lists a few common
        # borgmatic subcommands, as we cannot introspect without click.
        return (
            "# Failed to import Borgmatic CLI for completion generation: {}"
            "\n# Fallback minimal completion script:\n"
            "_borgmatic_completion() {\n"
            "    local cur\n"
            "    COMPREPLY=( $(compgen -W \"help version backup restore settings\" -- \"$cur\") )\n"
            "}\n"
            "complete -F _borgmatic_completion borgmatic\n".format(exc)
        )

    def collect_commands(cmd, path):
        """Recursively collect commands and options."""
        key = ':'.join(path + [cmd.name])
        info = {
            'options': [],
            'subcommands': [],
        }
        # Collect options
        for param in cmd.params:
            if isinstance(param, click.Option):
                # Use the longest option name for display
                if param.opts:
                    info['options'].append(max(param.opts, key=len))
        # Collect subcommands if this is a Group
        if isinstance(cmd, click.Group):
            for sub_name, sub_cmd in cmd.commands.items():
                info['subcommands'].append(sub_name)
        # Recursively collect nested commands
        sub_info = {}
        if isinstance(cmd, click.Group):
            for sub_name, sub_cmd in cmd.commands.items():
                sub_info.update(collect_commands(sub_cmd, path + [cmd.name]))
                sub_info[key] = info
        else:
            sub_info[key] = info
        return sub_info

    # Borgmatic can use a CommandCollection.  We treat it as a Group for
    # introspection purposes.
    if hasattr(cli, 'commands'):
        # click.CommandCollection exposes a .commands attribute
        root_cmds = cli.commands
    else:
        # Fallback: treat cli itself as a group
        root_cmds = {cli.name: cli}
    # Build a unified command tree
    command_tree = {}
    for name, cmd in root_cmds.items():
        command_tree.update(collect_commands(cmd, []))
    # Prepare the Bash completion script
    script_lines = [
        "_borgmatic_completions() {",
        "    local cur prev words cword",
        "    IFS=' ' read -ra words <<< \"$COMP_LINE\"",
        "    cword=$COMP_CWORD",
        "    cur=\"${words[cword]}\"",
        "    prev=\"${words[cword-1]}\"",
        "",
        "    case \"$prev\" in",
    ]
    # Root level subcommands
    root_key = cli.name
    if root_key in command_tree:
        root_info = command_tree[root_key]
        for sub_name in root_info.get('subcommands', []):
            script_lines.append(f"        {sub_name})")
            sub_key = f"{root_key}:{sub_name}"
            sub_info = command_tree.get(sub_key, {})
            opts = ' '.join(sub_info.get('options', []))
            if opts:
                script_lines.append(
                    f"            COMPREPLY=( $(compgen -W \"{opts}\" -- \"$cur\") )"
                )
            else:
                script_lines.append(f"            COMPREPLY=()")
            script_lines.append("            return ;;")
    # Default completion: suggest root subcommands and options
    root_opts = ' '.join(root_info.get('options', []) if root_key in command_tree else [])
    root_subs = ' '.join(command_tree[root_key].get('subcommands', []) if root_key in command_tree else [])
    all_root = f"{root_subs} {root_opts}".strip()
    script_lines.append("        *)")
    script_lines.append(
        f"            COMPREPLY=( $(compgen -W \"{all_root}\" -- \"$cur\") )"
    )
    script_lines.append("            return ;;")
    script_lines.append("    esac")
    script_lines.append("}")
    script_lines.append("complete -F _borgmatic_completions borgmatic")
    return "\n".join(script_lines)

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        raise ValueError("response must not be None")
    try:
        # Ensure we can index the response (convert to list if needed)
        data = list(response)
    except TypeError as exc:
        raise TypeError("response must be an iterable") from exc

    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    def _pager():
        """Yield slices of the data list of size max_results."""
        total = len(data)
        for start in range(0, total, max_results):
            # Yield a slice up to max_results
            yield data[start:start + max_results]

    return _pager()

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Handle None or empty response
    if not response:
        return iter([])

    # Validate response type
    if not isinstance(response, (list, tuple)):
        raise TypeError(
            f"Expected a list or tuple for 'response', got {type(response).__name__}"
        )

    # Handle max_results not provided
    if max_results is None:
        yield list(response)
        return

    # Validate max_results type and value
    if not isinstance(max_results, int):
        raise TypeError(
            f"Expected an int for 'max_results', got {type(max_results).__name__}"
        )
    if max_results <= 0:
        raise ValueError(
            f"'max_results' must be a positive integer, got {max_results}"
        )

    # Split into pages
    for i in range(0, len(response), max_results):
        yield response[i : i + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected a dict, got {type(d).__name__}")
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    if dicts is None:
        raise TypeError("iterable of dicts must be provided, got None")
    # Try to iterate over the input
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError(f"Expected an iterable of dicts, got {type(dicts).__name__}") from exc

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element {idx} is not a dict (got {type(d).__name__})")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key {key!r} in dict {idx} is not numeric (got {type(value).__name__})")
            result[key] = result.get(key, 0) + value
    return result

