def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable `dicts`.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not isinstance(dicts, (list, tuple, set, frozenset)):
        raise TypeError("`dicts` must be an iterable of dicts")

    counters = []
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("All elements of `dicts` must be dictionaries")
        counters.append(Counter(d))

    if not counters:
        return {}
    return dict(reduce(operator.add, counters))

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Basic checks: if url is falsy, return as is
    if not url:
        return ''

    # url_args should be a mapping; if not provided, nothing to replace
    if not url_args:
        return url

    try:
        # Use regex to match {key} or <key> placeholders
        pattern = re.compile(r'\{(\w+)\}|\<(\w+)\>')

        def _replacer(match):
            # Extract key from either group 1 or group 2
            key = match.group(1) or match.group(2)
            if key in url_args:
                # Safely convert value to string
                return str(url_args[key])
            # If key not found, keep the original placeholder
            return match.group(0)

        return pattern.sub(_replacer, url)
    except Exception as exc:
        # In case of any unexpected error, log a warning and return original URL
        logger.warning(f'_replace_url_args encountered an error: {exc!s}')
        return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args."""

    if not isinstance(url, str):
        # Invalid URL input, return empty string
        return ''

    # url_args should support .get for dict-like behavior
    if not hasattr(url_args, 'get'):
        # If url_args is not a mapping, just return the original URL
        return url

    result = url
    # Find placeholders enclosed in { } and replace with values from url_args
    try:
        start = result.find('{')
        while start != -1:
            end = result.find('}', start + 1)
            if end == -1:
                # No closing brace found, stop processing
                break
            key = result[start + 1:end]
            try:
                val = url_args.get(key)
            except Exception:
                val = None
            if val is not None:
                replacement = str(val)
            else:
                # If no value provided, leave placeholder unchanged
                replacement = result[start:end + 1]
            result = result[:start] + replacement + result[end + 1:]
            # Move to the next placeholder
            start = result.find('{', start + len(replacement))
    except Exception:
        # In case of any unexpected error, return the original URL
        return url

    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url or ''

    # Find placeholders of the form {key}
    placeholder_pattern = re.compile(r'\{([a-zA-Z0-9_\-\.]+)\}')

    def replace_match(match):
        key = match.group(1)
        if key in url_args:
            # Convert the value to string and return
            return str(url_args[key])
        # If key not found, leave placeholder unchanged
        return match.group(0)

    try:
        replaced_url = placeholder_pattern.sub(replace_match, url)
    except Exception as exc:
        # If something goes wrong, log warning and return original url
        logger.warning('Failed to replace URL args for %s: %s', url, exc)
        return url

    return replaced_url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    import re
    import urllib.parse
    from collections.abc import Mapping

    if not url:
        return ''

    if url_args is None:
        url_args = {}

    if not isinstance(url_args, Mapping):
        raise TypeError('url_args must be a mapping of key-value pairs')

    # Pattern matches {key} or :key
    pattern = re.compile(r'\{([^}]+)\}|\:([^\s\/]+)')

    def _replace(match):
        key = match.group(1) or match.group(2)
        if key not in url_args:
            raise KeyError(f'Placeholder "{key}" not found in url_args')
        value = url_args[key]
        # Encode the value for inclusion in a URL
        return urllib.parse.quote(str(value))

    return pattern.sub(_replace, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''
    if not isinstance(url_args, Mapping):
        raise TypeError("url_args must be a mapping-like object")
    # Pattern matches {name} or :name
    pattern = re.compile(r'{(?P<name>\w+)}|:(?P<name_colon>\w+)')
    def _repl(match):
        key = match.group('name') or match.group('name_colon')
        if key not in url_args:
            raise ValueError(f"Missing URL argument for placeholder: {key}")
        return str(url_args[key])
    return pattern.sub(_repl, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # If the value is actually None, treat it as representing None.
    if val is None:
        return True
    # Check string representations that typically signify None.
    if isinstance(val, str):
        stripped = val.strip()
        # Empty string or whitespace-only strings represent None.
        if not stripped:
            return True
        # Case-insensitive match for common None-like tokens.
        if stripped.lower() in ('none', 'null'):
            return True
    # For any other type or non-matching string, it does not represent None.
    return False

