        option_strings = getattr(action, "option_strings", [])
        for flag in option_strings:
            # Ensure flag is a string and is an option (starts with '-')
            if isinstance(flag, str) and flag.startswith("-") and flag not in seen:
                seen.add(flag)
                flags.append(flag)
    return " ".join(flags)

def parser_flags(parser):
