        vertex3tuple._cache = triplets
        return triplets

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if number < 0:
        raise ValueError("number must be non-negative")

    # Ensure alphabet is a sequence of unique symbols and has at least two characters
    if not hasattr(alphabet, "__iter__"):
        raise TypeError("alphabet must be a sequence")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")
    if len(set(alphabet)) != base:
        raise ValueError("alphabet symbols must be unique")

    # Validate padding, if provided
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer")

    # Convert number to base representation using the alphabet
    digits: List[str] = []
    n = number
    if n == 0:
        digits.append(alphabet[0])
    else:
        while n:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding with the zero symbol if requested
    if padding is not None and len(digits) < padding:
        zeros = [alphabet[0]] * (padding - len(digits))
        digits = zeros + digits

    return "".join(digits)

def int_to_string(number: int, alphabet: list, padding: int = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic input validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
    # Build base
    base = len(alphabet)
    # Special case: zero
    if number == 0:
        result = alphabet[0]
        if padding:
            result = alphabet[0] * padding
        return result
    digits = []
    temp = number
    while temp > 0:
        temp, rem = divmod(temp, base)
        digits.append(alphabet[rem])
    # digits currently least-significant first
    digits.reverse()
    # Apply padding
    if padding and len(digits) < padding:
        digits = [alphabet[0]] * (padding - len(digits)) + digits
    return "".join(digits)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Input validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not hasattr(alphabet, "__iter__"):
        raise TypeError(f"alphabet must be an iterable, got {type(alphabet).__name__}")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct symbols to establish a base")
    # Optional padding validation
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

    # Handle sign
    sign = ""
    n = number
    if n < 0:
        sign = "-"
        n = -n

    # Convert number to digits in the specified base
    if n == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while n:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    result = "".join(digits)

    # Apply padding (on the unsigned portion only)
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return sign + result

