def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import os
    import tarfile
    import tempfile
    import requests

    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Unable to download archive from {url}") from exc

    if destination_path.exists() and not destination_path.is_dir():
        raise OSError(f"Destination {destination_path} exists and is not a directory")

    if not destination_path.exists():
        try:
            os.makedirs(destination_path, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Could not create destination directory {destination_path}") from exc

    fd, temp_path = tempfile.mkstemp(suffix=".tar.gz")
    try:
        with os.fdopen(fd, "wb") as tmp_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)
    except Exception as exc:
        try:
            os.remove(temp_path)
        except Exception:
            pass
        raise RuntimeError("Failed to write the downloaded archive to a temporary file") from exc

    try:
        with tarfile.open(temp_path, "r:gz") as tar:
            tar.extractall(path=str(destination_path))
    except Exception as exc:
        raise RuntimeError("Failed to extract the archive") from exc
    finally:
        try:
            os.remove(temp_path)
        except Exception:
            pass

    return destination_path

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure destination_path is a Path object
    if not isinstance(destination_path, Path):
        destination_path = Path(destination_path)

    # If destination exists and is not empty, raise an error to avoid accidental overwrite
    if destination_path.exists():
        if not destination_path.is_dir():
            raise OSError(f"Destination path {destination_path} exists and is not a directory.")
        if any(destination_path.iterdir()):
            raise OSError(f"Destination directory {destination_path} already contains files.")

    # Create destination directory if it does not exist
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        raise OSError(f"Failed to create destination directory {destination_path}: {e}") from e

    # Download the .tar.gz file to a temporary file
    try:
        with requests.get(url, stream=True, timeout=30) as r:
            r.raise_for_status()
            with tempfile.NamedTemporaryFile(suffix=".tar.gz", delete=False) as tmp_file:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        tmp_file.write(chunk)
                temp_path = Path(tmp_file.name)
    except requests.RequestException as e:
        raise ConnectionError(f"Error downloading archive from {url}: {e}") from e

    # Extract the archive
    try:
        with tarfile.open(temp_path, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except (tarfile.TarError, OSError) as e:
        raise RuntimeError(f"Failed to extract archive {temp_path} to {destination_path}: {e}") from e
    finally:
        # Clean up the temporary file
        try:
            temp_path.unlink()
        except OSError:
            pass

    return destination_path

