    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # os.uname() is not available on all platforms; fall back to platform module
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False
    except Exception:
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("regex_dict expects a dictionary as input")
    result = {}
    for key, value in item.items():
        try:
            if isinstance(key, str):
                # Escape regex special characters except wildcard '*'
                escaped = re.escape(key).replace(r'\*', r'.*')
                regex_key = f'^{escaped}$'
            else:
                regex_key = key
            result[regex_key] = value
        except Exception:
            # Preserve original key/value if conversion fails
            result[key] = value
    return result

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            return name
        if len(name) <= 1:
            return name
        # Match strings that start and end with the same quote character
        match = re.match(r"^(['\"<])(?P<content>.*)\1$", name)
        if match:
            content = match.group('content')
            # Unescape any escaped quotes or backslashes within the string
            content = content.replace(r'\"', '"').replace(r"\'", "'").replace(r'\\', '\\')
            return content
        return name
    except Exception:
        return name

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    try:
        return re.sub(r"[\"']", '', name)
    except Exception:
        return name

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) > 1:
        if name[0] == name[-1] and name[0] in ('"', "'"):
            return name[1:-1]
    # Remove a single leading quote
    if name.startswith(("'", '"')):
        name = name[1:]
    # Remove a single trailing quote
    if name.endswith(("'", '"')):
        name = name[:-1]
    return name

def unquote(name):
    """Remove quote from the given name."""
    # Only operate on strings
    if not isinstance(name, str):
        return name
    # Remove matching leading and trailing single or double quotes
    return re.sub(r'^([\'"])(.*)\1$', r'\2', name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re, sys, os

    if not isinstance(s, (str, bytes)):
        raise TypeError(f"Input must be a string or bytes, got {type(s)!r}")

    # Decode bytes to str if necessary
    if isinstance(s, bytes):
        s = s.decode('utf-8')

    # Determine which platform to use
    if platform == 'this':
        platform_flag = 0 if os.name == 'nt' else 1
    elif platform in (0, 1):
        platform_flag = platform
    else:
        raise ValueError(f"Invalid platform specifier: {platform!r}")

    # Patterns for POSIX and Windows
    posix_pat = re.compile(
        r'''(?:"(?P<sq>[^"]*)"|'(?P<dq>[^']*)'|(?P<plain>[^ \t\n\r]+))''',
        re.UNICODE)
    win_pat = re.compile(
        r'''(?:"(?P<sq>[^"]*)"|(?P<plain>[^ \t\n\r"^]+))''',
        re.UNICODE)

    pattern = posix_pat if platform_flag == 1 else win_pat

    result = []
    pos = 0
    for m in pattern.finditer(s):
        if m.index != pos:
            # there was unmatched text between tokens
            raise ValueError(f"Could not parse input at position {pos}: '{s[pos:m.index]}'")
        pos = m.end()
        if m.group('sq') is not None:
            result.append(m.group('sq'))
        elif m.group('dq') is not None:
            result.append(m.group('dq'))
        else:
            result.append(m.group('plain'))

    if pos != len(s):
        # dangling characters that were not matched
        raise ValueError(f"Could not parse input at end: '{s[pos:]}'")

    return result**

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        platform = 0 if sys.platform == 'win32' else 1
    if platform == 1:
        # POSIX-like splitting, respects both single and double quotes
        token_re = re.compile(r'''(?x)(?:[^\s"']+|"(?:\\.|[^\\"])*"|'(?:\\.|[^\\'])*')''')
    else:
        # Rough Windows CMD splitting: split on whitespace unless inside double quotes
        # Backslashes before quotes are treated literally (approximate)
        token_re = re.compile(r'''(?x)(?:[^\s"]+|"[^"]*")''')
    parts = token_re.findall(s)
    cleaned = []
    for part in parts:
        if part.startswith(("'", '"')) and part.endswith(("'", '"')):
            inner = part[1:-1]
            unescaped = []
            i = 0
            while i < len(inner):
                if inner[i] == '\\' and i + 1 < len(inner):
                    unescaped.append(inner[i + 1])
                    i += 2
                else:
                    unescaped.append(inner[i])
                    i += 1
            cleaned.append(''.join(unescaped))
        else:
            cleaned.append(part)
    return cleaned

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    os_module = __import__('os')
    tmp_dir = os_module.path.abspath(str(tmp_path))

    # Determine destination directory name
    if filename:
        dest_dir_name = filename
    else:
        base_name = os_module.path.basename(archive_path)
        known_exts = ('.tar.gz', '.tgz', '.tar.bz2', '.tar.xz', '.zip')
        stripped = base_name
        for ext in known_exts:
            if base_name.endswith(ext):
                stripped = base_name[:-len(ext)]
                break
        else:
            stripped = os_module.path.splitext(base_name)[0]
        dest_dir_name = stripped

    dest_dir = os_module.path.join(tmp_dir, dest_dir_name)

    try:
        os_module.makedirs(dest_dir, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Failed to create extraction directory {dest_dir}") from exc

    # Build extraction command
    cmd = None
    if archive_path.endswith(('.tar.gz', '.tgz')):
        cmd = ['tar', '-xzf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.tar.bz2'):
        cmd = ['tar', '-xjf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.tar.xz'):
        cmd = ['tar', '-xJf', archive_path, '-C', dest_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', archive_path, '-d', dest_dir]
    else:
        raise ValueError(f"Unsupported archive type: {archive_path}")

    try:
        subprocess.run(cmd, check=True, capture_output=True, text=True)
    except subprocess.CalledProcessError as exc:
        raise OSError(f"Extraction failed for {archive_path}: {exc.stderr}") from exc

    return f"file://{os_module.path.abspath(dest_dir)}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Determine destination directory
    if isinstance(tmp_path, PosixPath):
        tmp_dir = str(tmp_path)
    else:
        tmp_dir = tmp_path

    # Construct a base name for the extraction directory
    archive_name = archive_path.split('/')[-1]
    if archive_name.lower().endswith('.tar.gz'):
        base_name = archive_name[:-7]
    elif archive_name.lower().endswith('.tgz'):
        base_name = archive_name[:-4]
    elif archive_name.lower().endswith('.tar.bz2'):
        base_name = archive_name[:-8]
    elif archive_name.lower().endswith('.tbz2'):
        base_name = archive_name[:-4]
    elif archive_name.lower().endswith('.zip'):
        base_name = archive_name[:-4]
    else:
        # fallback: strip one extension part
        base_name = archive_name.rsplit('.', 1)[0] if '.' in archive_name else archive_name

    dest_dir = f"{tmp_dir}/{filename if filename else base_name}"

    try:
        # Ensure the destination directory exists
        subprocess.run(['mkdir', '-p', dest_dir], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

        # Choose extraction command based on archive type
        if archive_path.lower().endswith('.zip'):
            extract_cmd = ['unzip', '-o', archive_path, '-d', dest_dir]
        elif archive_path.lower().endswith(('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar')):
            extract_cmd = ['tar', '-xf', archive_path, '-C', dest_dir]
        else:
            raise ValueError(f"Unsupported archive type for file {archive_path}")

        # Run extraction
        subprocess.run(extract_cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    except subprocess.CalledProcessError as exc:
        raise OSError(f"Failed to extract archive {archive_path}: {exc}") from exc
    except OSError as exc:
        raise OSError(f"Error creating extraction directory {dest_dir}: {exc}") from exc

    # Return the file:// URL to the extracted repository
    return f"file://{dest_dir}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Resolve absolute paths
    archive_abs = os.path.abspath(archive_path)
    tmp_dir_abs = os.path.abspath(tmp_path)

    # Ensure temporary directory exists
    try:
        os.makedirs(tmp_dir_abs, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Unable to create temporary directory '{tmp_dir_abs}': {exc}") from exc

    # Determine extraction destination directory
    if filename:
        dest_dir = os.path.join(tmp_dir_abs, filename)
    else:
        # Strip all extensions (handles .tar.gz, .zip, etc.)
        base_name = os.path.basename(archive_abs)
        while True:
            base_name, ext = os.path.splitext(base_name)
            if not ext:
                break
        dest_dir = os.path.join(tmp_dir_abs, base_name)

    # If destination already exists, remove it to avoid stale data
    if os.path.exists(dest_dir):
        try:
            shutil.rmtree(dest_dir)
        except Exception as exc:
            raise OSError(f"Unable to remove existing directory '{dest_dir}': {exc}") from exc

    # Unpack the archive
    try:
        shutil.unpack_archive(archive_abs, dest_dir)
    except shutil.ReadError as exc:
        raise ValueError(f"Unsupported archive format or corrupted archive: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to unpack archive '{archive_abs}': {exc}") from exc

    # Return file URL of the extracted repository
    return f"file://{dest_dir}"

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            cwd=ignored,
            text=True,
            stderr=subprocess.STDOUT
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Git command failed: {exc.output}") from exc
    except FileNotFoundError as exc:
        raise RuntimeError("Git is not installed or not found in PATH") from exc
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or str(frequency).strip().lower() == "always":
        return None

    s = str(frequency).strip()
    if not s:
        raise ValueError("Empty frequency string")

    # Extract the numeric prefix
    num_str = ''
    i = 0
    while i < len(s) and s[i].isdigit():
        num_str += s[i]
        i += 1

    if not num_str:
        raise ValueError(f"Frequency '{frequency}' missing number")

    unit_part = s[i:].strip().lower()
    if not unit_part:
        raise ValueError(f"Frequency '{frequency}' missing unit")

    num = int(num_str)

    # Map unit to timedelta components
    if unit_part in ('microsecond', 'microseconds', 'us'):
        return datetime.timedelta(microseconds=num)
    if unit_part in ('millisecond', 'milliseconds', 'ms'):
        return datetime.timedelta(milliseconds=num)
    if unit_part in ('second', 'seconds', 'sec', 'secs', 's'):
        return datetime.timedelta(seconds=num)
    if unit_part in ('minute', 'minutes', 'min', 'mins', 'm'):
        return datetime.timedelta(minutes=num)
    if unit_part in ('hour', 'hours', 'h'):
        return datetime.timedelta(hours=num)
    if unit_part in ('day', 'days', 'd'):
        return datetime.timedelta(days=num)
    if unit_part in ('week', 'weeks', 'w'):
        return datetime.timedelta(weeks=num)
    if unit_part in ('month', 'months', 'mo', 'mos'):
        return datetime.timedelta(days=30 * num)
    if unit_part in ('year', 'years', 'yr', 'yrs', 'y'):
        return datetime.timedelta(days=365 * num)

    raise ValueError(f"Unsupported unit '{unit_part}' in frequency '{frequency}'")

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip()
        if freq_str.lower() == "always":
            return None
    else:
        raise ValueError(f"frequency must be a string or None, got {type(frequency)}")

    import re

    pattern = r'^\s*(?P<num>[-+]?\d+(?:\.\d+)?)\s*(?P<unit>\w+)\s*$'
    match = re.match(pattern, freq_str, re.IGNORECASE)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    num_str = match.group('num')
    unit_str = match.group('unit').lower()

    # Convert numeric part
    try:
        if '.' in num_str or 'e' in num_str.lower():
            num_val = float(num_str)
        else:
            num_val = int(num_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: {num_str}")

    unit_map = {
        'week': 'weeks',
        'weeks': 'weeks',
        'day': 'days',
        'days': 'days',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
        'millisecond': 'milliseconds',
        'milliseconds': 'milliseconds',
        'microsecond': 'microseconds',
        'microseconds': 'microseconds',
        'month': 'month',
        'months': 'month',
    }

    if unit_str not in unit_map:
        raise ValueError(f"Unknown unit in frequency: {unit_str}")

    key = unit_map[unit_str]
    if key == 'month':
        # Treat month as 30 days
        if isinstance(num_val, float) and not num_val.is_integer():
            # Non-integer months not supported for datetime.timedelta
            raise ValueError("Fractional months not supported")
        return datetime.timedelta(days=int(num_val) * 30)

    kwargs = {key: num_val}
    return datetime.timedelta(**kwargs)

