def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Quick checks for common localhost identifiers
        if isinstance(host, str):
            host_lc = host.lower()
            if host_lc in ("localhost", "127.0.0.1", "::1"):
                return True
        # Resolve host to one or more IP addresses
        try:
            addrinfo = socket.getaddrinfo(host, None, 0, 0, 0)
        except socket.gaierror:
            return False
        # Use ipaddress for robust loopback detection
        try:
            import ipaddress
        except Exception:
            return False
        for family, _, _, _, sockaddr in addrinfo:
            ip_str = sockaddr[0]
            try:
                ip_obj = ipaddress.ip_address(ip_str)
            except ValueError:
                continue
            if ip_obj.is_loopback:
                return True
        return False
    except Exception:
        # Any unexpected error defaults to False
        return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform
    all path fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:
      ['foo.txt', 'pp:root/somedir']
    ... transform that into:
      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        return []
    if not hasattr(find_paths, "__iter__") or isinstance(find_paths, (str, bytes)):
        raise TypeError("find_paths should be an iterable of strings")
    transformed = []
    for fragment in find_paths:
        if not isinstance(fragment, str):
            raise TypeError(f"Each fragment must be a string, got {type(fragment)}")
        # Treat anything containing ':' as an existing pattern and leave it unchanged
        if ':' in fragment:
            transformed.append(fragment)
        else:
            transformed.append(f'sh:**/*{fragment}*/**')
    return transformed

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything."""
    target_path = os.path.expanduser(config_filename)

    # Abort if file exists and overwrite is not allowed
    if not overwrite and os.path.isfile(target_path):
        return

    # Ensure parent directories exist
    parent_dir = os.path.dirname(target_path)
    if parent_dir:
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError:
            if not os.path.isdir(parent_dir):
                raise

    # Write the rendered configuration atomically
    temp_path = target_path + ".tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        os.chmod(temp_path, mode)
        os.replace(temp_path, target_path)
    finally:
        if os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass

    return target_path

