def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    try:
        if script is None:
            return ""
        # Allow script to be a list or string
        if isinstance(script, (list, tuple)):
            lines = script
        else:
            # Dedent multiline strings to normalise indentation
            lines = textwrap.dedent(script).splitlines()
        # Strip whitespace, ignore blank lines
        cleaned = [line.strip() for line in lines if line.strip()]
        return seperator.join(cleaned)
    except Exception as exc:
        # If any unexpected error, return empty string or propagate?
        # Here we choose to raise a ValueError to indicate misuse
        raise ValueError(f"oneline failed to process script: {exc}") from exc

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an EnvironmentError is raised.
    """
    # Extract name
    try:
        name = matcher.name  # attribute access
    except AttributeError:
        try:
            name = matcher['name']  # dict-like access
        except (KeyError, TypeError):
            try:
                name = matcher[0]  # tuple/list index
            except Exception as exc:
                raise ValueError('Matcher does not provide a variable name') from exc

    # Extract default
    default = None
    default_provided = False
    if hasattr(matcher, 'default'):
        default = matcher.default
        default_provided = True
    elif isinstance(matcher, dict) and 'default' in matcher:
        default = matcher['default']
        default_provided = True
    else:
        try:
            if len(matcher) > 1:
                default = matcher[1]
                default_provided = True
        except Exception:
            pass  # ignore if matcher not subscriptable

    # Retrieve environment value
    value = os.environ.get(name, default if default_provided else None)

    if value is None:
        if default_provided:
            return default
        raise EnvironmentError(f'Environment variable "{name}" not found and no default provided')
    return value

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine the variable name and optional default from various matcher formats.
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError("Matcher list/tuple must contain at least the variable name.")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError("Matcher dict must contain a 'name' key.")
        name = matcher['name']
        default = matcher.get('default')
    else:
        raise TypeError("Matcher must be a list, tuple, or dict.")

    if not isinstance(name, str):
        raise TypeError("Variable name must be a string.")

    value = os.getenv(name, default)
    if value is None and default is None:
        raise KeyError(f"Environment variable '{name}' not found and no default provided")

    return value

def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Try to extract 'name' and optional 'default' from the matcher.
    try:
        name = matcher.group("name")
    except AttributeError:
        name = getattr(matcher, "name", None)

    if name is None:
        raise ValueError("Matcher must provide a variable name")

    try:
        default = matcher.group("default")
    except AttributeError:
        default = getattr(matcher, "default", None)

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise EnvironmentError(f"environment variable '{name}' not found and no default provided")
    return value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.
    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")
    parsed = urllib.parse.urlparse(image_href)
    if parsed.scheme not in ("http", "https"):
        raise ValueError("image_href must include http or https scheme")
    if not parsed.netloc:
        raise ValueError("image_href missing network location")
    netloc = parsed.netloc.lower()
    use_ssl = parsed.scheme.lower() == "https"
    path = parsed.path
    if not path:
        raise ValueError("image_href missing path")
    path = path.lstrip("/")
    if not path:
        raise ValueError("image_href missing path segment")
    filename = path.split("/")[-1]
    if "." in filename:
        image_id = filename.split(".", 1)[0]
    else:
        image_id = filename
    if not image_id:
        raise ValueError("image_href missing image id")
    return image_id, netloc, use_ssl

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # Determine the regex pattern type for isinstance checks
    PatternType = getattr(re, "Pattern", getattr(re, "_pattern_type", None))
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    elif PatternType is not None and isinstance(pattern, PatternType):
        return pattern
    else:
        raise TypeError(f"Invalid pattern type: {type(pattern)}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, list) or not all(isinstance(c, str) for c in commands):
        raise TypeError("commands must be a list of strings")
    if not isinstance(args, list) or not all(isinstance(a, str) for a in args):
        raise TypeError("args must be a list of strings")

    # Build the command list
    cmd = commands + args

    if verbose:
        print("Running command:", " ".join(cmd))

    stderr_option = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as exc:
        msg_parts = [f"Command '{' '.join(cmd)}' failed with return code {exc.returncode}."]
        if exc.stdout:
            msg_parts.append(f"Stdout:\n{exc.stdout}")
        if exc.stderr:
            msg_parts.append(f"Stderr:\n{exc.stderr}")
        raise RuntimeError(" ".join(msg_parts)) from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error running command '{' '.join(cmd)}': {exc}") from exc

