def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Choose a Dumper class: default to yaml.SafeDumper if no dumper is provided
    if dumper is None:
        dumper_cls = yaml.SafeDumper
    else:
        dumper_cls = dumper

    try:
        yaml_str = yaml.dump(
            obj,
            Dumper=dumper_cls,
            default_flow_style=False,
            allow_unicode=True
        )
    except yaml.YAMLError as exc:
        raise RuntimeError(f"YAML dumping error: {exc}") from exc

    # In Python 2, yaml.dump returns a byte string. Convert to unicode.
    if isinstance(yaml_str, bytes):
        try:
            yaml_str = yaml_str.decode("utf-8")
        except Exception:
            yaml_str = yaml_str.decode("utf-8", errors="replace")

    return yaml_str

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        Shape of the array to create.
    dtype : numpy.dtype
        Data-type of the array to create.

    Returns
    -------
    numpy.ndarray
        An uninitialized array of the given shape and dtype.
    """
    # Validate shape input
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be a tuple or list of integers")
    try:
        shape = tuple(int(dim) for dim in shape)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"All dimensions in shape must be integers: {exc}") from exc
    for dim in shape:
        if dim < 0:
            raise ValueError("All dimensions in shape must be non-negative integers")

    # Ensure dtype is a np.dtype instance
    try:
        dtype = np.dtype(dtype)
    except TypeError as exc:
        raise ValueError(f"Invalid dtype specified: {exc}") from exc

    try:
        return np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape} and dtype {dtype}: {exc}") from exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        if shape is None:
            raise ValueError("Shape cannot be None")
        shape_tuple = tuple(shape)
        for s in shape_tuple:
            if not isinstance(s, int) or s < 0:
                raise ValueError("Shape elements must be non-negative integers")
        dtype_np = np.dtype(dtype)
    except Exception as exc:
        raise ValueError(f"Invalid shape or dtype: {exc}") from exc

    try:
        return np.empty(shape_tuple, dtype=dtype_np)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array: {exc}") from exc

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input must be array-like or numeric") from e
    mean = 0.2
    sigma = 0.1
    if sigma <= 0:
        raise ValueError("Sigma must be positive")
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    return coeff * np.exp(-((arr - mean) ** 2) / (2 * sigma ** 2))

