def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    configs = {}
    error_records = []
    logger = logging.getLogger('config_loader')

    # Lazy imports of configuration parsers
    try:
        import yaml
    except Exception:
        yaml = None
    try:
        import toml
    except Exception:
        toml = None
    try:
        import json
    except Exception:
        json = None

    def _resolve_env_in_value(val):
        if isinstance(val, str):
            return os.path.expandvars(val)
        return val

    def _recursive_env_resolve(obj):
        if isinstance(obj, dict):
            return {k: _recursive_env_resolve(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_recursive_env_resolve(elem) for elem in obj]
        else:
            return _resolve_env_in_value(obj)

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as fd:
                raw = fd.read()
        except Exception as e:
            rec = logger.makeRecord(
                'config_loader',
                logging.ERROR,
                fname,
                0,
                f'Cannot read configuration file {fname}: {e}',
                args=None,
                exc_info=(type(e), e, e.__traceback__),
            )
            error_records.append(rec)
            continue

        parsed = None
        ext = os.path.splitext(fname)[1].lower()
        try:
            if ext in ('.yaml', '.yml') and yaml:
                parsed = yaml.safe_load(raw)
            elif ext == '.toml' and toml:
                parsed = toml.loads(raw)
            elif ext == '.json' and json:
                parsed = json.loads(raw)
            else:
                # Try yaml if available, else toml
                if yaml:
                    parsed = yaml.safe_load(raw)
                elif toml:
                    parsed = toml.loads(raw)
                else:
                    raise ValueError('No suitable parser available')
        except Exception as e:
            rec = logger.makeRecord(
                'config_loader',
                logging.ERROR,
                fname,
                0,
                f'Error parsing configuration file {fname}: {e}',
                args=None,
                exc_info=(type(e), e, e.__traceback__),
            )
            error_records.append(rec)
            continue

        if parsed is None:
            parsed = {}

        if resolve_env:
            try:
                parsed = _recursive_env_resolve(parsed)
            except Exception as e:
                rec = logger.makeRecord(
                    'config_loader',
                    logging.ERROR,
                    fname,
                    0,
                    f'Error resolving environment variables in {fname}: {e}',
                    args=None,
                    exc_info=(type(e), e, e.__traceback__),
                )
                error_records.append(rec)

        if overrides and isinstance(overrides, dict):
            try:
                parsed.update(overrides)
            except Exception as e:
                rec = logger.makeRecord(
                    'config_loader',
                    logging.ERROR,
                    fname,
                    0,
                    f'Error applying overrides to {fname}: {e}',
                    args=None,
                    exc_info=(type(e), e, e.__traceback__),
                )
                error_records.append(rec)

        configs[fname] = parsed

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    error_records = []

    for cfg_file in config_filenames:
        try:
            with open(cfg_file, 'r', encoding='utf-8') as fd:
                raw = fd.read()
        except Exception as exc:
            rec = logging.LogRecord('config_parser',
                                    logging.ERROR,
                                    cfg_file, 0,
                                    f'Could not read file: {exc}', None, exc)
            error_records.append(rec)
            continue

        try:
            if cfg_file.lower().endswith('.json'):
                parsed = json.loads(raw)
            elif cfg_file.lower().endswith(('.yaml', '.yml')):
                parsed = yaml.safe_load(raw)
            elif cfg_file.lower().endswith('.toml'):
                parsed = toml.loads(raw)
            else:
                raise ValueError(f'Unsupported file type: {cfg_file}')
        except Exception as exc:
            rec = logging.LogRecord('config_parser',
                                    logging.ERROR,
                                    cfg_file, 0,
                                    f'Parse error: {exc}', None, exc)
            error_records.append(rec)
            continue

        # Resolve environment variables if requested
        if resolve_env:
            def _resolve(obj):
                if isinstance(obj, str):
                    return os.path.expandvars(obj)
                if isinstance(obj, dict):
                    return {k: _resolve(v) for k, v in obj.items()}
                if isinstance(obj, list):
                    return [_resolve(i) for i in obj]
                return obj
            parsed = _resolve(parsed)

        # Apply overrides if any
        if overrides and cfg_file in overrides:
            override = overrides[cfg_file]
            if isinstance(parsed, dict) and isinstance(override, dict):
                parsed.update(override)

        configs[cfg_file] = parsed

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed
    configuration, and sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging
    configs = {}
    records = []

    # Helper function to create a LogRecord for an error
    def _make_record(filename, exc, msg=None):
        exc_info = None
        if exc is not None:
            exc_info = (__import__('sys').exc_info())
        return logging.LogRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=msg or str(exc),
            args=(),
            exc_info=exc_info
        )

    for fn in config_filenames:
        try:
            with open(fn, 'r') as f:
                raw = f.read()
        except Exception as exc:
            records.append(_make_record(fn, exc))
            continue

        try:
            if fn.endswith('.toml'):
                toml = __import__('toml')
                cfg = toml.loads(raw)
            elif fn.endswith(('.yaml', '.yml')):
                yaml = __import__('yaml')
                cfg = yaml.safe_load(raw)
            else:
                raise ValueError(f"Unsupported file extension for {fn}")
        except Exception as exc:
            records.append(_make_record(fn, exc))
            continue

        if not isinstance(cfg, dict):
            records.append(_make_record(fn, None,
                f"Parsed configuration in {fn} is not a dictionary."))
            continue

        if resolve_env:
            import os
            def resolve(value):
                if isinstance(value, str):
                    return os.path.expandvars(value)
                if isinstance(value, dict):
                    return {k: resolve(v) for k, v in value.items()}
                if isinstance(value, list):
                    return [resolve(v) for v in value]
                return value
            cfg = resolve(cfg)

        if overrides:
            cfg.update(overrides)

        configs[fn] = cfg

    return configs, records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    parsed_configs = {}
    error_records = []

    # Helper to recursively expand environment variables in a configuration structure
    def _expand_env(value):
        import os
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_expand_env(item) for item in value]
        elif isinstance(value, str):
            return os.path.expandvars(value)
        else:
            return value

    for cfg_file in config_filenames:
        try:
            with open(cfg_file, 'r') as fd:
                raw = fd.read()

            # Parse based on file extension; fall back to yaml or toml if unable
            ext = cfg_file.split('.')[-1].lower()
            if ext == 'toml':
                import toml
                config = toml.loads(raw)
            elif ext in ('yaml', 'yml'):
                import yaml
                config = yaml.safe_load(raw)
            else:
                # Try YAML first, then TOML
                try:
                    import yaml
                    config = yaml.safe_load(raw)
                except Exception:
                    try:
                        import toml
                        config = toml.loads(raw)
                    except Exception:
                        raise ValueError(f"Unsupported file format: {cfg_file}")

            # Some loaders return None for empty files; coerce to empty dict
            if config is None:
                config = {}

            # Resolve environment variables if requested
            if resolve_env:
                config = _expand_env(config)

            # Merge overrides if provided
            if overrides and cfg_file in overrides:
                if isinstance(overrides[cfg_file], dict):
                    config.update(overrides[cfg_file])

            parsed_configs[cfg_file] = config

        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=cfg_file,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=exc
            )
            error_records.append(record)

    return parsed_configs, error_records

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple (major, minor) or None")

    # Attempt to get a pre‑registered mapping, if one exists
    handlers = getattr(cls, "_protocol_handlers", None)

    if not handlers:
        # Build the mapping by inspecting class attributes that look
        # like protocol handler subclasses.  A handler is considered to
        # define a protocol version if it has a `_protocol_version`
        # attribute of the form (major, minor).  Other attributes or
        # values are ignored.
        handlers = {}
        for name, value in cls.__dict__.items():
            if isinstance(value, type) and hasattr(value, "_protocol_version"):
                ver = value._protocol_version
                # Only use the handler if the version is a valid tuple.
                if isinstance(ver, tuple) and len(ver) == 2:
                    handlers[ver] = value

    # Return the desired subset of the mapping
    if protocol_version is None:
        return handlers.copy()
    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

def protocol_handlers(cls, protocol_version=None):
        """Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        handlers = {}
        # Search for handler classes defined on the class.
        for attr_name, attr_val in cls.__dict__.items():
            if isinstance(attr_val, type):
                # Look for a protocol version marker (common patterns)
                version = (
                    getattr(attr_val, "_bolt_protocol_version", None) or
                    getattr(attr_val, "bolt_protocol_version", None) or
                    getattr(attr_val, "protocol_version", None)
                )
                if isinstance(version, tuple) and len(version) == 2:
                    handlers[tuple(version)] = attr_val
        # If a specific protocol version is requested, filter the dict.
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
                )
            if len(protocol_version) != 2:
                raise TypeError(
                    f"protocol_version tuple must be of length 2, got {len(protocol_version)}"
                )
            return {tuple(protocol_version): handlers[tuple(protocol_version)]
                    } if tuple(protocol_version) in handlers else {}
        return handlers

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Default holder for protocol handler mapping, should be defined
    # on the subclass or in this class.
    handlers = getattr(cls, "_protocol_handlers", {})
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        # Optional: enforce tuple of two integers
        if len(protocol_version) != 2 or not all(isinstance(v, int) for v in protocol_version):
            raise TypeError(
                f"protocol_version must be a tuple of two integers, got {protocol_version}"
            )
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}
    # Return a copy of all handlers if no specific version requested
    return dict(handlers)

