def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a list or tuple (sequence types), return as is
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq))

    # If seq is a string or bytes, treat it as a string type
    if isinstance(seq, (str, bytes, bytearray)):
        return (seq, type(seq))

    # If seq is an iterable but not string/bytes, convert to a list
    # We allow optional bufsize to limit processing for generators
    try:
        if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes, bytearray)):
            if bufsize is not None:
                # lazily read up to bufsize elements if seq is a generator/iterator
                from itertools import islice
                seq_list = list(islice(seq, bufsize))
                # If seq had more items beyond bufsize, keep a reference to the iterator
                # to allow further consumption if needed
                remaining_iter = None
                try:
                    remaining_iter = seq  # assume seq supports __next__
                except Exception:
                    remaining_iter = None
                if remaining_iter is not None:
                    # Attach remaining iterator to list via attribute for later retrieval
                    seq_list._remaining_iter = remaining_iter
                return (seq_list, type(seq))
            else:
                return (list(seq), type(seq))
    except Exception:
        # If any error occurs, just treat seq as a single-element sequence
        return ([seq], type(seq))

    # Fallback: treat seq as a single element sequence
    return ([seq], type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a
    sequence type).
    """
    # If seq is already one of the recognized sequence types,
    # return it unchanged along with its type.
    if isinstance(seq, (list, tuple, str)):
        return (seq, type(seq))

    # For other iterables (generators, iterators, etc.) we need to
    # materialise them into a list, respecting an optional buffer size.
    try:
        # Prepare a list to hold the items
        seq_list = []
        # If bufsize is provided and valid, limit the number of
        # elements that are copied
        if bufsize is None or bufsize <= 0:
            seq_list.extend(seq)  # consumes the entire iterable
        else:
            for i, element in enumerate(seq):
                seq_list.append(element)
                if i + 1 >= bufsize:
                    break
        return (seq_list, type(seq))
    except TypeError as exc:
        # seq is not iterable
        raise TypeError(f"Object {seq!r} must be iterable for _get_seq_with_type") from exc

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Helper to detect a non-string sequence type
    def _is_sequence(value):
        return (hasattr(value, "__iter__") and not isinstance(value, (str, bytes)))

    # If seq is None, return None tuple
    if seq is None:
        return (None, None)

    try:
        if _is_sequence(seq):
            # Sequence already, return as is
            return (seq, type(seq))
        else:
            # Try to convert to list (or another sequence type)
            seq_obj = list(seq)
            return (seq_obj, type(seq_obj))
    except Exception as exc:
        # If conversion fails, return original and its type
        return (seq, type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("Input sequence is None")
    # If already a list or tuple, return it unchanged
    if isinstance(seq, (list, tuple)):
        return seq, type(seq).__name__
    # If it's a string or bytes, keep it as is
    if isinstance(seq, (str, bytes)):
        # For very large strings we may want to materialise them
        if bufsize is not None and len(seq) > bufsize:
            return list(seq), type(seq).__name__
        return seq, type(seq).__name__
    # For any other iterable, convert to list
    try:
        seq_list = list(seq)
    except Exception as exc:
        raise ValueError(f"Unable to interpret sequence: {seq!r}") from exc
    return seq_list, 'iterable'

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("seq cannot be None")
    # Determine whether seq is a sequence type (excluding string-like types)
    try:
        is_seq = hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes, bytearray))
    except Exception:
        is_seq = False
    if is_seq:
        return (seq, type(seq).__name__)

    # seq is not a sequence; handle according to bufsize
    if bufsize is None:
        # Return the element wrapped in a one-element sequence
        return ([seq], 'single_value')

    # bufsize specified – attempt to split seq into chunks of given size
    if not isinstance(bufsize, int) or bufsize <= 0:
        raise ValueError("bufsize must be a positive integer")
    try:
        iterator = iter(seq)
    except TypeError:
        # seq is not iterable; fall back to wrapping it in a list
        return ([seq], 'single_value')

    chunks = []
    current = []
    for idx, item in enumerate(iterator, 1):
        current.append(item)
        if idx % bufsize == 0:
            chunks.append(current)
            current = []
    if current:
        chunks.append(current)

    return (chunks, f'chunked_{bufsize}')

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # If no new scale requested, simply return the current scale.
    if other is None:
        return getattr(self, "scale", None)

    # Validate that the new scale is numeric.
    if not isinstance(other, (int, float)):
        raise TypeError(
            f"Provided scale must be numeric, got {type(other).__name__}"
        )

    # Ensure the graph currently has a known, non‑zero scale.
    current_scale = getattr(self, "scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError(
            "Cannot rescale graph with an unknown or zero scale."
        )

    # Compute the scaling factor required to reach the desired scale.
    factor = other / current_scale

    # Identify the last coordinate that exists on this graph.
    # We check z, then y, then x to figure out “last”.
    coord_order = ["z", "y", "x"]
    last_coord = None
    for coord in coord_order:
        if hasattr(self, coord):
            last_coord = coord
            break
    if last_coord is None:
        raise LenaValueError("Graph has no coordinate to rescale.")

    # Rescale the coordinate values.
    try:
        orig_values = getattr(self, last_coord)
        setattr(self, last_coord, orig_values * factor)
    except Exception as exc:
        raise LenaValueError(
            f"Failed to rescale coordinate '{last_coord}': {exc}"
        ) from exc

    # Rescale any errors that accompany this coordinate.
    # Attempt common patterns: a dict named 'errors'.
    errors = getattr(self, "errors", None)
    if isinstance(errors, dict) and last_coord in errors:
        try:
            errors[last_coord] = errors[last_coord] * factor
        except Exception:
            pass

    # Also check attribute naming patterns for individual error arrays.
    for err_attr in (f"{last_coord}_err", f"{last_coord}error"):
        if hasattr(self, err_attr):
            try:
                err_val = getattr(self, err_attr)
                setattr(self, err_attr, err_val * factor)
            except Exception:
                pass

    # Update the graph's scale to the new value.
    self.scale = other
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    See docstring for details.
    """
    # Validate get_coordinate
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    # Resolve histogram bins
    try:
        bins = getattr(hist, "bins")
    except AttributeError:
        try:
            bins = hist["bins"]
        except Exception:
            raise TypeError("hist must provide a 'bins' attribute or mapping")

    # Prepare storage for graph points
    points = []

    # Determine default make_value if none provided
    if make_value is None:
        def make_value_default(bin_val):
            # Try common attribute names
            for attr in ("content", "value", "count", "height", "size"):
                if hasattr(bin_val, attr):
                    return getattr(bin_val, attr)
            # Try numeric index
            try:
                return bin_val[-1]
            except Exception:
                raise ValueError("Unable to determine bin value")
        make_value = make_value_default

    # Determine scale for graph
    graph_scale = None
    if scale is True:
        graph_scale = getattr(hist, "scale", None)

    # Iterate over histogram bins
    for bin_obj in bins:
        # Extract left, right, and bin value
        try:
            left = getattr(bin_obj, "left")
            right = getattr(bin_obj, "right")
        except Exception:
            try:
                left, right = bin_obj[:2]
            except Exception:
                raise ValueError("Cannot determine bin boundaries")

        # Determine bin value (without context)
        try:
            bin_val = make_value(bin_obj)
        except Exception as e:
            raise ValueError(f"Error invoking make_value: {e}")

        # Get coordinate of graph point
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:  # middle
            coord = (left + right) / 2.0

        # Build point values
        if isinstance(bin_val, (list, tuple)):
            point_values = [coord] + list(bin_val)
        else:
            point_values = [coord, bin_val]

        points.append(tuple(point_values))

    # Assemble the result graph
    # The function returns a simple dictionary mimicking a graph object.
    graph = {
        "field_names": field_names,
        "scale": graph_scale,
        "points": points,
    }

    return graph

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    collected_errors = []

    # Check interface provision claim (unless tentative)
    try:
        provided_by = iface.providedBy
    except Exception:
        provided_by = None

    if not tentative and provided_by is not None:
        try:
            if not provided_by(candidate):
                collected_errors.append(
                    f"{candidate} does not claim to provide {iface}"
                )
        except Exception as exc:
            collected_errors.append(
                f"Error checking providedBy for {candidate}: {exc}"
            )

    # Iterate over all interface members
    try:
        members = dict(iface.items())
    except Exception:
        members = {}

    for name, iface_obj in members.items():
        if not hasattr(candidate, name):
            collected_errors.append(
                f"{candidate} is missing required member '{name}'"
            )
            continue

        # If the interface member has a signature attribute, treat it as a method.
        # In zope.interface, MethodInterface objects have a 'signature'
        # attribute which is an inspect.Signature instance (or None).
        signature_attr = getattr(iface_obj, "signature", None)

        if signature_attr is not None:
            attr = getattr(candidate, name)
            if not callable(attr):
                collected_errors.append(
                    f"'{name}' should be callable on {candidate}, "
                    f"but is of type {type(attr).__name__}"
                )
                continue

            # Simple signature checking: compare number of positional parameters
            # only if the interface signature is an inspect.Signature instance.
            try:
                if hasattr(signature_attr, "parameters"):
                    iface_params = list(
                        signature_attr.parameters.items()
                    )
                    # find the candidate's signature
                    cand_sig = getattr(attr, "__signature__", None)
                    if cand_sig is None:
                        # attempt to introspect
                        cand_sig = \
                            __import__("inspect").signature(attr)
                    cand_params = [
                        p
                        for p in cand_sig.parameters.values()
                        if p.kind in (
                            __import__("inspect").Parameter.POSITIONAL_OR_KEYWORD,
                            __import__("inspect").Parameter.POSITIONAL_ONLY,
                        )
                    ]
                    # positional required parameters must be enough
                    required_iface_params = [
                        p for p in iface_params if p[1].default is __import__("inspect").Parameter.empty
                    ]
                    if len(cand_params) < len(required_iface_params):
                        collected_errors.append(
                            f"Method '{name}' of {candidate} has insufficient "
                            f"positional arguments compared to interface definition"
                        )
            except Exception:
                # If any introspection fails, we skip detailed signature check.
                pass

    if collected_errors:
        if len(collected_errors) == 1:
            raise zope.interface.Invalid(collected_errors[0])
        else:
            message = "Multiple validation errors: " + "; ".join(collected_errors)
            raise zope.interface.Invalid(message)

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    * `iface` must be a class (or any type that can be passed to
      :func:`issubclass`/`isinstance`).  The function checks that
      `candidate` either is a subclass of `iface` or implements all
      attributes and methods defined on `iface`.  If *tentative* is
      ``True``, the check is lenient: non‑callable attributes missing
      from `candidate` are ignored, but missing required methods raise
      an exception.

    Raises
    ------
    TypeError
        If `iface` is not a class or `candidate` does not provide the
        required interface.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")

    # Determine whether candidate is a class or an instance
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Quick check for subclass or instance compatibility
    try:
        if issubclass(candidate_cls, iface):
            return
    except TypeError:
        pass

    # Verify that all attributes defined on iface exist on candidate
    missing = []
    for name in dir(iface):
        # Skip special methods unless they are defined on iface
        if name.startswith("__") and name.endswith("__"):
            if not hasattr(iface, name):
                continue
        iface_attr = getattr(iface, name, None)
        try:
            cand_attr = getattr(candidate_cls, name)
        except AttributeError:
            # For instances, try the object itself
            try:
                cand_attr = getattr(candidate, name)
            except AttributeError:
                if tentative and not callable(iface_attr):
                    continue
                missing.append(name)
                continue
        if callable(iface_attr):
            if not callable(cand_attr):
                missing.append(name)

    if missing:
        missing_str = ", ".join(missing)
        raise TypeError(f"Candidate {candidate_cls.__name__ if isinstance(candidate, type) else candidate} does not implement required members: {missing_str}")
    # If we reach here, candidate passes the verification
    return

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Ensure iface is a class or type
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class or type, got {type(iface).__name__}")

    # Decide which object to test (class or instance)
    if isinstance(candidate, type):
        test_obj = candidate
    else:
        test_obj = candidate.__class__

    # Gather public attributes/methods of iface
    required_names = [
        name for name in dir(iface)
        if not name.startswith("_")
    ]

    for name in required_names:
        # Skip if it's an attribute defined in the base object that is not relevant
        if name in ("__dict__", "__weakref__", "__module__", "__doc__"):
            continue

        # Check existence
        if not hasattr(test_obj, name):
            if tentative:
                return False
            raise ValueError(f"Candidate {candidate} is missing required attribute '{name}' from interface {iface.__name__}")

        # If the attribute is a method in iface, ensure candidate's is callable
        iface_attr = getattr(iface, name)
        cand_attr = getattr(test_obj, name)

        # Use inspect is not allowed; we rely on callable
        if callable(iface_attr) and not callable(cand_attr):
            if tentative:
                return False
            raise ValueError(f"Attribute '{name}' in candidate {candidate} should be callable to satisfy interface {iface.__name__}")

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass was supplied, honor it – but ensure it is a type
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit_metaclass must be a type, got %r" % explicit_mc)
        return explicit_mc

    # No bases provided: default to the built‑in type metaclass
    if not bases:
        return type

    # Gather candidate metaclasses from each base.
    metaclasses = []
    for base in bases:
        try:
            # In some code bases bases might not be class objects; handle gracefully.
            base_cls = type(base)
        except Exception:
            raise TypeError("base must be a class type, got %r" % base)
        # Prefer an explicit __metaclass__ attribute if present
        mc = getattr(base, "__metaclass__", None)
        if mc is not None:
            if not isinstance(mc, type):
                raise TypeError(
                    "__metaclass__ attribute on base %r must be a type, got %r" % (base, mc)
                )
            metaclasses.append(mc)
        else:
            metaclasses.append(base_cls)

    # Resolve the most derived metaclass that satisfies all candidates.
    chosen = metaclasses[0]
    for mc in metaclasses[1:]:
        # If the candidate is a subclass of the current chosen metaclass,
        # it is more derived – adopt it.
        if isinstance(mc, chosen):
            chosen = mc
        # If neither is a subclass of the other, a conflict exists.
        elif not isinstance(chosen, mc):
            raise TypeError(
                "metaclass conflict among bases: %r and %r"
                % (metaclasses[0], metaclasses[1])
            )

    # In the unlikely event that resolution fails, fall back to `type`.
    if not isinstance(chosen, type):
        return type
    return chosen

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it (after validation)
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(
                f"Explicit metaclass must be a type, not {type(explicit_mc)!r}"
            )
        return explicit_mc

    # No explicit metaclass; determine from bases
    if not bases:
        # No bases -> default is 'type'
        return type

    # Gather metaclasses of all base types
    metaclasses = set()
    for base in bases:
        try:
            metaclasses.add(base.__class__)   # metaclass of the base
        except Exception as exc:
            raise TypeError(f"Unable to determine metaclass of base {base!r}: {exc}") from exc

    # If only one unique metaclass, use it
    if len(metaclasses) == 1:
        return next(iter(metaclasses))

    # Resolve metaclass conflict: find a metaclass that is a superclass of all others
    # The algorithm is equivalent to Python's mro-based search
    for candidate in list(metaclasses):
        try:
            if all(issubclass(other, candidate) for other in metaclasses):
                return candidate
        except TypeError:
            # In case issubclass fails because of non-type objects, skip
            continue

    # If no common super-metadata found, fallback to topmost metaclass in MRO order
    # Build MRO of each metaclass and find first common ancestor
    try:
        common = None
        for candidate in list(metaclasses):
            mro = candidate.mro()
            if common is None:
                common = set(mro)
            else:
                common &= set(mro)
        if common:
            # Prefer the most derived (first in MRO) among commons
            return next(m for m in candidate.mro() if m in common)
    except Exception:
        pass

    # As a last resort, raise an informative error
    metaclass_names = ", ".join(m.__name__ for m in metaclasses)
    raise TypeError(
        f"Metaclass conflict: multiple metaclasses found: {metaclass_names}"
    )

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    try:
        val = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return val

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        if key in self:
            value = self[key]
            del self[key]
            return value
        if default is not __marker:
            return default
        raise KeyError(key)
    except Exception as exc:
        # Re‑raise any unexpected exception to aid debugging
        raise exc from None

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    # Attempt to use a frequency mapping if available
    freq = getattr(self, "_freq", None)
    try:
        if isinstance(freq, dict) and freq:
            # Find key with smallest frequency count
            least_key = min(freq, key=freq.get)
        else:
            # Fallback to an arbitrary key (first in insertion order)
            least_key = next(iter(self))
    except Exception:
        # If something goes wrong, fall back to the first key again
        least_key = next(iter(self))
    # Get the value and remove the key
    value = self[least_key]
    del self[least_key]
    # Remove from frequency map if present
    if isinstance(freq, dict) and least_key in freq:
        del freq[least_key]
    return least_key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    # Determine the key with the lowest frequency
    min_key = None
    min_freq = None
    freq_map = getattr(self, "_freq", {})
    for key, _ in self.items():
        freq = freq_map.get(key, 0)
        if min_freq is None or freq < min_freq:
            min_freq = freq
            min_key = key
    if min_key is None:
        raise KeyError('dictionary is empty')
    value = self.pop(min_key)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # If the instance stores an OrderedDict (common for LRU caches),
    # prefer popping from it to preserve LRU semantics.
    if hasattr(self, "_cache"):
        cache = self._cache
        # OrderedDict has popitem with last parameter
        if hasattr(cache, "popitem") and callable(cache.popitem):
            try:
                return cache.popitem(last=False)
            except TypeError:
                # Fallback if last parameter not supported
                pass
    # Fallback to generic dict behavior: pop the first item in iteration order.
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")
    value = self[key]
    del self[key]
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        # Expect an OrderedDict-like container for LRU storage
        return self._cache.popitem(last=False)
    except AttributeError:
        # Fallback to a plain dict-like interface
        if not self:
            raise KeyError("dictionary is empty")
        key = next(iter(self))
        value = self[key]
        del self[key]
        return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Assume the LRU store is backed by an OrderedDict stored in `self._data`.
    if not hasattr(self, "_data"):
        raise AttributeError("Expected an attribute `_data` backed by an OrderedDict.")
    try:
        # `popitem(last=False)` removes the first (least recently used) item.
        return self._data.popitem(last=False)
    except KeyError:
        # Raised if the cache/dict is empty.
        raise KeyError("LRU cache is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self:
        raise KeyError('LRU cache is empty')
    key = next(iter(self))
    try:
        value = self[key]
    except KeyError:
        # In case the mapping changed between iterating and accessing
        raise KeyError(f"Key {key!r} not found during popitem")
    del self[key]
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to use the built‑in dict implementation (works for dict subclasses)
    try:
        return dict.popitem(self)
    except TypeError:
        # Fallback for custom containers that expose an OrderedDict named _data
        if hasattr(self, "_data") and hasattr(self._data, "popitem"):
            return self._data.popitem(last=True)
        # If neither works, re‑raise a clear error
        raise TypeError("popitem not supported for this object's structure") from None

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Expect the class to maintain an ordered mapping of keys to values
    # where most recently used items are at the end.
    if not hasattr(self, "_order"):
        raise AttributeError("Missing _order attribute in the instance.")
    try:
        key, value = self._order.popitem(last=True)
        return key, value
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")

def popitem(self):
    """Release and return the `(key, value)` pair that was most recently used."""
    try:
        key, value = dict.popitem(self)
        return key, value
    except KeyError as e:
        raise KeyError('dict is empty') from e

def popitem(self):
        """Remove and return the `(key, value)` pair most recently used."""
        try:
            # Assuming the cache uses an OrderedDict named `_store`
            # where the most recently used item is at the end.
            return self._store.popitem(last=True)
        except KeyError:
            raise KeyError('popitem() called on an empty cache')

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # The class is expected to store items in an ordered container
    # where the most recently used item is at the end.
    try:
        # If the storage is an OrderedDict (or similar) use popitem
        return self._cache.popitem(last=True)
    except AttributeError as exc:
        # Fallback: try a generic dict if one is present
        if hasattr(self, '_store') and isinstance(self._store, dict):
            # Pop the last inserted key in a dict (Python 3.7+ preserves insertion order)
            try:
                key, value = next(reversed(self._store.items()))
                del self._store[key]
                return key, value
            except StopIteration:
                raise KeyError("popitem from an empty container") from exc
        else:
            raise TypeError("Underlying storage is not defined or not ordered") from exc
    except KeyError:
        # Raised when the underlying mapping is empty
        raise KeyError("popitem from an empty container")

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dict is empty')
    import random
    key = random.choice(list(self.keys()))
    return key, self.pop(key)

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches an "in" keyword followed by a parenthesized
        # comma-separated list.  The list is captured in the first group.
        # Example: "IN (1, 2, 3)" or "in (foo, bar)"
        pattern = r'\bin\b\s*\(([^)]*)\)'
        return re.compile(pattern, re.IGNORECASE | re.DOTALL)
    except re.error as exc:
        # Re-raise a ValueError with a clearer message
        raise ValueError(f"Failed to compile IN-style regex: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    # Attempt to instantiate the converter.  If the constructor requires
    # additional configuration this should be added here.
    try:
        return _converting._Converter()
    except Exception as exc:
        raise RuntimeError(
            "Failed to create parameter style converter"
        ) from exc

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter = _converting._Converter()
    except Exception as exc:
        raise RuntimeError("Failed to create Converter: {}".format(exc)) from exc

    if converter is None:
        raise RuntimeError("Converter is None after creation")

    return converter

def isoparse(self, dt_str):
    """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    Supported formats are described in the full documentation.
    """
    import re
    from datetime import datetime, date, time, timedelta
    from dateutil.tz import tzutc, tzoffset

    if hasattr(dt_str, "read"):
        dt_str = dt_str.read()
    dt_str = dt_str.strip()

    if not dt_str:
        raise ValueError("Empty datetime string")

    # Split timezone
    tzinfo = None
    tz_match = re.search(r"(Z|[+-]\d{2}(?::?\d{2})?)$", dt_str)
    if tz_match:
        tz_part = tz_match.group(1)
        dt_str_main = dt_str[:tz_match.start()]
    else:
        tz_part = None
        dt_str_main = dt_str

    # Parse timezone part
    if tz_part == "Z":
        tzinfo = tzutc()
    elif tz_part:
        sign = 1 if tz_part[0] == "+" else -1
        rest = tz_part[1:]
        if ":" in rest:
            hh, mm = rest.split(":")
        else:
            if len(rest) == 2:  # HH
                hh, mm = rest, "00"
            elif len(rest) == 4:  # HHMM
                hh, mm = rest[:2], rest[2:]
            else:
                raise ValueError(f"Invalid timezone {tz_part!r}")
        try:
            hour_offset = int(hh) * sign
            minute_offset = int(mm) * sign
        except ValueError:
            raise ValueError(f"Invalid timezone offsets in {tz_part!r}")
        offset_seconds = hour_offset * 3600 + minute_offset * 60
        if offset_seconds == 0:
            tzinfo = tzutc()
        else:
            tzinfo = tzoffset(None, offset_seconds)

    # Split date and time
    sep_match = re.search(r"[Tt ]", dt_str_main)
    if sep_match:
        date_part = dt_str_main[:sep_match.start()]
        time_part = dt_str_main[sep_match.end():]
    else:
        date_part = dt_str_main
        time_part = None

    # Parse date
    def parse_date(date_str):
        if "W" in date_str or "w" in date_str:
            # Week date
            w = re.split("[Ww-]", date_str)
            if len(w) < 2:
                raise ValueError(f"Invalid week date {date_str!r}")
            year = int(w[0])
            week = int(w[1])
            day = int(w[2]) if len(w) > 2 else 1
            try:
                return date.fromisocalendar(year, week, day)
            except Exception as e:
                raise ValueError(f"Invalid ISO week date {date_str!r}") from e
        # Calendar date
        if "-" in date_str:
            parts = date_str.split("-")
        else:
            parts = [date_str[:4]]
            if len(date_str) > 4:
                parts.append(date_str[4:6])
            if len(date_str) > 6:
                parts.append(date_str[6:8])
        try:
            year = int(parts[0])
            month = int(parts[1]) if len(parts) > 1 else 1
            day = int(parts[2]) if len(parts) > 2 else 1
            return date(year, month, day)
        except Exception as e:
            raise ValueError(f"Invalid date {date_str!r}") from e

    parsed_date = parse_date(date_part)

    # Parse time
    def parse_time(time_str):
        if not time_str:
            return 0, 0, 0, 0, 0  # hour, minute, second, microsecond, day_offset
        day_offset = 0
        # Handle decimal separator
        if "." in time_str or "," in time_str:
            sep = "." if "." in time_str else ","
            before, frac = time_str.split(sep, 1)
            micro = int((frac + "000000")[:6])
        else:
            before = time_str
            micro = 0

        if ":" in before:
            parts = before.split(":")
            if len(parts) == 1:
                hour = int(parts[0])
                minute = 0
                second = 0
            elif len(parts) == 2:
                hour, minute = map(int, parts)
                second = 0
            elif len(parts) == 3:
                hour, minute, second = map(int, parts)
            else:
                raise ValueError(f"Invalid time {time_str!r}")
        else:
            if len(before) == 2:
                hour = int(before)
                minute = 0
                second = 0
            elif len(before) == 4:
                hour = int(before[:2])
                minute = int(before[2:])
                second = 0
            elif len(before) == 6:
                hour = int(before[:2])
                minute = int(before[2:4])
                second = int(before[4:])
            else:
                raise ValueError(f"Invalid time {time_str!r}")

        if hour == 24:
            if minute or second or micro:
                raise ValueError("24 hour only allowed with 00 minute, 00 second, 0 microsecond")
            hour = 0
            day_offset = 1

        return hour, minute, second, micro, day_offset

    hour, minute, second, microsecond, day_offset = parse_time(time_part)

    try:
        dt = datetime(parsed_date.year, parsed_date.month, parsed_date.day,
                      hour, minute, second, microsecond,
                      tzinfo=tzinfo)
    except Exception as e:
        raise ValueError(f"Failed to construct datetime from components") from e

    if day_offset:
        dt += timedelta(days=day_offset)

    return dt

