def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime.datetime):
        raise TypeError(f"Expected datetime.datetime, got {type(dt).__name__}")
    # Ensure timezone aware, default to UTC if naive
    if dt.tzinfo is None:
        try:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        except Exception as exc:
            raise ValueError("Unable to make datetime timezone aware") from exc
    # Convert to UTC
    utc_dt = dt.astimezone(datetime.timezone.utc)
    # Format without microseconds if not needed
    if utc_dt.microsecond:
        return utc_dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    from datetime import datetime, timezone
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime instance")
    if dt.tzinfo is None:
        # Assume UTC for naive datetimes
        dt = dt.replace(tzinfo=timezone.utc)
    # Convert to UTC and format as ISO 8601 without fractional seconds
    return dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Ensure dt is a datetime-like object
    if not hasattr(dt, "tzinfo") or not hasattr(dt, "strftime"):
        raise TypeError("dt must be a datetime instance")
    # Convert to UTC if possible
    try:
        if dt.tzinfo is None:
            dt_utc = dt.replace(tzinfo=datetime.timezone.utc)
        else:
            dt_utc = dt.astimezone(datetime.timezone.utc)
    except Exception as exc:
        raise ValueError("Failed to convert dt to UTC") from exc
    # Build the string representation
    if dt_utc.microsecond:
        s = dt_utc.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        # Strip trailing zeros and dot if no fractional part remains
        s = s.rstrip("0").rstrip(".")
    else:
        s = dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    return s

def process_text_links(text):
    """Process links in text, adding target="_blank" attributes to anchor tags and converting textual URLs to links."""
    url_re = re.compile(r'(https?://[^\s<]+)')
    return url_re.sub(lambda m: f'<a href="{m.group(0)}" target="_blank" rel="noopener noreferrer">{m.group(0)}</a>', text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        return ""
    try:
        # Regex matches URLs starting with http://, https:// or www.
        url_regex = re.compile(
            r'\b(?:https?://|www\.)[^\s<]+',
            re.IGNORECASE
        )

        def _replace(match):
            raw = match.group(0)
            href = raw if raw.lower().startswith(("http://", "https://")) else f"http://{raw}"
            # Add additional attributes; here we set target="_blank"
            return f'<a href="{href}" target="_blank">{raw}</a>'

        return url_regex.sub(_replace, text)
    except Exception:
        # In case of any error, return the original text unchanged
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    if not isinstance(url, str):
        return None
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ("http", "https"):
        return None
    req = Request(url, method="HEAD")
    try:
        with urlopen(req) as resp:
            if hasattr(resp, "status") and resp.status != 200:
                return None
            return resp.info().get("Content-Type")
    except Exception:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    Return the content-type header value if successful, otherwise None.
    """
    try:
        parsed = urlparse(url)
        if parsed.scheme not in ("http", "https"):
            return None
        req = urllib.request.Request(url, method="HEAD")
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return None
            return resp.headers.get("Content-Type")
    except Exception:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status >= 400:
                return None
            return resp.getheader('Content-Type')
    except Exception:
        return None

