def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    result: Dict[str, str] = {}

    # First attempt JSON parsing
    try:
        import json

        data = json.loads(document)
        # Extract links
        links = data.get("links", []) or []
        link_map: Dict[str, str] = {}
        for l in links:
            rel = l.get("rel", "") or ""
            href = l.get("href")
            if href:
                link_map[rel] = href
        # HCard
        for key in ("hcard", "http://webfinger.net/rel/hcard", "rel:hcard"):
            if key in link_map:
                result["hcard_url"] = link_map[key]
                break
        # LRDD
        if "lrdd" in link_map:
            result["lrdd"] = link_map["lrdd"]
        # Store additional useful fields
        if "subject" in data:
            result["subject"] = data["subject"]
        if "aliases" in data:
            result["aliases"] = data["aliases"]
        return result
    except Exception:
        # If JSON parsing fails, try XRD (XML) parsing
        try:
            import xml.etree.ElementTree as ET

            root = ET.fromstring(document)
        except Exception:
            return {}
        # Find all Link elements
        link_map: Dict[str, str] = {}
        for link in root.findall(".//{*}Link"):
            rel = link.get("rel") or ""
            href = link.get("href")
            if href:
                link_map[rel] = href
        # HCard
        for key in ("hcard", "http://webfinger.net/rel/hcard", "rel:hcard"):
            if key in link_map:
                result["hcard_url"] = link_map[key]
                break
        # LRDD
        if "lrdd" in link_map:
            result["lrdd"] = link_map["lrdd"]
        # Subject and Alias may be present
        subject_elem = root.find(".//{*}Subject")
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text
        alias_elems = root.findall(".//{*}Alias")
        if alias_elems:
            result["aliases"] = [elem.text for elem in alias_elems if elem.text]
        return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    try:
        # Try JSON first
        data = json.loads(document)
        # Ensure key hcard_url if missing but present in links
        if isinstance(data, dict):
            if "hcard_url" not in data:
                links = data.get("links", [])
                for link in links:
                    if isinstance(link, dict) and link.get("rel"):
                        rel = link["rel"]
                        if "hcard" in rel.lower():
                            data["hcard_url"] = link.get("href") or link.get("template")
                            break
            return data
    except Exception:
        # Fall back to XRD parsing
        try:
            # Parse XML
            root = xml.etree.ElementTree.fromstring(document)
        except Exception:
            return None
        # Namespace handling (optional)
        ns = {}
        if root.tag.startswith("{"):
            uri = root.tag.split("}")[0][1:]
            ns = {"ns": uri}
            find = lambda tag: root.find(f"ns:{tag}", ns)
            findall = lambda tag: root.findall(f"ns:{tag}", ns)
        else:
            find = lambda tag: root.find(tag)
            findall = lambda tag: root.findall(tag)
        result: Dict = {}
        subject = find("subject")
        if subject is not None and subject.text:
            result["subject"] = subject.text
        aliases = [a.text for a in findall("Alias") if a.text]
        if aliases:
            result["aliases"] = aliases
        links = []
        for link_elem in findall("Link"):
            rel = link_elem.attrib.get("rel")
            href = link_elem.attrib.get("href")
            template = link_elem.attrib.get("template")
            link_dict = {"rel": rel}
            if href:
                link_dict["href"] = href
            if template:
                link_dict["template"] = template
            links.append(link_dict)
        if links:
            result["links"] = links
        # Extract hcard_url if present
        hcard_url = None
        for ln in links:
            if ln.get("rel") and "hcard" in ln["rel"].lower():
                hcard_url = ln.get("href") or ln.get("template")
                break
        if hcard_url:
            result["hcard_url"] = hcard_url
        return result if result else None
    return None

