                    link_data[attr] = val
            if link_data:
                links.append(link_data)
        if links:
            result["links"] = links

        return result if result else None
    except Exception:
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None

    # Try JSON first
    stripped = document.lstrip()
    if stripped.startswith('{') or stripped.startswith('['):
        try:
            data = json.loads(stripped)
        except Exception:
            return None
        # Normalise to expected keys
        result: Dict = {}
        for key in ("subject", "properties", "links"):
            if key in data:
                result[key] = data[key]
        return result

    # Otherwise assume XRD
    try:
        root = ET.fromstring(stripped)
    except Exception:
        return None

    # Helper to strip XML namespaces
    def _strip_namespace(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    # Extract subject
    subject_elem = root.find(lambda x: _strip_namespace(x) == "Subject")
    subject = subject_elem.text.strip() if subject_elem is not None else None

    # Extract properties
    properties: Dict = {}
    for prop in root.findall(lambda x: _strip_namespace(x) == "Property"):
        key = prop.attrib.get("type") or prop.attrib.get("rel") or _strip_namespace(prop.tag)
        value = prop.text.strip() if prop.text else ""
        properties[key] = value

    # Extract links
    links: list = []
    for link in root.findall(lambda x: _strip_namespace(x) == "Link"):
        rel = link.attrib.get("rel")
        href = link.attrib.get("href")
        if rel and href:
            links.append({"rel": rel, "href": href})

    result: Dict = {}
    if subject:
        result["subject"] = subject
    if properties:
        result["properties"] = properties
    if links:
        result["links"] = links
    return result if result else None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON parsing first
    try:
        import json
        data = json.loads(document)
        result: Dict[str, Any] = {}
        result["subject"] = data.get("subject", "")
        result["aliases"] = data.get("aliases", [])
        # Extract hcard URL if present
        hcard_url = None
        for link in data.get("links", []):
            href = link.get("href")
            if href and ("hcard" in href or ".well-known/hcard" in href):
                hcard_url = href
                break
        if hcard_url:
            result["hcard_url"] = hcard_url
        return result
    except Exception:
        pass

    # Fallback to XRD parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        result: Dict[str, Any] = {}
        subject = root.find("xrd:Subject", ns)
        if subject is not None:
            result["subject"] = subject.text or ""
        aliases = []
        for alias in root.findall("xrd:Alias", ns):
            if alias.text:
                aliases.append(alias.text)
        if aliases:
            result["aliases"] = aliases
        # Look for hcard link
        hcard_url = None
        for link in root.findall("xrd:Link", ns):
            href = link.attrib.get("href")
            if href and ("hcard" in href or ".well-known/hcard" in href):
                hcard_url = href
                break
        if hcard_url:
            result["hcard_url"] = hcard_url
        return result
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        _, host = handle.split("@", 1)
    except ValueError:
        # handle does not contain a host part
        return None
    # Build the request URL for the webfinger endpoint
    try:
        import urllib.request
        import urllib.error
        url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
        try:
            with urllib.request.urlopen(url, timeout=5) as resp:
                return resp.read().decode("utf-8")
        except urllib.error.URLError:
            # Fallback to http if https fails
            url = f"http://{host}/.well-known/webfinger?resource=acct:{handle}"
            try:
                with urllib.request.urlopen(url, timeout=5) as resp:
                    return resp.read().decode("utf-8")
            except Exception:
                return None
    except Exception:
        return None
    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Normalize handle by stripping the "acct:" scheme if present
        handle_clean = handle
        if handle_clean.lower().startswith("acct:"):
            handle_clean = handle_clean[5:]
        if "@" not in handle_clean:
            return None
        _, domain = handle_clean.rsplit("@", 1)

        # Manual percent‑encoding (RFC 3986)
        def percent_encode(s: str) -> str:
            return ''.join(
                c if c.isalnum() or c in "-._~" else f"%{ord(c):02X}"
                for c in s
            )

        resource = f"acct:{handle_clean}"
        url = f"https://{domain}/.well-known/webfinger?resource={percent_encode(resource)}"

        with urllib.request.urlopen(url) as resp:
            try:
                charset = resp.headers.get_content_charset("utf-8")
                return resp.read().decode(charset, errors="replace")
            except (AttributeError, LookupError):
                return resp.read().decode("utf-8", errors="replace")
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except Exception:
        return None
    url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
    try:
        with closing(urllib2.urlopen(url)) as page:
            if page.getcode() != 200:
                return None
            data = page.read()
            if isinstance(data, bytes):
                data = data.decode("utf-8", errors="replace")
            return data
    except Exception:
        return None

