def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Prepare headers, adding a default User-Agent.
    headers = {'User-Agent': USER_AGENT}
    if 'headers' in kwargs:
        headers.update(kwargs.pop('headers'))
    kwargs.update({'headers': headers, 'timeout': timeout})

    # Choose the correct requests function based on the method.
    method_upper = method.upper()
    if method_upper == "POST":
        request_func = requests.post
    else:
        # For other methods, use requests.request
        request_func = requests.request

    try:
        if method_upper == "POST":
            response = request_func(url, data=data, *args, **kwargs)
        else:
            # Pass the method as the first argument to requests.request.
            response = request_func(method_upper, url, data=data, *args, **kwargs)
        return response.status_code, None
    except requests.exceptions.RequestException as ex:
        return None, ex

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Basic type checks
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dict")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    if any(not isinstance(k, str) for k in keys):
        raise TypeError("all keys must be strings")

    # No subkeys – insert at the top level
    if not keys:
        dic[key] = val
        return

    # Ensure the first key points to a dict
    if key not in dic or not isinstance(dic[key], dict):
        dic[key] = {}
    current = dic[key]

    # Iterate over intermediate subkeys (all but the last)
    for subkey in keys[:-1]:
        if subkey not in current or not isinstance(current[subkey], dict):
            current[subkey] = {}
        current = current[subkey]

    # Set the value for the last key
    current[keys[-1]] = val

def list_of_file_names(settings_dirs, spec_option):
