def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Returns a sorted list of fully-qualified file paths found in the
    specified directories.  The ``spec_option`` argument controls which
    files are selected:

    *  If ``spec_option`` is ``'ini'`` or ``'INICONFIG'`` (case‑insensitive),
       only files ending with ``.ini`` are returned.
    *  If ``spec_option`` is ``'all'`` (case‑insensitive), all files are
       returned.
    *  If ``spec_option`` is a sequence of extensions (e.g. ``['.json',
       '.yaml']``), only files matching any of those extensions are
       returned.
    *  Any other value raises a :class:`ValueError`.

    Parameters
    ----------
    settings_dirs : str | Path | Iterable[str | Path]
        One or more directory paths to search.

    spec_option : str | Iterable[str]
        Extension filter as described above.

    Returns
    -------
    list[str]
        Sorted list of absolute file paths that match the criteria.

    Notes
    -----
    * The function silently skips directories that do not exist or are
      not readable.
    * Relative paths are converted to absolute paths based on the current
      working directory.
    * Duplicate paths are removed.
    """
    import os
    from pathlib import Path

    # Normalise settings_dirs to a list of Path objects
    if isinstance(settings_dirs, (str, Path)):
        dirs = [Path(settings_dirs)]
    else:
        dirs = [Path(d) for d in settings_dirs]

    # Normalise spec_option to a list of lower‑case extensions
    def _parse_spec(opt):
        if isinstance(opt, str):
            if opt.lower() in ("ini", "input"):
                return {".ini"}
            if opt.lower() == "all":
                return None
            # Treat arbitrary string as one extension
            return {opt.lower() if opt.lower().startswith(".") else f".{opt.lower()}"}
        if isinstance(opt, (list, set, tuple)):
            exts = set()
            for e in opt:
                if not isinstance(e, str):
                    raise ValueError(f"Extension must be string, got {e!r}")
                exts.add(e.lower() if e.lower().startswith(".") else f".{e.lower()}")
            return exts
        raise ValueError(f"Invalid spec_option type: {type(opt).__name__}")

    try:
        extensions = _parse_spec(spec_option)
    except Exception as exc:
        raise ValueError(f"Invalid spec_option {spec_option!r}: {exc}") from exc

    files = set()
    for d in dirs:
        try:
            if not d.is_dir():
                continue
            for entry in d.iterdir():
                if entry.is_file():
                    if extensions is None or entry.suffix.lower() in extensions:
                        files.add(str(entry.resolve()))
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue

    return sorted(files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""

    try:
        # Ensure settings_dirs is a list of directories
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        elif isinstance(settings_dirs, (list, tuple, set)):
            dirs = list(settings_dirs)
        else:
            # Unsupported type, return empty list
            return []

        matching_files = []

        for directory in dirs:
            if not isinstance(directory, str):
                # Skip non-string items
                continue
            try:
                # Walk through the directory tree
                for root, _, files in os.walk(directory):
                    for file_name in files:
                        # Match the file name against spec_option pattern
                        if fnmatch.fnmatch(file_name, spec_option):
                            full_path = os.path.join(root, file_name)
                            matching_files.append(full_path)
            except (OSError, PermissionError):
                # Skip directories that cannot be accessed
                continue

        # Return a sorted list of unique absolute file paths
        return sorted(set(matching_files))
    except Exception:
        # In case anything unexpected happens, return an empty list
        return []

