def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files.

        The method looks for an ``include`` key in the supplied
        ``parser_dict``.  The value can be a dictionary mapping group
        names to either another dictionary (inline include) or a file
        path pointing to a JSON/YAML file that contains a dictionary.
        Each included mapping is merged into the original ``parser_dict``
        (recursively, so nested ``include``s are also respected).  After
        processing the ``include`` key is removed. Errors encountered
        while loading a file are caught and logged via a ``logger``
        attribute if present, but do not interrupt the merge of other
        entries.
        """
        includes = parser_dict.get('include')
        if not includes:
            return parser_dict
        if not isinstance(includes, dict):
            raise TypeError("The 'include' directive must be a dictionary.")
        # Recursive merge helper
        def deep_merge(src, dst):
            for k, v in src.items():
                if k in dst and isinstance(dst[k], dict) and isinstance(v, dict):
                    deep_merge(v, dst[k])
                else:
                    dst[k] = v
        for key, inc in includes.items():
            # Resolve include value
            if isinstance(inc, str):
                # Treat as path to a JSON file
                try:
                    import json, pathlib
                    path = pathlib.Path(inc)
                    with path.open('rt', encoding='utf-8') as f:
                        inc_map = json.load(f)
                    if not isinstance(inc_map, dict):
                        raise ValueError(f"Included file {inc} does not contain a dictionary at the top level.")
                except Exception as exc:
                    if hasattr(self, 'logger'):
                        self.logger.warning(f"Failed to load include file '{inc}': {exc}")
                    continue
            elif isinstance(inc, dict):
                inc_map = inc
            else:
                # Unsupported include format; skip
                continue
            # Merge into destination
            if key in parser_dict and isinstance(parser_dict[key], dict):
                deep_merge(inc_map, parser_dict[key])
            else:
                parser_dict[key] = inc_map
        # Remove the include key after processing
        parser_dict.pop('include', None)
        return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files.

        The ``parser_dict`` may contain an ``include`` key whose value can be
        either a ``dict`` or a file path (JSON/YAML).  The method loads the
        included data, merges it into ``parser_dict`` and handles nested
        ``include`` directives recursively.  It returns the updated dictionary.

        Parameters
        ----------
        parser_dict : dict
            The dictionary to process.

        Returns
        -------
        dict
            The updated dictionary with all ``include`` directives resolved.

        Raises
        ------
        FileNotFoundError
            If a file path is specified but does not exist.
        TypeError
            If the ``include`` value is of an unexpected type.
        ValueError
            If the included file has an unsupported format.
        """
        include_key = "include"
        if include_key not in parser_dict:
            return parser_dict

        include_value = parser_dict.pop(include_key)
        if isinstance(include_value, dict):
            source_data = include_value
        elif isinstance(include_value, str):
            import json
            import os

            file_path = include_value
            if not os.path.isfile(file_path):
                raise FileNotFoundError(f"Include file not found: {file_path}")

            _, ext = os.path.splitext(file_path)
            ext = ext.lower()
            with open(file_path, "r", encoding="utf-8") as fp:
                if ext == ".json":
                    source_data = json.load(fp)
                elif ext in {".yaml", ".yml"}:
                    try:
                        import yaml
                    except Exception as e:
                        raise RuntimeError(
                            "YAML loading requested but PyYAML is not installed"
                        ) from e
                    source_data = yaml.safe_load(fp)
                else:
                    raise ValueError(f"Unsupported include file format: {ext}")

            if source_data is None:
                raise TypeError(f"Include file '{file_path}' is empty")
            if not isinstance(source_data, dict):
                raise TypeError(
                    f"Include file '{file_path}' must contain a top‑level dict"
                )
        else:
            raise TypeError(
                f"Unsupported include value type: {type(include_value)!r}"
            )

        # Merge the source data into the current dictionary.
        def merge_dict(dest, src):
            for key, val in src.items():
                if key in dest and isinstance(dest[key], dict) and isinstance(val, dict):
                    # Recursively merge nested dictionaries.
                    merge_dict(dest[key], val)
                else:
                    dest[key] = val

        merge_dict(parser_dict, source_data)

        # After merging, handle any nested ``include`` directives in the result.
        if isinstance(parser_dict, dict):
            # Search nested dictionaries for ``include`` keys.
            for k, v in list(parser_dict.items()):
                if isinstance(v, dict):
                    parser_dict[k] = self._include_groups(v)

        return parser_dict

def _include_groups(self, parser_dict):
    """
    Resolve the include directive in spec files.
    The directive is expected to be a dictionary entry with the key
    ``__include__`` whose value is either:
      * a path to a JSON file containing a dictionary to merge
      * a dictionary that should be merged directly into the current
        config.

    The method recursively processes nested include directives and
    protects against circular references by tracking the files that
    have already been processed.  In case of any failure a
    ``RuntimeError`` is raised with a helpful message.
    """
    import json
    import os

    # Map of absolute file paths that have already been processed.
    _processed_files = set()

    def _merge_dicts(base, new, path_stack):
        """
        Deeply merge ``new`` into ``base``.  New values overwrite old
        values when the same key is present.  Keys that are dictionaries
        are merged recursively.  Circular references are detected via
        ``path_stack``.
        """
        for key, val in new.items():
            if key in base and isinstance(base[key], dict) and isinstance(val, dict):
                base[key] = _merge_dicts(base[key], val, path_stack)
            else:
                base[key] = val
        return base

    def _process_node(node_repr, current_path, path_stack):
        """
        Process a node that may contain an include directive.
        ``node_repr`` is expected to be a dictionary.
        """
        if not isinstance(node_repr, dict):
            # Nothing to include; return as-is.
            return node_repr

        # Detect a direct include dict.
        if "__include__" in node_repr:
            include = node_repr["__include__"]
            if isinstance(include, dict):
                # Merge the provided dictionary.
                resolved = {}
                for sub_k, sub_v in include.items():
                    resolved[sub_k] = _process_node(sub_v, current_path, path_stack)
                # Merge into current node (excluding the include key).
                node_to_merge = dict(node_repr)
                node_to_merge.pop("__include__")
                return _merge_dicts(resolved, node_to_merge, path_stack)
            elif isinstance(include, str):
                # Treat the string as a file path.
                inc_path = os.path.abspath(
                    include if os.path.isabs(include)
                    else os.path.join(os.path.dirname(current_path), include)
                )
                if inc_path in _processed_files:
                    raise RuntimeError(f"Circular include detected: {inc_path}")
                if not os.path.isfile(inc_path):
                    raise FileNotFoundError(f"Included file not found: {inc_path}")
                try:
                    with open(inc_path, "r") as f:
                        inc_content = json.load(f)
                except Exception as exc:
                    raise RuntimeError(f"Failed to load include file {inc_path}") from exc
                _processed_files.add(inc_path)
                node_to_merge = dict(node_repr)
                node_to_merge.pop("__include__")
                merged = _merge_dicts(
                    _process_node(inc_content, inc_path, path_stack + (inc_path,)),
                    node_to_merge,
                    path_stack + (inc_path,),
                )
                _processed_files.discard(inc_path)
                return merged
            else:
                # Unsupported include form.
                raise RuntimeError(
                    f"Unsupported include type {type(include)!r} in {node_repr!r}"
                )

        # No include directive; recurse into dict values.
        processed = {}
        for key, val in node_repr.items():
            processed[key] = _process_node(val, current_path, path_stack)
        return processed

    # Start processing from the root dictionary.
    try:
        return _process_node(parser_dict, os.getcwd(), tuple())
    except Exception as exc:
        raise RuntimeError("Failed to resolve includes in parser dict") from exc

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')
        # Attempt to get a value from the spec, falling back to the option's default
        spec_val = None
        if hasattr(self, "spec"):
            try:
                spec_val = self.spec.get(arg.name, NoDefault())
            except Exception:
                spec_val = NoDefault()
        # If the spec did not provide a value, use the option's default
        if isinstance(spec_val, NoDefault):
            if isinstance(arg.default, NoDefault):
                # No default at all, skip this option
                continue
            val = arg.default
        else:
            val = spec_val
        if isinstance(arg, DictOption):
            # For dict options, build nested defaults and merge any spec overrides
            nested_defaults = {}
            if hasattr(arg.scheme, "get_spec_defaults"):
                try:
                    nested_defaults = arg.scheme.get_spec_defaults()
                except Exception:
                    nested_defaults = {}
            if isinstance(val, dict):
                nested_defaults.update(val)
            defaults[arg.name] = nested_defaults
        else:
            defaults[arg.name] = val
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # helper to merge dictionary-like objects safely
    def merge(dict_obj):
        try:
            if dict_obj is None:
                return
            if isinstance(dict_obj, dict):
                defaults.update(dict_obj)
            elif hasattr(dict_obj, "to_dict") and callable(dict_obj.to_dict):
                defaults.update(dict_obj.to_dict())
            elif hasattr(dict_obj, "__dict__"):
                # exclude private attributes
                defaults.update({k: v for k, v in dict_obj.__dict__.items() if not k.startswith("_")})
        except Exception:
            # ignore objects that cannot be merged
            pass

    # collect defaults from the spec and the default_spec
    merge(getattr(self, "spec", None))
    merge(getattr(self, "_default_spec", None))

    # collect defaults from individual arguments
    args = getattr(self, "args", [])
    for arg in args:
        try:
            # Many argument objects expose a 'name' and a 'default' attribute
            name = getattr(arg, "name", None)
            default = getattr(arg, "default", None)
            # Skip if default is missing or a sentinel value
            if name is not None and default is not None and default is not getattr(arg, "_NO_DEFAULT", None):
                defaults[name] = default
        except Exception:
            # Skip arguments that do not provide expected attributes
            continue

    return defaults

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources."""
        defaults = {}
        # Retrieve defaults from spec if available
        spec = getattr(self, "spec", {})
        if isinstance(spec, dict):
            spec_defaults = spec
        else:
            try:
                spec_defaults = dict(spec)
            except Exception:
                spec_defaults = {}
        # Iterate over arguments to determine their defaults
        for arg in getattr(self, "args", []):
            if not hasattr(arg, "name"):
                continue
            name = arg.name
            # Use value from spec if present
            if name in spec_defaults:
                defaults[name] = spec_defaults[name]
                continue
            # Fallback to argument's own default if defined
            if hasattr(arg, "default") and not isinstance(arg.default, NoDefault):
                defaults[name] = arg.default
                continue
            # Optional: environment variable fallback (case‑insensitive)
            try:
                env_val = os.getenv(name.upper())
                if env_val is not None:
                    defaults[name] = env_val
            except Exception:
                # Ignore errors retrieving environment variable
                pass
        return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Start with defaults set by the class-level default spec if present
    try:
        if hasattr(self, "_default_spec"):
            d = getattr(self._default_spec, "get", lambda: {})()
            if isinstance(d, dict):
                defaults.update(d)
    except Exception:
        pass

    # Override or extend with values from the instance spec if available
    try:
        if hasattr(self, "spec"):
            d = getattr(self.spec, "get", lambda: {})()
            if isinstance(d, dict):
                defaults.update(d)
    except Exception:
        pass

    # Finally, fill in defaults that were defined on the options themselves
    for opt in getattr(self, "args", []):
        try:
            # Skip if already set by spec/default_spec
            name = getattr(opt, "name", None) or getattr(opt, "option_name", None)
            if not name:
                continue
            if name in defaults:
                continue
            default_val = getattr(opt, "default", None)
            if default_val is not None and not isinstance(default_val, getattr(opt, "NoDefault", type(None))):
                defaults[name] = default_val
        except Exception:
            # If an option does not have the expected attributes, ignore it
            continue

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Iterate over all arguments defined in the scheme
    for arg in getattr(self, "args", []):
        # Ensure the argument is a valid option type
        if not hasattr(arg, "name"):
            continue
        # Attempt to get the value from the spec; fall back to the option's default
        value = None
        if getattr(self, "spec", None) is not None:
            try:
                # Many spec-like objects implement a ``get`` method; fall back to
                # attribute access if ``get`` is not available.
                if hasattr(self.spec, "get"):
                    value = self.spec.get(arg.name)
                else:
                    value = getattr(self.spec, arg.name, None)
            except Exception:
                value = None
        # If the spec does not provide a value, fall back to the default on the option
        if value is None:
            if not isinstance(arg.default, NoDefault):
                value = arg.default
        # Store the resolved value
        if value is not None:
            defaults[arg.name] = value
    return defaults

