def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import warnings
    deprecated_map = getattr(self, 'deprecated_args', {})
    for old_arg, new_arg in deprecated_map.items():
        if old_arg in cli_args:
            warnings.warn(
                f"Keyword argument '{old_arg}' is deprecated. Use '{new_arg}'.",
                DeprecationWarning,
                stacklevel=2,
            )
        elif old_arg in answer_file_args:
            warnings.warn(
                f"Argument '{old_arg}' is deprecated in answer file. Use '{new_arg}'.",
                DeprecationWarning,
                stacklevel=2,
            )

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Normalise inputs
    if cli_args is None:
        cli_args = {}
    if answer_file_args is None:
        answer_file_args = {}
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Deprecation mapping expected on the instance: {'old_name': 'new_name', ...}
    deprecation_map = getattr(self, "deprecated_args", None)
    if deprecation_map is None:
        # No deprecation info available; nothing to do
        return
    if not isinstance(deprecation_map, dict):
        raise AttributeError(
            f"deprecated_args attribute must be a dict, got {type(deprecation_map).__name__}"
        )

    # Merge the arguments to search for deprecated keys
    merged_args = {**answer_file_args, **cli_args}

    for old_name, new_name in deprecation_map.items():
        if old_name in merged_args:
            try:
                # Use warnings to emit a deprecation notice
                warnings.warn(
                    f"Argument '{old_name}' is deprecated. "
                    f"Use '{new_name}' instead.",
                    DeprecationWarning,
                    stacklevel=3,
                )
            except Exception:
                # If warnings module is not available or any other error occurs,
                # fall back to printing to stderr.
                import sys
                sys.stderr.write(
                    f"WARNING: Argument '{old_name}' is deprecated. "
                    f"Use '{new_name}' instead.\n"
                )

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure we have dictionaries to work with
    cli = cli_args or {}
    files = answer_file_args or {}

    # Determine deprecation mapping if the instance defines it
    deprecation_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecation_map, dict):
        deprecation_map = {}

    # Combine arguments, giving precedence to CLI values
    all_args = {}
    all_args.update(files)
    all_args.update(cli)

    # Import warnings only when needed
    import warnings
    warnings.simplefilter("always", DeprecationWarning)

    for arg in all_args:
        if arg in deprecation_map:
            new_arg = deprecation_map[arg]
            warnings.warn(
                f"Argument '{arg}' is deprecated; "
                f"use '{new_arg}' instead.",
                DeprecationWarning,
                stacklevel=3,
            )

    # Reset warnings filter to default
    warnings.simplefilter("default", DeprecationWarning)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Try to retrieve the parser for the requested command.
    try:
        parser = self.commands[command_name]
    except (KeyError, AttributeError):
        # If the command does not exist or the object does not provide
        # a parser, return an empty list rather than raising an exception.
        return []

    # Build a list of option specifications.
    options = []
    try:
        for action in parser._actions:
            # Skip actions that do not correspond to command-line flags
            if not getattr(action, 'option_strings', []):
                continue
            for flag in action.option_strings:
                spec = {
                    'flag': flag,
                    'help': getattr(action, 'help', None),
                    'type': getattr(action, 'type', None),
                    'dest': getattr(action, 'dest', None),
                }
                options.append(spec)
    except AttributeError:
        # The parser object does not have an _actions iterable.
        # Return an empty list in this case.
        return []

    return options

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    # Try to fetch the options mapping from the instance attributes.
    try:
        # Preferred attribute name
        option_specs = self._parser_option_specs
    except AttributeError:
        # Fallback to another possible attribute
        option_specs = getattr(self, "options_map", {})
    if not isinstance(option_specs, dict):
        # If attribute exists but isn't a dictionary, fall back to empty dict
        option_specs = {}
    # Retrieve options for the requested command; return empty list if not found.
    options = option_specs.get(command_name, [])
    # Ensure the result is a list
    if isinstance(options, list):
        return options
    try:
        return list(options)
    except TypeError:
        # If options is not iterable, return empty list to avoid crashes.
        return []

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name.strip():
        raise ValueError("command_name must be a non-empty string")

    # Determine where the option specifications are stored
    specs_dict = (
        getattr(self, "_parser_option_specs", None)
        or getattr(self, "_command_option_specs", None)
        or getattr(self, "parser_option_specs", None)
    )

    if not isinstance(specs_dict, dict):
        raise AttributeError(
            "Expected a dict attribute named '_parser_option_specs', "
            "'_command_option_specs', or 'parser_option_specs' containing "
            "command option specifications."
        )

    # Retrieve the options for the given command
    try:
        options = specs_dict[command_name]
    except KeyError as exc:
        raise KeyError(
            f"Command '{command_name}' not found in parser options."
        ) from exc

    if not isinstance(options, list):
        raise TypeError(
            f"Options for command '{command_name}' should be a list, "
            f"got {type(options).__name__}"
        )

    # Return a shallow copy to prevent accidental modifications
    return list(options)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Retrieve the dictionary that holds all command specifications
    try:
        command_specs = getattr(self, "_option_spec", None)
    except Exception as exc:
        raise AttributeError("Instance is missing the `_option_spec` attribute") from exc

    if command_specs is None:
        raise AttributeError("Instance has no `_option_spec` attribute")

    # Get the spec for the particular command
    try:
        cmd_spec = command_specs.get(command_name)
    except AttributeError as exc:
        raise AttributeError("_option_spec should be a mapping") from exc

    if cmd_spec is None:
        raise ValueError(f"Command '{command_name}' not registered in option specs")

    # Get the option specification within that command
    try:
        option_spec = cmd_spec.get(argument_name)
    except AttributeError as exc:
        raise AttributeError("Command spec should be a mapping") from exc

    if option_spec is None:
        raise ValueError(f"Option '{argument_name}' not found for command '{command_name}'")

    return option_spec

def get_option_spec(self, command_name, argument_name):
