def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Convert input to a dictionary representation
    try:
        # Namespace or any object exposing __dict__
        arg_dict = vars(args)
    except TypeError:
        # Assume args is already a dict
        arg_dict = args

    if not isinstance(arg_dict, dict):
        # Unsupported type
        return []

    silent = []
    for key, value in arg_dict.items():
        # Silenced if the value is None, empty string, boolean False,
        # or an empty collection (list/tuple/set/dict).
        if value is None:
            silent.append(key)
        elif isinstance(value, str) and value.strip() == '':
            silent.append(key)
        elif isinstance(value, bool) and not value:
            silent.append(key)
        elif isinstance(value, (list, tuple, set, dict)) and not value:
            silent.append(key)

    return silent

def get_silent_args(self, args):
        """
        list of silenced argument

        :param args: The received arguments.
        :return: list, silenced argument names
        """
        # Default silently return an empty list for invalid input
        if args is None:
            return []

        # If args is a dictionary, assume the value indicates whether the flag is active
        if isinstance(args, dict):
            try:
                return [key for key, value in args.items() if not value]
            except Exception:
                return []

        # If args is an iterable (list/tuple) of strings
        if isinstance(args, (list, tuple)):
            silent_flags = {"-q", "--quiet", "-s", "--silent"}
            try:
                return [arg for arg in args if arg in silent_flags]
            except Exception:
                return []

        # Fallback: try converting to list
        try:
            return [arg for arg in list(args) if isinstance(arg, str) and arg in {"-q", "--quiet", "-s", "--silent"}]
        except Exception:
            return []

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent_names = []
    if args is None:
        return silent_names
    try:
        for arg in args:
            if isinstance(arg, str) and arg.startswith('-'):
                # Strip all leading '-' characters to get the argument name
                silent_names.append(arg.lstrip('-'))
    except Exception:
        # If args is not iterable or some unexpected error occurs, return an empty list
        return []
    return silent_names

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping so we can check for keys
    if not isinstance(args, dict):
        raise TypeError(f"'args' must be a dict, got {type(args).__name__}")

    # Retrieve the list of required argument names; if not set, assume none
    required = getattr(self, 'required', [])
    if not isinstance(required, (list, tuple, set)):
        raise TypeError(f"'required' must be a list, tuple, or set, got {type(required).__name__}")

    # Iterate through each required argument and verify presence and non‑None value
    missing = []
    for name in required:
        # Support nested keys using dot notation if desired
        if '.' in name:
            parts = name.split('.')
            value = args
            for part in parts:
                if isinstance(value, dict) and part in value:
                    value = value[part]
                else:
                    value = None
                    break
        else:
            value = args.get(name)
        if value is None:
            missing.append(name)

    if missing:
        missing_str = ', '.join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required keys – default to an empty list if not set.
    required_keys = getattr(self, 'required', [])
    if not isinstance(required_keys, (list, set, tuple)):
        raise TypeError("`self.required` must be a list, set, or tuple of argument names")

    # Ensure `args` is a mapping (dict-like). If it is a different type,
    # try to convert or raise an informative error.
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception as exc:
            raise TypeError("`args` must be a mapping of argument names to values") from exc

    missing = []
    for key in required_keys:
        val = args.get(key, None)
        if val is None or (isinstance(val, str) and not val.strip()):
            missing.append(key)

    if missing:
        # Raise a single exception listing all missing required arguments.
        missing_str = ", ".join(missing)
        raise InvalidArgumentError(f"Missing required argument(s): {missing_str}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required arguments. Expect self.required_args as an iterable.
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("no 'required_args' attribute found on instance")
    # Normalize args to a mapping. Accept dictionaries or objects with attribute access.
    try:
        if isinstance(args, dict):
            mapping = args
        else:
            mapping = vars(args)
    except Exception as exc:
        raise TypeError(f"Unsupported type for args: {type(args).__name__}") from exc
    missing = []
    for key in required:
        # Missing key or value is None is considered unmet
        if key not in mapping or mapping[key] is None:
            missing.append(key)
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if not isinstance(args, dict):
        raise TypeError('args must be a dictionary of argument names to values')
    required = getattr(self, 'required_args', [])
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError('Missing required argument(s): {}'.format(', '.join(missing)))
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of option definitions")
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument values")

    required_args = []

    for opt in options_spec:
        # skip entries that are not mappings
        if not isinstance(opt, dict):
            continue

        cond = opt.get('required_when')
        if cond is None:
            continue

        matched = False
        try:
            if callable(cond):
                matched = bool(cond(command_name, args))
            else:
                # treat as a string expression; expose 'args' and 'command_name' to eval
                matched = bool(eval(cond, {}, {'args': args, 'command_name': command_name}))
        except Exception:
            # If evaluation fails, treat as not matched
            matched = False

        if matched:
            # Prefer the 'arg' key (destination name) or fall back to 'name'
            arg_name = opt.get('arg') or opt.get('name')
            if arg_name is not None:
                required_args.append(arg_name)

    return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_args = []
    # Helper to safely get a value from args (dict or namespace)
    def _get_from_args(key):
        if isinstance(args, dict):
            return args.get(key)
        return getattr(args, key, None)

    for opt in options_spec:
        if not isinstance(opt, dict):
            continue
        cond = opt.get('required_when')
        if cond is None:
            continue

        matched = False
        try:
            if callable(cond):
                # try passing command_name and args
                try:
                    matched = bool(cond(command_name=command_name, args=args))
                except TypeError:
                    matched = bool(cond(command_name, args))
            elif isinstance(cond, (list, tuple)):
                # any truthy value for keys in args
                matched = any(bool(_get_from_args(k)) for k in cond if isinstance(k, str))
            elif isinstance(cond, str):
                matched = bool(_get_from_args(cond))
            else:
                matched = bool(cond)
        except Exception:
            matched = False

        if matched:
            name = opt.get('name') or opt.get('arg')
            if name is not None:
                required_args.append(name)
    return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required = []
        for opt in options_spec or ():
            # determine the argument name/key to return
            name = opt.get('arg') or opt.get('name') or opt.get('option')
            if not name:
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            matched = False
            if callable(cond):
                # Try to call with args and command_name if possible
                try:
                    matched = cond(args, command_name)
                except TypeError:
                    try:
                        matched = cond(args)
                    except Exception:
                        matched = False
            elif isinstance(cond, dict):
                # required when all key/value pairs in cond match the current args
                matched = all(args.get(k) == v for k, v in cond.items())
            elif isinstance(cond, (list, tuple, set)):
                # required when any key in the iterable is present and truthy in args
                matched = any(args.get(k) for k in cond)
            else:
                # assume cond is a key name; required when that key in args is truthy
                matched = bool(args.get(cond))
            if matched:
                required.append(name)
        return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        name = opt.get('name')
        cond = opt.get('required_when')
        if not name or not cond:
            continue
        try:
            if callable(cond):
                try:
                    cond_met = cond(command_name, args)
                except TypeError:
                    cond_met = cond(args)
            else:
