    return required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values")

    for name, val in args.items():
        # Determine the value and the maximum allowed length
        value = val
        max_len = None

        # If the argument value is given as a (value, max_length) tuple/list,
        # unpack it.  Otherwise look for a predefined max length that may
        # be stored on the instance either as a dedicated attribute or in
        # a mapping.
        if isinstance(val, (tuple, list)) and len(val) == 2:
            value, max_len = val
        else:
            # Check for an attribute such as `_max_len_<arg_name>`
            attr_name = f"_max_len_{name}"
            if hasattr(self, attr_name):
                max_len = getattr(self, attr_name)
            # Fall back to a generic dictionary if it exists
            elif hasattr(self, "_max_lengths") and isinstance(self._max_lengths, dict):
                max_len = self._max_lengths.get(name)

        # Skip arguments that have no length constraint
        if max_len is None:
            continue

        # Ensure the value actually supports length
        if not hasattr(value, "__len__"):
            raise TypeError(f"Argument '{name}' does not support length comparison")

        # Check the actual length against the maximum
        if len(value) > max_len:
            raise ValueError(
                f"Argument '{name}' length ({len(value)}) exceeds the maximum of {max_len}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument definitions from the parsed YAML
    argdefs = self.parsed_yaml.get('args', {})

    def _get_spec(name):
        """Return the spec dictionary for a given argument name."""
        if isinstance(argdefs, dict):
            return argdefs.get(name, {})
        # args is a list of one-item dicts
        for item in argdefs:
            if name in item:
                return item[name]
        return {}

    length_keys = ('maxlength', 'maxlen', 'max_length', 'max-length')

    for arg_name, arg_value in args.items():
        spec = _get_spec(arg_name)
        if not spec:
            continue
        maxlen = None
        for key in length_keys:
            if key in spec:
                maxlen = spec[key]
                break
        if maxlen is None:
            continue

        # Validate that maxlen is a non-negative integer
        if not isinstance(maxlen, int):
            raise TypeError(
                f"Maximum length for argument '{arg_name}' must be an integer "
                f"(got {type(maxlen).__name__} instead)"
            )
        if maxlen < 0:
            raise ValueError(
                f"Maximum length for argument '{arg_name}' must be non-negative "
                f"(got {maxlen})"
            )

        # If the argument value has a length, check against maxlen
        try:
            length = len(arg_value)
        except TypeError:
            # If the value has no length, skip the check
            continue

        if length > maxlen:
            raise ValueError(
                f"Argument '{arg_name}' length {length} exceeds maximum of {maxlen}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument specifications (if any) from parsed YAML
    arg_specs = getattr(self, 'parsed_yaml', {}).get('args', {})
    for arg_name, value in args.items():
        # Skip if no value provided
        if value is None:
            continue
        # Find any length constraint for this argument
        spec = arg_specs.get(arg_name, {})
        # Common keys that may contain a max length
        max_len = None
        for key in ('length', 'len', 'max_length', 'max'):
            if key in spec:
                max_len = spec[key]
                break
        # If there's no length constraint defined, skip this argument
        if max_len is None:
            continue
        # Validate that the constraint is an integer
        if not isinstance(max_len, int):
            raise TypeError(
                f"Specified max length for argument '{arg_name}' "
                f"must be int, got {type(max_len).__name__}"
            )
        # Ensure that the value has a length; if not, ignore
        try:
            val_len = len(value)
        except TypeError:
            continue  # value has no length, so skip check
        # Raise an error if the value exceeds the specified length
        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds "
                f"maximum allowed {max_len}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"'args' must be a dict (got {type(args).__name__})")

    for arg_name, arg_attrs in args.items():
        # If arg_attrs is not a dict, skip validation
        if not isinstance(arg_attrs, dict):
            continue

        # Retrieve 'max_length' and 'value' if present
        max_length = arg_attrs.get('max_length')
        value = arg_attrs.get('value')

        # Skip if no length constraint or no value to check
        if max_length is None or value is None:
            continue

        # Validate max_length is a non-negative integer
        if not isinstance(max_length, Integral):
            raise TypeError(
                f"max_length for argument '{arg_name}' must be an integer "
                f"(got {type(max_length).__name__})"
            )
        if max_length < 0:
            raise ValueError(
                f"max_length for argument '{arg_name}' must be non-negative "
                f"(got {max_length})"
            )

        # Ensure the value is a type that supports len()
        if not hasattr(value, "__len__"):
            raise TypeError(
                f"value for argument '{arg_name}' must be a sized object "
                f"(got {type(value).__name__})"
            )

        if len(value) > max_length:
            raise ValueError(
                f"Argument '{arg_name}' length {len(value)} exceeds "
                f"maximum allowed {max_length}"
            )
    return None

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    spec = self.parsed_yaml.get('args', {})
    if not isinstance(spec, (dict, list)):
        raise TypeError("args spec must be a dict or a list")
    if isinstance(spec, dict):
        items = spec.items()
    else:
        # spec is a list where each item is a dict with one key
        items = []
        for item in spec:
            if not isinstance(item, dict):
                continue
            try:
                key, value = list(item.items())[0]
            except Exception:
                continue
            items.append((key, value))

    for arg_name, attrs in items:
        if not isinstance(attrs, dict):
            continue
        # support different key names for length
        maxlen = attrs.get('len') or attrs.get('maxlen') or attrs.get('maxlength')
        if maxlen is None:
            continue
        if not isinstance(maxlen, int):
            raise TypeError(
                f"max length for argument '{arg_name}' must be an int, got {type(maxlen).__name__}")
        if arg_name not in args:
            continue
        val = args[arg_name]
        try:
            length = len(val)
        except Exception as exc:
            raise ValueError(
                f"Argument '{arg_name}' does not support len()") from exc
        if length > maxlen:
            raise ValueError(
                f"Argument '{arg_name}' too long: {length} > {maxlen}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # If the object does not expose a mapping of choices, just skip validation.
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        return

    for arg_name, value in args.items():
        if arg_name not in self.choices:
            continue

        allowed = self.choices[arg_name]
        try:
            # ``allowed`` may be a list, tuple, set or any iterable.
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of: {allowed!r}"
                )
        except TypeError:
            # ``allowed`` is not a proper collection; treat as invalid.
            raise ValueError(
                f"Cannot validate choices for argument '{arg_name}'; "
                f"invalid choices container: {allowed!r}"
            ) from None

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # argument definitions from the parsed yaml
    arg_defs = self.parsed_yaml.get('args', {})
    if not isinstance(arg_defs, dict):
        return

    for name, value in args.items():
        if name not in arg_defs:
            continue
        definition = arg_defs[name]
        # Only check if there is a 'choices' entry
        choices = definition.get('choices')
        if not choices:
            continue

        # Normalise a dict of choices to a list of keys
        if isinstance(choices, dict):
            allowed = list(choices.keys())
        elif isinstance(choices, (list, tuple)):
            allowed = list(choices)
        else:
            # unsupported choice type, skip validation
            continue

        if value not in allowed:
            msg = (
                f"Invalid value for argument `{name}`: `{value}`. "
                f"Allowed values are: {allowed}."
            )
            raise ValueError(msg)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"Expected `args` to be a dict, got {type(args).__name__}")
    # If no choice definitions exist, nothing to validate.
    choices = getattr(self, "choices", None)
    if not isinstance(choices, dict):
