                    f"Invalid value for choice argument `{arg_name}`: {arg_value!r}. "
                    f"Expected one of {valid_values!r}."
                )
        else:
            # If the choices definition is not a standard iterable, skip validation.
            continue

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    # `_choices` should be a mapping of argument name -> iterable of allowed values.
    choices_map = getattr(self, "_choices", {})
    for arg_name, allowed in choices_map.items():
        if arg_name in args:
            val = args[arg_name]
            # If allowed is an iterable of choice values, ensure the argument value is among them.
            if isinstance(allowed, (list, tuple, set)):
                if val not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {val!r} not in allowed choices {allowed}"
                    )
            else:
                # If `allowed` is not iterable, ignore or treat as no constraints.
                continue

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not args:
        return

    # Retrieve the argument definitions from the parsed YAML,
    # which may be a dict or a list of dicts.
    arg_defs = self.parsed_yaml.get('args')
    if not arg_defs:
        return

    # Normalize the argument definitions to a mapping of arg name -> spec.
    normalized_defs = {}
    if isinstance(arg_defs, dict):
        normalized_defs = arg_defs
    elif isinstance(arg_defs, list):
        for item in arg_defs:
            if isinstance(item, dict):
                # Each item in the list should be a mapping with one key.
                for key, spec in item.items():
                    normalized_defs[key] = spec
    else:
        # Unsupported format; skip validation.
        return

    for arg_name, value in args.items():
        spec = normalized_defs.get(arg_name)
        if not spec:
            continue  # Unknown argument; skip validation here.

        # The spec may itself contain a 'choices' key indicating allowed values.
        choices = spec.get('choices') if isinstance(spec, dict) else None
        if not choices:
            # No explicit choices defined; nothing to validate.
            continue

        # Allow values that are lists/tuples of choices if the argument
        # is defined as multi-valued. In that case every element must
        # be within the allowed choices.
        if isinstance(value, (list, tuple)):
            for elem in value:
                if elem not in choices:
                    raise ValueError(
                        f"Invalid value '{elem}' for argument '{arg_name}'. "
                        f"Allowed choices are: {choices}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{arg_name}'. "
                    f"Allowed choices are: {choices}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the instance has the required bounds attributes.
    if not hasattr(self, "min_") or not hasattr(self, "max_"):
        raise AttributeError(
            "Instance must have 'min_' and 'max_' attributes for validation"
        )

    min_val = self.min_
    max_val = self.max_

    # If a single value is provided instead of an iterable, treat it as a list.
    try:
        iter(args)
    except TypeError:
        args = [args]

    for val in args:
        try:
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument {val!r} is out of range [{min_val}, {max_val}]"
                )
        except TypeError:
            # The comparison failed because values aren't comparable
            raise TypeError(
                f"Cannot compare argument {val!r} with bounds {min_val!r} and {max_val!r}"
            )
    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments, expected to be a mapping of names to values.
    :return: args if all values are within their defined bounds.
    :raise ValueError: If any value is outside its minimum or maximum boundary.
    :raise TypeError: If args is not a mapping or if a value cannot be compared.
    """
    # Ensure args is a mapping
    if not hasattr(args, 'items'):
        raise TypeError("args must be a mapping of argument names to values")

    # Retrieve per-argument constraints from the instance, if provided
    min_constraints = getattr(self, 'min_', {})
    max_constraints = getattr(self, 'max_', {})

    # Validate each argument value
    for name, value in args.items():
        # Skip if no constraints are defined for this argument
        if name not in min_constraints and name not in max_constraints:
            continue

        # Compare against minimum, if defined
        min_val = min_constraints.get(name)
        if min_val is not None:
            try:
                if value < min_val:
                    raise ValueError(f"Argument '{name}'={value} is less than minimum allowed {min_val}")
            except TypeError as exc:
                raise TypeError(f"Cannot compare value of argument '{name}' with minimum bound {min_val}") from exc

        # Compare against maximum, if defined
        max_val = max_constraints.get(name)
        if max_val is not None:
            try:
                if value > max_val:
                    raise ValueError(f"Argument '{name}'={value} is greater than maximum allowed {max_val}")
            except TypeError as exc:
                raise TypeError(f"Cannot compare value of argument '{name}' with maximum bound {max_val}") from exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Expected to be a mapping of argument names to values.
    :return: The original ``args`` mapping if all values are within their bounds.
    :raises TypeError: If ``args`` is not a mapping or value comparisons fail.
    :raises ValueError: If a value is outside its defined bounds.
    """
    # Ensure we received a mapping of arguments
    if not hasattr(args, "items"):
        raise TypeError(f"Expected a mapping for args, got {type(args).__name__}")

    for name, value in args.items():
        # Retrieve optional bounds from the instance. Conventional names are
        # ``min_<name>`` and ``max_<name>`` but you can adapt this as needed.
        min_val = getattr(self, f"min_{name}", None)
        max_val = getattr(self, f"max_{name}", None)

        # If a bound is defined but the value cannot be compared, raise a clear error
        try:
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument '{name}'={value} is below its minimum {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument '{name}'={value} exceeds its maximum {max_val}"
                )
        except TypeError as exc:
            # Provide a more descriptive message for comparison errors
            raise TypeError(
                f"Cannot compare argument '{name}'={value} with bounds "
                f"({min_val}, {max_val})"
            ) from exc

    return args

def create_complex_argument_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance or factory
    """
    # Validate inputs
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # If a custom parsing function is provided, use it directly
    parse_func = spec_option.get("parse_func")
    if callable(parse_func):
        return parse_func

    # If a class is directly supplied in the spec, use it
    cls = spec_option.get("class")
    if isinstance(cls, type):
        return cls

    # If the spec defines fields, create a lightweight NamedTuple-like parser
    fields = spec_option.get("fields")
    if isinstance(fields, (list, tuple)):
        field_types = spec_option.get("field_types", [])
        # Ensure field_types has a type for each field, default to str
        if not isinstance(field_types, (list, tuple)):
            raise TypeError("field_types must be a list or tuple of types")
        if len(field_types) != len(fields):
            # Pad with str if not enough types specified
            field_types = list(field_types) + [str] * (len(fields) - len(field_types))

        # Create the namedtuple type
        ComplexStruct = type(type_name, (tuple,), {"__slots__": (), "__new__": type("new", (tuple,), {
            "__new__": lambda cls, *args: tuple.__new__(cls, args)
        })["__new__"]})

        # Alternative simpler approach: use collections.namedtuple
        try:
            from collections import namedtuple
            ComplexStruct = namedtuple(type_name, fields)
        except Exception as exc:
            raise RuntimeError(f"Failed to create namedtuple {type_name}: {exc}") from exc

        def parser(value):
            """
            Parse a comma-separated string into the ComplexStruct.
            """
            parts = [p.strip() for p in value.split(",")]
            if len(parts) != len(fields):
                raise ValueError(
                    f"Expected {len(fields)} values for {option_name} of type {type_name}, "
                    f"but got {len(parts)}: '{value}'"
                )
            converted = []
            for part, typ in zip(parts, field_types):
                try:
                    converted.append(typ(part))
                except Exception as exc:
                    raise ValueError(
                        f"Could not convert '{part}' to {typ.__name__} for field '{option_name}'"
                    ) from exc
            return ComplexStruct(*converted)

        parser.__name__ = f"parse_{type_name}"
        return parser

    # Fallback: If spec contains '__type__', try dynamic loading
    if "__type__" in spec_option:
        try:
            fqdn = spec_option["__type__"]
            factory = self.load_name(fqdn)  # assumes a loader method on self
            args = spec_option.get("__args__", [])
            kwargs = {k: v for k, v in spec_option.items() if k not in ("__type__", "__args__")}
            return factory(*args, **kwargs)
        except Exception as exc:
            raise RuntimeError(f"Could not construct type from spec {spec_option}: {exc}") from exc

    # If nothing matches, raise an informative error
    raise ValueError(
        f"Unable to create a complex argument type for {option_name}. "
        f"Spec must include 'parse_func', 'class', 'fields', or '__type__'."
    )

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Basic validation of inputs
        if not isinstance(subcommand, str):
            raise TypeError("subcommand must be a string")
        if not isinstance(type_name, str):
            raise TypeError("type_name must be a string")
        if not isinstance(option_name, str):
            raise TypeError("option_name must be a string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")

        # Expecting a 'fields' entry containing field definitions
        fields = spec_option.get("fields")
        if not isinstance(fields, dict):
            raise ValueError("spec_option must contain a 'fields' dictionary")

        if not fields:
            raise ValueError("spec_option 'fields' dictionary cannot be empty")

        # Create a namedtuple type dynamically
        from collections import namedtuple
        field_names = list(fields.keys())
        ComplexType = namedtuple(type_name, field_names)

        # Optionally populate default values if provided
        defaults = spec_option.get("defaults", {})
        if defaults:
            if not isinstance(defaults, dict):
                raise TypeError("defaults must be a dictionary")
            # Ensure defaults correspond to defined fields
            for k in defaults:
                if k not in fields:
                    raise ValueError(f"Default field '{k}' not defined in fields")

        return ComplexType
    except Exception as exc:
        raise RuntimeError(
            f"Failed to create complex argument type '{type_name}' for subcommand "
            f"'{subcommand}': {exc}"
        ) from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    try:
        if not isinstance(subcommand, str) or not subcommand.strip():
            raise ValueError("subcommand must be a non‑empty string")
        if not isinstance(type_name, str) or not type_name.strip():
            raise ValueError("type_name must be a non‑empty string")
        if not isinstance(option_name, str) or not option_name.strip():
            raise ValueError("option_name must be a non‑empty string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict")

        # Define a lightweight complex argument class on the fly
        class _ComplexArgument:
            """Simple container for complex argument metadata."""

            def __init__(self, subcmd, type_name, opt_name, spec):
                self.subcommand = subcmd
                self.type_name = type_name
                self.option_name = opt_name
                self.spec_option = spec

            def __repr__(self):
                return (
                    f"<{self.__class__.__name__} "
                    f"subcommand={self.subcommand!r} "
                    f"type_name={self.type_name!r} "
                    f"option_name={self.option_name!r} "
                    f"spec_option={self.spec_option!r}>"
                )

        # Optional sanity‑check: ensure that spec_option contains at least a description
        if "description" not in spec_option:
            raise KeyError("spec_option missing required key 'description'")

        # Instantiate and return
        return _ComplexArgument(subcommand, type_name, option_name, spec_option)

    except Exception as exc:
        raise ValueError(f"Failed to create complex argument type: {exc}") from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate required arguments
    if not isinstance(subcommand, str) or not subcommand.strip():
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name.strip():
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name.strip():
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary containing specification parameters")

    # Resolve the complex type class.  Prefer a cached registry if available,
    # otherwise attempt to load by fully‑qualified name.
    try:
        # Common pattern: self._complex_type_registry is a mapping
        # from type name to class
        type_cls = self._complex_type_registry[type_name]
    except AttributeError:
        # No registry defined – fall back to loading by name
        type_cls = None
    except KeyError:
        type_cls = None

    if type_cls is None:
        # Attempt to import the class by a fully qualified name.
        # Expect type_name to be something like 'module.ClassName'.
        if "." in type_name:
            mod_name, cls_name = type_name.rsplit(".", 1)
            try:
                module = __import__(mod_name, fromlist=[cls_name])
                type_cls = getattr(module, cls_name)
            except (ImportError, AttributeError) as exc:
                raise ImportError(f"Could not load complex type '{type_name}': {exc}") from exc
        else:
            raise KeyError(f"Complex type '{type_name}' not registered and cannot be imported")

    # Instantiate the complex type
    try:
        # The constructor is assumed to accept the option name as the first
        # positional argument and then keyword arguments from spec_option.
        instance = type_cls(option_name, **spec_option)
    except TypeError as exc:
        raise TypeError(
            f"Failed to instantiate complex type '{type_name}' with option_name='{option_name}': {exc}"
        ) from exc

    # Optional: perform a sanity check that the instance is of the expected type
    if not isinstance(instance, type_cls):
        raise TypeError(
            f"Instance created from '{type_name}' is not an instance of the expected class"
        )

    return instance

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare containers for the separated arguments
    control_args = {}
    nested_args = {}

    # Basic validation and normalisation of the input
    try:
        if args is None:
            return control_args, nested_args

        # If args is a dict, iterate over its items
        if isinstance(args, dict):
            items = args.items()

        # If args is a list of 2‑tuples, transform it to a dict
        elif isinstance(args, list):
            normalised = {}
            for entry in args:
                if isinstance(entry, (tuple, list)) and len(entry) == 2:
                    normalised[entry[0]] = entry[1]
                else:
                    raise ValueError(
                        "List entries must be two‑item key/value pairs")
            items = normalised.items()

        else:
            raise TypeError("args must be a dict or list of pairs")

        # Splitting logic
        for key, value in items:
            # Skip missing values
            if value is None:
                continue

            # Determine if the argument is a control argument.
            # A very simple heuristic: keys starting with '_' or 'control_'
            # are treated as control arguments. Extend this logic if the
            # calling code defines a more explicit list.
            is_control = (
                isinstance(key, str) and (
                    key.startswith('_')
                    or key.lower().startswith('control_')
                )
            )

            if is_control:
                control_args[key] = value
            else:
                # All other keys are treated as nested or custom arguments
                nested_args[key] = value

        return control_args, nested_args

    except Exception as exc:
        # In the unlikely event of an error, return empty dicts to avoid
        # catastrophic failure in the caller. The caller can decide if the
        # error should be surfaced.
        return {}, {}

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Helper to flatten a dict into dot notation
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, key))
            else:
                flat[key] = v
        return flat

    # Defensive type checking
    if args is None:
        return {}, {}
    if not isinstance(args, dict):
        # Attempt to convert iterable of key/value pairs
        try:
            args = dict(args)
        except Exception:
            raise TypeError("Expected 'args' to be a dict or key/value iterable")

    # Determine control arguments
    control_keys = set()
    try:
        # If the instance defines a set/list of known control keys, use it.
        known_control = getattr(self, "control_args", set())
        if isinstance(known_control, (list, set, tuple)):
            control_keys.update(known_control)
    except Exception:
        # Ignore missing attribute
        pass

    # By convention, prefixed with an underscore are also control
    for k in args:
        if k.startswith("_"):
            control_keys.add(k)

    control_args = {k: v for k, v in args.items() if k in control_keys}
    nested_args_raw = {k: v for k, v in args.items() if k not in control_keys}

    # Flatten nested arguments (if any values are dicts)
    nested_args = {}
    for k, v in nested_args_raw.items():
        if isinstance(v, dict):
            flattened = _flatten(v, k)
            nested_args.update(flattened)
        else:
            nested_args[k] = v

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :returns: Dictionary extended with extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    result = dict(vars_dict)

    if extra_vars is None:
        return result

    # Handle a single dictionary
    if isinstance(extra_vars, dict):
        result.update(extra_vars)
        return result

    # Handle a list of items
    if isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                result.update(item)
            elif isinstance(item, str):
                if '=' in item:
                    key, val = item.split('=', 1)
                    result[key] = val
            else:
                # unsupported item type, ignore or raise
                raise ValueError(f"Unsupported extra var type: {type(item)}")
        return result

    # Handle a string like "key=value"
    if isinstance(extra_vars, str):
        if '=' in extra_vars:
            key, val = extra_vars.split('=', 1)
            result[key] = val
        else:
            raise ValueError("String extra vars must be in 'key=value' format")
        return result

    # Unsupported type for extra_vars
    raise ValueError(f"Unsupported type for extra_vars: {type(extra_vars)}")

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # Ensure we have a dictionary to work with
        if vars_dict is None:
            vars_dict = {}
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        # No extra variables to merge
        if not extra_vars:
            return vars_dict

        # Validate the structure of extra_vars
        if not isinstance(extra_vars, list):
            raise TypeError("extra_vars must be a list of dictionaries")

        # Merge each dictionary, overriding existing keys
        for extra in extra_vars:
            if extra is None:
                continue
            if not isinstance(extra, dict):
                raise TypeError("Each element in extra_vars must be a dictionary")
            vars_dict.update(extra)

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated vars_dict
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict
    # If extra_vars is a dict itself, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict
    # If extra_vars is iterable but not a string
    try:
        iter(extra_vars)
    except TypeError:
        raise TypeError("extra_vars must be dict or iterable of key-value pairs")
    # Process each element
    for item in extra_vars:
        # If item is a dict, merge its items
        if isinstance(item, dict):
            vars_dict.update(item)
        # If item is a tuple/list of length 2, treat as key-value pair
        elif isinstance(item, (list, tuple)) and len(item) == 2:
            key, value = item
            vars_dict[key] = value
        else:
            # Unsupported item type; skip or raise
            continue
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import subprocess

    if not playbook_path or not os.path.isfile(playbook_path):
        raise ValueError(f"Playbook file does not exist: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        try:
            # Accept an integer verbosity level (0-5)
            level = int(verbose)
            if level > 0:
                cmd.append("-" + "v" * level)
        except (ValueError, TypeError):
            # If verbose is not an integer, ignore or log
            pass

    # Additional ansible-playbook args
    if ansible_args:
        for key, value in ansible_args.items():
            if not key.startswith("--"):
                key = f"--{key}"
            if value is True:
                # Flag without value
                cmd.append(key)
            elif value is False or value is None:
                # Skip false or None values
                continue
            else:
                cmd.extend([key, str(value)])

    # Extra vars
    if extra_vars:
        # Serialize dict to JSON and pass via --extra-vars
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=False)
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook executable not found. Ensure Ansible is installed and in PATH.")
    except Exception as exc:
        raise RuntimeError(f"Error executing ansible-playbook: {exc}") from exc

    if result.returncode != 0:
        error_msg = f"ansible-playbook returned exit code {result.returncode}\n"
        if result.stderr:
            error_msg += f"stderr: {result.stderr}"
        raise RuntimeError(error_msg)

    return result.stdout.strip()

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build base command
    cmd = ["ansible-playbook"]

    # Verbosity handling
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                # Cap verbosity at 5
                cmd.append("-" + "v" * min(verbose, 5))
        elif isinstance(verbose, str):
            # accept strings like "-v" "-vv"
            if not verbose.startswith("--"):
                cmd.append(verbose)

    # Append any additional ansible-playbook arguments
    if ansible_args:
        for key, val in ansible_args.items():
            opt = f"--{key}"
            # Skip False or None
            if val is False or val is None:
                continue
            # Boolean flag
            if val is True:
                cmd.append(opt)
                continue
            # For list values join with commas
            if isinstance(val, (list, tuple)):
                val_str = ",".join(str(x) for x in val)
            else:
                val_str = str(val)
            cmd.append(f"{opt}={val_str}")

    # Include extra-vars if provided
    if extra_vars:
        try:
            import json
            ev_str = json.dumps(extra_vars, separators=(",", ":"))
        except Exception:
            ev_str = str(extra_vars)
        cmd.extend(["--extra-vars", ev_str])

    # Resolve playbook path relative to workspace if possible
    try:
        workspace_root = getattr(ir_workspace, "root", None) or getattr(ir_workspace, "path", None)
        if workspace_root:
            playbook_full = os.path.join(workspace_root, playbook_path)
        else:
            playbook_full = playbook_path
    except Exception:
        playbook_full = playbook_path

    cmd.append(playbook_full)

    # Execute the command and handle output
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout
    except subprocess.CalledProcessError as exc:
        err_msg = (
            f"Ansible playbook '{playbook_full}' failed with exit code "
            f"{exc.returncode}"
        )
        if exc.stderr:
            err_msg += f"\nStderr: {exc.stderr.strip()}"
        raise RuntimeError(err_msg) from exc
    except FileNotFoundError:
        raise RuntimeError("The 'ansible-playbook' command was not found in the PATH")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Resolve the playbook path, ensure it exists
    abs_playbook = os.path.abspath(playbook_path)
    if not os.path.isfile(abs_playbook):
        raise FileNotFoundError(f"Playbook not found: {abs_playbook}")

    # Base command
    cmd = ["ansible-playbook"]

    # Handle verbosity: use -v, -vv, etc.
    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non-negative integer")
        if verbose > 0:
            cmd.append("-" + ("v" * verbose))

    # Custom ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if key.startswith("-"):
                arg = key
            else:
                arg = f"--{key.replace('_', '-')}"
            # Flags without a value
            if isinstance(value, bool):
                if value:
                    cmd.append(arg)
                # skip false flags
                continue
            if value is None:
                cmd.append(arg)
                continue
            if isinstance(value, list):
                # join list items with space
                for item in value:
                    cmd.extend([arg, str(item)])
            else:
                cmd.extend([arg, str(value)])

    # Pass extra-vars if provided
    if extra_vars:
        try:
            import json
        except ImportError:
            raise RuntimeError("json module not available for extra_vars serialization")
        cmd.extend(["--extra-vars", json.dumps(extra_vars, separators=(',', ':'))])

    # Append the playbook to run
    cmd.append(abs_playbook)

    # Execute the command
    try:
        result = subprocess.run(cmd, text=True, capture_output=True, check=False)
    except OSError as exc:
        raise RuntimeError(f"Failed to start ansible-playbook: {exc}") from exc

    # If ansible reported an error, raise with stdout/stderr
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"Stdout: {result.stdout}\n"
            f"Stderr: {result.stderr}"
        )

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Known type mappings for each parser. Extend this map as needed.
    known_type_map = {
        'main': {
            'port': int,
            'verbose': bool,
            'debug': bool,
            'timeout': int
        },
        'virsh': {
            'timeout': int,
            'force': bool
        },
        'ospd': {
            'threads': int,
            'enable': bool
        }
    }

    parser_map = known_type_map.get(parser_name, {})

    for key, value in values_dict.items():
        # Skip None values – leave as is
        if value is None:
            continue

        # If parser provides explicit type, use it
        if key in parser_map:
            try:
                values_dict[key] = parser_map[key](value)
                continue
            except Exception:
                # If conversion fails, fall back to generic rules below
                pass

        # Generic conversion for strings
        if isinstance(value, str):
            lowered = value.lower()

            # Boolean values
            if lowered in ('true', 'false'):
                values_dict[key] = lowered == 'true'
                continue

            # Try integer conversion
            try:
                values_dict[key] = int(value)
                continue
            except ValueError:
                pass

            # Try float conversion
            try:
                values_dict[key] = float(value)
                continue
            except ValueError:
                pass

        # Fall back: keep original value (likely already correct type)
        # (no modification)

    # The dict is modified in place; returning it is optional but convenient.
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser object for the given command name.
    # Assume parsers are stored in a dict attribute ``self.parsers``.
    parser = getattr(self, "parsers", {}).get(parser_name)
    if parser is None:
        # If no parser is found, there's nothing to convert.
        return

    # Build a mapping from argument dest to its expected type.
    # ``argparse`` stores action objects under `parser._actions`.
    type_map = {}
    actions = getattr(parser, "_actions", [])
    for action in actions:
        dest = getattr(action, "dest", None)
        if dest is None:
            continue
        # ``action.type`` is the function used for type conversion.
        action_type = getattr(action, "type", None)
        type_map[dest] = action_type

    # Convert each value in the dict if we know its expected type.
    for key, raw_value in list(values_dict.items()):
        if key not in type_map:
            continue
        typ = type_map[key]
        if typ is None or raw_value is None:
            continue
        # Only attempt conversion for string values (CLI args are strings)
        if isinstance(raw_value, str):
            try:
                if typ is bool:
                    # Interpret common truthy/falsy string representations.
                    if raw_value.lower() in ("true", "1", "yes", "on"):
                        values_dict[key] = True
                    elif raw_value.lower() in ("false", "0", "no", "off"):
                        values_dict[key] = False
                    else:
                        # If it doesn't look like a boolean, leave unchanged.
                        continue
                else:
                    values_dict[key] = typ(raw_value)
            except Exception:
                # If conversion fails, leave the original value unchanged.
                pass

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    # locate the parser object for the given command name
    parser = None
    if hasattr(self, "parsers") and isinstance(self.parsers, dict):
        parser = self.parsers.get(parser_name)
    if parser is None:
        raise ValueError(f"Parser for '{parser_name}' not found.")
    # build mapping from dest name to conversion function
    dest_to_type = {}
    for action in getattr(parser, "_actions", []):
        if action.dest and action.type:
            dest_to_type[action.dest] = action.type
    # helper to convert boolean strings
    def _parse_bool(val):
        if isinstance(val, bool):
            return val
        if isinstance(val, str):
            low = val.lower()
            if low in ("true", "yes", "1", "t", "y"):
                return True
            if low in ("false", "no", "0", "f", "n"):
                return False
        raise ValueError(f"Cannot convert {val!r} to bool")
    # recursively convert nested dictionaries
    def _convert(d):
        for k, v in list(d.items()):
            if isinstance(v, dict):
                _convert(v)
                continue
            if k in dest_to_type:
                conv = dest_to_type[k]
                try:
                    if conv is bool:
                        d[k] = _parse_bool(v)
                    else:
                        d[k] = conv(v)
                except Exception as exc:
                    raise ValueError(
                        f"Argument '{k}' with value {v!r} "
                        f"cannot be converted using {conv}: {exc}"
                    ) from exc
    _convert(values_dict)
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key="", sep="_"):
        flattened = {}
        for key, value in d.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                flattened.update(_flatten(value, new_key, sep=sep))
            elif isinstance(value, list):
                # Convert lists to comma‑separated strings for flattening
                flattened[new_key] = json.dumps(value)
            else:
                flattened[new_key] = value
        return flattened

    # Common filenames where a plugin might store its metadata
    possible_files = ("plugin.json", "metadata.json", "manifest.json")
    spec_path = None
    for fname in possible_files:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        raise FileNotFoundError(
            f"No plugin spec file found in '{plugin_dir}'. "
            f"Tried: {', '.join(possible_files)}"
        )

    try:
        with open(spec_path, "r", encoding="utf-8") as fh:
            spec = json.load(fh)
    except Exception as exc:
        raise ValueError(f"Failed to read or parse plugin spec from '{spec_path}': {exc}")

    if not isinstance(spec, dict):
        raise ValueError(f"The plugin spec at '{spec_path}' is not a JSON object (dict).")

    return _flatten(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
