    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    def _flatten(d, parent_key=''):
        """Recursively flattens a nested dictionary."""
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            elif isinstance(v, list):
                # Flatten lists by indexing elements
                for i, elem in enumerate(v):
                    list_key = f"{new_key}.{i}"
                    if isinstance(elem, (dict, list)):
                        items.update(_flatten(elem, list_key))
                    else:
                        items[list_key] = elem
            else:
                items[new_key] = v
        return items

    spec_path_json = os.path.join(plugin_dir, 'plugin.json')
