    # Helper to add spec argument to a parser
    def _add_spec_arg(parser):
        try:
            parser.add_argument(
                '--spec',
                type=str,
                default='',
                help='Specification parameter for the command'
            )
        except Exception as exc:
            raise RuntimeError(f"Failed to add '--spec' to parser {parser}: {exc}") from exc

    # Case 1: root_subparsers is an iterable of parsers
    if hasattr(root_subparsers, '__iter__') and not isinstance(root_subparsers, (str, bytes)):
        for p in root_subparsers:
            if hasattr(p, 'add_argument'):
                _add_spec_arg(p)
            else:
                raise TypeError(f"Expected parser objects, got {type(p)}")
    # Case 2: root_subparsers is a single parser
    elif hasattr(root_subparsers, 'add_argument'):
        _add_spec_arg(root_subparsers)
    else:
        raise TypeError(f"Unsupported root_subparsers type: {type(root_subparsers)}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    try:
        import os
        path_abs = os.path.abspath(path)
        root_abs = os.path.abspath(root)
        if not path_abs.startswith(root_abs):
            raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
        rel = path_abs[len(root_abs):]
        if rel.startswith(os.sep):
            rel = rel[1:]
        if rel == '':
            rel = '.'
        return rel
    except Exception as e:
        raise e

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    # Normalize paths to a consistent absolute form
    norm_path = os.path.abspath(os.path.normpath(path))
    norm_root = os.path.abspath(os.path.normpath(root))
    try:
        # Compute relative path from root to path
        relative = os.path.relpath(norm_path, norm_root)
        # If relative traversal goes above root, root is not a prefix
        if relative == '.' or relative.startswith(os.pardir + os.sep) or relative == os.pardir:
            raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
        # If the path is exactly the root, return empty string
        if relative == '.':
            return ''
        return relative
    except Exception as exc:
        raise ValueError(f"Failed to strip root '{root}' from path '{path}': {exc}") from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")

    root_abs = os.path.abspath(os.path.normpath(root))
    path_abs = os.path.abspath(os.path.normpath(path))

    # Ensure that root is a prefix of path
    try:
        # os.path.commonpath will raise ValueError if paths are on different drives (Windows)
        common = os.path.commonpath([path_abs, root_abs])
    except ValueError as e:
        raise ValueError(
            f"Unable to compare path '{path_abs}' and root '{root_abs}': {e}"
        )

    if common != root_abs:
        raise ValueError(
            f"Root path '{root_abs}' is not a prefix of '{path_abs}'"
        )

    # Derive relative path and perform final sanity check
    relative = os.path.relpath(path_abs, root_abs)

    # os.path.relpath should never return an absolute path in this case,
    # but guard against unexpected results
    if os.path.isabs(relative) or relative.startswith(".."):
        raise ValueError(
            f"Resulting relative path '{relative}' is invalid for root '{root_abs}' and path '{path_abs}'"
        )

    return relative
